#define ttisboolean(o)		checktype((o), LUA_TBOOLEAN)
#define ttisfalse(o)		checktag((o), LUA_VFALSE)
#define ttistrue(o)		checktag((o), LUA_VTRUE)

#define ttislightuserdata(o)	checktag((o), LUA_VLIGHTUSERDATA)

#define ttisfloat(o)		checktag((o), LUA_VNUMFLT)
#define ttisinteger(o)		checktag((o), LUA_VNUMINT)
#define ttisnumber(o)		checktype((o), LUA_TNUMBER)

#define ttisshrstr(o)		checktag((o), LUA_VSHRSTR)
#define ttislngstr(o)		checktag((o), LUA_VLNGSTR)
#define ttisstring(o)		checktype((o), LUA_TSTRING)

#define ttisfunction(o)		checktype(o, LUA_TFUNCTION)
#define ttisclosure(o)		((rawtt(o) & 0x1F) == LUA_VLCL)
#define ttisLclosure(o)		checktag((o), LUA_VLCL)
#define ttiscclosure(o)		checktag((o), LUA_VCCL)
#define ttisCclosure(o)		checktag((o), LUA_VCCL)
#define ttislcf(o)		checktag((o), LUA_VLCCL)

#define ttisfulluserdata(o)	checktag((o), LUA_VUSERDATA)
#define ttistable(o)		checktag((o), LUA_VTABLE)
#define ttisthread(o)		checktag((o), LUA_VTHREAD)
#define ttisdeadkey(o)		checktag((o), LUA_VDEADKEY)


