#define deadvalue(o)	check_exp(ttisdeadkey(o), cast_voidp(val_(o).gc))

#define l_isfalse(o)	(ttisnil(o) || ttisfalse(o))


#define iscollectable(o)	(rawtt(o) & BIT_ISCOLLECTABLE)


/* Macros for internal tests */

/* collectable object has the same tag as TValue */
