  { TValue *io = (obj); TString *x_ = (x); \
    val_(io).gc = obj2gco(x_); settt_(io, ctb(x_->tt)); \
    checkliveness(L,io); }

#define setuvalue(L,obj,x) \
  { TValue *io = (obj); Udata *x_ = (x); \
    val_(io).gc = obj2gco(x_); settt_(io, ctb(LUA_VUSERDATA)); \
    checkliveness(L,io); }

#define setthvalue(L,obj,x) \
  { TValue *io = (obj); lua_State *x_ = (x); \
    val_(io).gc = obj2gco(x_); settt_(io, ctb(LUA_VTHREAD)); \
    checkliveness(L,io); }

#define setclLvalue(L,obj,x) \
  { TValue *io = (obj); LClosure *x_ = (x); \
    val_(io).gc = obj2gco(x_); settt_(io, ctb(LUA_VLCL)); \
    checkliveness(L,io); }

#define setclCvalue(L,obj,x) \
  { TValue *io = (obj); CClosure *x_ = (x); \
    val_(io).gc = obj2gco(x_); settt_(io, ctb(LUA_VCCL)); \
    checkliveness(L,io); }

#define sethvalue(L,obj,x) \
  { TValue *io = (obj); Table *x_ = (x); \
    val_(io).gc = obj2gco(x_); settt_(io, ctb(LUA_VTABLE)); \
    checkliveness(L,io); }

#define setdeadvalue(obj)	settt_(obj, LUA_VDEADKEY)



#define setobj(L,obj1,obj2) \
	{ TValue *io1=(obj1); const TValue *io2=(obj2); \
          io1->tt_ = io2->tt_; io1->value_ = io2->value_; \
	  (void)L; checkliveness(L,io1); }


/*
** Different types of assignments, according to source
*/

/* from stack to stack */
#define setobjs2s(L,o1,o2)	setobj(L,s2v(o1),s2v(o2))
/* to stack (not from same stack) */
#define setobj2s(L,o1,o2)	setobj(L,s2v(o1),o2)
/* from table to same table */
#define setobjt2t	setobj
/* to new object */
#define setobj2n	setobj
/* to table (define it as an expression to be used with conditional macros */
#define setobj2t(L,o1,o2)  ((void)L, *(o1) = *(o2), checkliveness(L,(o1)))


/*
** Entries in the Lua stack
*/
typedef union StackValue {
  TValue val;
} StackValue;


/* index to stack elements */
typedef StackValue *StkId;

/* convert a 'StackValue' to a 'TValue' */
#define s2v(o)	(&(o)->val)



/*
** {======================================================
** Types and sizes of basic GC objects
** =======================================================
*/


/*
** Common Header for all collectable objects (in macro form, to be
** included in other objects)
*/
#define CommonHeader	struct GCObject *next; lu_byte tt; lu_byte marked


/* Common type for all collectable objects */
typedef struct GCObject {
  CommonHeader;
} GCObject;


/* Bit mark for collectable types */
#define BIT_ISCOLLECTABLE	(1 << 6)

#define iscollectable(o)	(rawtt(o) & BIT_ISCOLLECTABLE)

/* mark a tag as collectable */
#define ctb(t)			((t) | BIT_ISCOLLECTABLE)

/* make a variant tag for a type */
#define makevariant(t,v)	((t) | ((v) << 4))


/*
** Macro to convert a Lua object into a GCObject
*/
#define obj2gco(v)	((GCObject *)(v))

/* macro to convert a GCObject into a specific value */
#define gco2ts(v)	check_exp(novariant((v)->tt) == LUA_TSTRING, (TString *)(v))
#define gco2u(v)	check_exp((v)->tt == LUA_VUSERDATA, (Udata *)(v))
#define gco2lcl(v)	check_exp((v)->tt == LUA_VLCL, (LClosure *)(v))
#define gco2ccl(v)	check_exp((v)->tt == LUA_VCCL, (CClosure *)(v))
#define gco2cl(v)	check_exp(novariant((v)->tt) == LUA_TFUNCTION, (Closure *)(v))
#define gco2t(v)	check_exp((v)->tt == LUA_VTABLE, (Table *)(v))
#define gco2p(v)	check_exp((v)->tt == LUA_VPROTO, (Proto *)(v))
#define gco2th(v)	check_exp((v)->tt == LUA_VTHREAD, (lua_State *)(v))


/*
** String headers for string table
*/

/*
** Information about short strings:
** All short strings with the same content share the same TString.
** The 'extra' field is used to check if it is a keyword (for long
** strings, the field is used as a boolean for keeping the string
** in cache). The 'shrlen' field is the length for short strings.
*/
typedef struct TString {
  CommonHeader;
  lu_byte extra;  /* reserved words for short strings; "has hash" for longs */
  lu_byte shrlen;  /* length for short strings */
  unsigned int hash;
  union {
    size_t lnglen;  /* length for long strings */
    struct TString *hnext;  /* linked list for hash table */
  } u;
  char contents[1];
} TString;


/*
** Get the actual string (array of bytes) from a TString.
*/
#define getstr(ts)  ((ts)->contents)

/* get the actual string (array of bytes) from a Lua value */
#define svalue(o)       getstr(tsvalue(o))

/* get string length from 'TString *s' */
#define tsslen(s)	((s)->tt == LUA_VSHRSTR ? (s)->shrlen : (s)->u.lnglen)

/* get string length from 'TValue *o' */
#define vslen(o)	tsslen(tsvalue(o))


/*
** Header for userdata with user values;
** memory area follows the end of this structure.
*/
typedef struct Udata {
  CommonHeader;
  unsigned short nuvalue;  /* number of user values */
  size_t len;  /* number of bytes */
  struct Table *metatable;
  GCObject *gclist;
  union UValue {  /* (first) user value */
    TValue uv;
    LUAI_MAXALIGN;  /* ensures maximum alignment for udata bytes */
  } uv[1];
} Udata;


/*
** Header for userdata with no user values. These objects have no
** associated user values, so are simpler.
*/
typedef struct Udata0 {
  CommonHeader;
  unsigned short nuvalue;  /* number of user values */
  size_t len;  /* number of bytes */
  struct Table *metatable;
  union {
    LUAI_MAXALIGN;  /* ensures maximum alignment for udata bytes */
  } bindata;
} Udata0;


/* compute the offset of the memory area of a userdata */
#define udatamemoffset(nuv) \
	((nuv) == 0 ? offsetof(Udata0, bindata)  \
                    : offsetof(Udata, uv) + (sizeof(UValue) * (nuv)))

/* get the address of the memory block inside 'Udata' */
#define getudatamem(u)  (cast_charp(u) + udatamemoffset((u)->nuvalue))

/* compute the size of a userdata object */
#define sizeudata(nuv,nb)	(udatamemoffset(nuv) + (nb))


