	  io_->value_ = n_->u.key_val; io_->tt_ = n_->u.key_tt; \
	  checkliveness(L,io_); }


/*
** About 'alimit': if 'isrealasize(t)' is true, then 'alimit' is the
** real size of the array part. Otherwise, the array part has no elements
** past index 'alimit'; the actual size of the array is the index of the
** last element with a non-nil value in that range, or zero if no such
** element.
*/
#define BITRAS		(1 << 7)
#define isrealasize(t)		((t)->flags & BITRAS)
#define setrealasize(t)		((t)->flags |= BITRAS)
#define setnorealasize(t)	((t)->flags &= cast_byte(~BITRAS))


typedef struct Table {
  CommonHeader;
  lu_byte flags;  /* 1<<p means tagmethod(p) is not present */
  lu_byte lsizenode;  /* log2 of size of 'node' array */
  unsigned int alimit;  /* "limit" of 'array' part */
  TValue *array;  /* array part */
  Node *node;
