** Free memory
*/
void luaM_freemem (lua_State *L, void *block, size_t size) {
  global_State *g = G(L);
  lua_assert((size == 0) == (block == NULL));
  (*g->frealloc)(g->ud, block, size, 0);
  g->totalbytes -= cast(l_mem, size);
}


/*
** Generic allocation routine.
** If allocation fails while shrinking a block, do nothing (the block
** stays as it was).
*/
void *luaM_realloc_ (lua_State *L, void *block, size_t oldsize, size_t size) {
  void *newblock;
  global_State *g = G(L);
  lua_assert((size == 0) == (block == NULL));
  newblock = (*g->frealloc)(g->ud, block, oldsize, size);
  if (l_unlikely(newblock == NULL && size > 0)) {
    lua_assert(size > oldsize);  /* cannot fail when shrinking a block */
    if (g->gcrunning) {
      luaC_fullgc(L, 1);  /* try to free some memory... */
      newblock = (*g->frealloc)(g->ud, block, oldsize, size);  /* try again */
    }
    if (newblock == NULL)
      luaD_throw(L, LUA_ERRMEM);
  }
  lua_assert((size == 0) == (newblock == NULL));
  g->totalbytes = (g->totalbytes - cast(l_mem, oldsize)) + cast(l_mem, size);
  return newblock;
}


void *luaM_saferealloc_ (lua_State *L, void *block, size_t oldsize,
                                                    size_t size) {
  void *newblock = luaM_realloc_(L, block, oldsize, size);
  if (l_unlikely(newblock == NULL && size > 0))  /* allocation failed? */
    luaM_toobig(L);
  return newblock;
}


void *luaM_malloc_ (lua_State *L, size_t size, int tag) {
  if (size == 0)
    return NULL;  /* that's all */
  else {
    global_State *g = G(L);
    void *newblock = (*g->frealloc)(g->ud, NULL, tag, size);
    if (l_unlikely(newblock == NULL)) {
      if (g->gcrunning) {
        luaC_fullgc(L, 1);
        newblock = (*g->frealloc)(g->ud, NULL, tag, size);
      }
      if (newblock == NULL)
        luaD_throw(L, LUA_ERRMEM);
    }
    g->totalbytes += cast(l_mem, size);
    return newblock;
  }
