    const char *nl = strchr(source, '\n');
    const char *what = "[string \"";
    size_t whatlen = strlen(what);
    addstr(out, LUA_IDSIZE, what, whatlen);
    bufflen -= whatlen + (sizeof("...\"]") / sizeof(char));
    if (srclen > bufflen || nl != NULL) {
