    out += whatlen + srclen;
    if (srclen != (nl ? (size_t)(nl - source) : (size_t)-1)) {
      addstr(out, LUA_IDSIZE, "...", 3);
      out += 3;
    }
    *out++ = '"'; *out++ = ']'; *out = '\0';
  }
}

