  lua_Integer i;
  lua_Number n;
  const char *e;
  if ((e = lua_str2integer(s, &e, 10)) != NULL && *e == '\\0') {
    setivalue(o, i);
    return cast_int(e - s) + 1;
  }
  else if ((e = l_str2d(s, &n)) != NULL) {
    setfltvalue(o, n);
    return cast_int(e - s) + 1;
  }
  return 0;
}'''

new = '''int luaO_str2num (const char *s, TValue *o) {
  lua_Integer i;
  lua_Number n;
  const char *e;
  char *ep;
  /* try integer first */
  i = (lua_Integer)strtoll(s, &ep, 0);
  if (ep != s && *ep == '\\0') {
    setivalue(o, i);
    return cast_int(ep - s) + 1;
  }
  /* try float */
  n = strtod(s, &ep);
  if (ep != s && *ep == '\\0') {
    setfltvalue(o, n);
    return cast_int(ep - s) + 1;
  }
  return 0;
}'''

