/* hash functions */
#define hashpow2(t,n)		(gnode(t, lmod((n), sizenode(t))))
#define hashstr(t,str)		hashpow2(t, (str)->hash)
#define hashboolean(t,p)	hashpow2(t, p)
#define hashmod(t,n)		(gnode(t, (n) % (sizenode(t)-1) + 1))
#define hashpointer(t,p)	hashpow2(t, point2uint(p))

static Node *hashfloat (const Table *t, lua_Number n) {
  int i;
  lua_Number m = l_mathop(frexp)(n, &i) * cast_num(INT_MAX - DBL_MAX_EXP);
  i += cast_int(m);
  if (i < 0) {
    if (cast_uint(i) == 0u - cast_uint(i)) i = 0;
    i = -i;
  }
  return hashmod(t, i);
}

static Node *mainpositionTV (const Table *t, const TValue *key) {
  switch (ttypetag(key)) {
    case LUA_VNUMINT:
      return hashpow2(t, l_castS2U(ivalue(key)));
    case LUA_VNUMFLT:
      return hashfloat(t, fltvalue(key));
    case LUA_VSHRSTR:
      return hashstr(t, tsvalue(key));
    case LUA_VLNGSTR:
      return hashpow2(t, luaS_hashlongstr(tsvalue(key)));
    case LUA_VFALSE:
      return hashpow2(t, 0);
    case LUA_VTRUE:
      return hashpow2(t, 1);
    case LUA_VLIGHTUSERDATA:
      return hashpointer(t, pvalue(key));
    case LUA_VLCCL:
      return hashpointer(t, fvalue(key));
    default:
      return hashpointer(t, gcvalue(key));
  }
