  return (isrealasize(t) || t->array[t->alimit - 1].tt_ != LUA_VEMPTY);
}

unsigned int luaH_realasize (const Table *t) {
  if (limitequalsasize(t))
    return t->alimit;
  else {
    unsigned int sq = t->alimit;
    /* find boundary using the array */
    while (sq > 1 && isempty(&t->array[sq/2 - 1]))
      sq /= 2;
    return sq;
  }
