    while (t->lastfree > t->node) {
      t->lastfree--;
      if (keyisnil(t->lastfree))
        return t->lastfree;
    }
  }
  return NULL;
}

static void rehash (lua_State *L, Table *t, const TValue *ek) {
  unsigned int nasize;
  unsigned int na;
  unsigned int nums[MAXABITS + 1];
  int i;
  int totaluse;
  for (i = 0; i <= MAXABITS; i++) nums[i] = 0;
  setlimittosize(t);
  na = 0;
  totaluse = 0;
  /* count array slots */
  for (i = 0; i < (int)t->alimit; i++) {
    if (!isempty(&t->array[i])) {
      totaluse++;
      if (i < MAXABITS) {
        int k = 0;
        unsigned int v = i + 1;
        while (v > 1) { v >>= 1; k++; }
        nums[k]++;
      }
    }
  }
  na = totaluse;
  /* count hash slots */
  for (i = 0; i < (int)sizenode(t); i++) {
    Node *n = &t->node[i];
    if (!keyisnil(n)) {
      totaluse++;
      if (keyisinteger(n)) {
        lua_Integer key = keyival(n);
        if (key > 0 && key <= (lua_Integer)MAXASIZE) {
          int k = 0;
          unsigned int v = (unsigned int)key;
          while (v > 1) { v >>= 1; k++; }
          nums[k]++;
          na++;
        }
      }
    }
  }
  /* count ek */
  if (ttisinteger(ek)) {
    lua_Integer key = ivalue(ek);
    if (key > 0 && key <= (lua_Integer)MAXASIZE) {
      int k = 0;
      unsigned int v = (unsigned int)key;
      while (v > 1) { v >>= 1; k++; }
      nums[k]++;
      na++;
    }
  }
  totaluse++;
  /* compute new array size */
  nasize = 0;
  {
    unsigned int a = 0;
    unsigned int optimal = 0;
    unsigned int sum = 0;
    for (i = 0; i <= MAXABITS; i++) {
      a += nums[i];
      if (a > (1u << i) / 2) {
        optimal = 1u << i;
        sum = a;
      }
    }
    nasize = optimal;
    na = sum;
  }
  luaH_resize(L, t, nasize, totaluse - na);
}

