           (unsigned int)key == t->alimit + 1 &&
           !isempty(&t->array[t->alimit - 1])) {
    setlimittosize(t);
    if (l_castS2U(key) - 1u < t->alimit)
      return &t->array[key - 1];
  }
  {
    Node *n = hashpow2(t, l_castS2U(key));
    for (;;) {
      if (keyisinteger(n) && keyival(n) == key)
        return gval(n);
      else {
        int nx = gnext(n);
        if (nx == 0) break;
        n += nx;
      }
