    /* find boundary using the array */
    while (sq > 1 && isempty(&t->array[sq/2 - 1]))
      sq /= 2;
    return sq;
  }
}

static unsigned int setlimittosize (Table *t) {
  t->alimit = luaH_realasize(t);
  setrealasize(t);
  return t->alimit;
}

int luaH_getn (Table *t) {
  unsigned int limit = t->alimit;
  if (limit > 0 && isempty(&t->array[limit - 1])) {
    if (!isrealasize(t) && limit > 1 && !isempty(&t->array[limit/2 - 1])) {
      limit = setlimittosize(t);
    }
    /* binary search */
    unsigned int lo = 0;
    while (limit > lo + 1) {
      unsigned int mid = (lo + limit) / 2;
      if (isempty(&t->array[mid - 1]))
        limit = mid;
      else
        lo = mid;
    }
    return lo;
  }
  if (!limitequalsasize(t)) {
    if (isempty(&t->array[limit]))
      return limit;
    limit = setlimittosize(t);
  }
  if (limit == 0 || isempty(&t->array[limit - 1]))
    return 0;
  if (isdummy(t))
    return limit;
  /* search in hash part */
  {
    unsigned int j = limit;
    for (;;) {
      unsigned int m = j + (j >> 1);
      if (m > INT_MAX) break;
      TValue key;
      setivalue(&key, m);
      if (isempty(luaH_getint(t, m)))
        j = m;
      else if (m == j + 1)
        return m;
      else
        j = m;
      if (j < limit) break;
    }
    return j;
  }
}

static Node *getfreepos (Table *t) {
  if (!isdummy(t)) {
    while (t->lastfree > t->node) {
      t->lastfree--;
      if (keyisnil(t->lastfree))
        return t->lastfree;
    }
  }
  return NULL;
}

static void rehash (lua_State *L, Table *t, const TValue *ek) {
  unsigned int nasize;
  unsigned int na;
  unsigned int nums[MAXABITS + 1];
  int i;
  int totaluse;
  for (i = 0; i <= MAXABITS; i++) nums[i] = 0;
  setlimittosize(t);
  na = 0;
  totaluse = 0;
  /* count array slots */
  for (i = 0; i < (int)t->alimit; i++) {
    if (!isempty(&t->array[i])) {
      totaluse++;
      if (i < MAXABITS) {
        int k = 0;
        unsigned int v = i + 1;
        while (v > 1) { v >>= 1; k++; }
        nums[k]++;
      }
    }
  }
  na = totaluse;
  /* count hash slots */
  for (i = 0; i < (int)sizenode(t); i++) {
    Node *n = &t->node[i];
    if (!keyisnil(n)) {
      totaluse++;
      if (keyisinteger(n)) {
        lua_Integer key = keyival(n);
        if (key > 0 && key <= (lua_Integer)MAXASIZE) {
          int k = 0;
          unsigned int v = (unsigned int)key;
          while (v > 1) { v >>= 1; k++; }
          nums[k]++;
          na++;
        }
      }
    }
  }
  /* count ek */
  if (ttisinteger(ek)) {
    lua_Integer key = ivalue(ek);
    if (key > 0 && key <= (lua_Integer)MAXASIZE) {
      int k = 0;
      unsigned int v = (unsigned int)key;
      while (v > 1) { v >>= 1; k++; }
      nums[k]++;
      na++;
    }
  }
  totaluse++;
  /* compute new array size */
  nasize = 0;
  {
    unsigned int a = 0;
    unsigned int optimal = 0;
    unsigned int sum = 0;
    for (i = 0; i <= MAXABITS; i++) {
      a += nums[i];
      if (a > (1u << i) / 2) {
        optimal = 1u << i;
        sum = a;
      }
    }
    nasize = optimal;
    na = sum;
  }
  luaH_resize(L, t, nasize, totaluse - na);
}

Table *luaH_new (lua_State *L) {
  GCObject *o = luaC_newobj(L, LUA_VTABLE, sizeof(Table));
  Table *t = gco2t(o);
  t->metatable = NULL;
  t->flags = cast_byte(maskflags);
  t->array = NULL;
  t->alimit = 0;
  t->node = cast(Node *, dummynode);
  t->lsizenode = 0;
  t->lastfree = NULL;
  t->gclist = NULL;
  return t;
}

static void setarrayvector (lua_State *L, Table *t, unsigned int size) {
  t->array = luaM_reallocvector(L, t->array, luaH_realasize(t), size, TValue);
  unsigned int i;
  for (i = t->alimit; i < size; i++)
    setempty(&t->array[i]);
  t->alimit = size;
  setrealasize(t);
}

static void setnodevector (lua_State *L, Table *t, unsigned int size) {
  if (size == 0) {
    t->node = cast(Node *, dummynode);
    t->lsizenode = 0;
    t->lastfree = NULL;
  }
  else {
    int i;
    int lsize;
    if (size > MAXHSIZE)
      luaG_runerror(L, "table overflow");
    lsize = 0;
    while ((1u << lsize) < size) lsize++;
    size = 1u << lsize;
    t->node = luaM_newvector(L, size, Node);
    for (i = 0; i < (int)size; i++) {
      Node *n = gnode(t, i);
      gnext(n) = 0;
      setnilkey(n);
      setempty(gval(n));
    }
    t->lsizenode = cast_byte(lsize);
    t->lastfree = gnode(t, size);
  }
}

void luaH_resize (lua_State *L, Table *t, unsigned int nasize,
                                          unsigned int nhsize) {
  unsigned int i;
  int j;
  unsigned int oldasize = setlimittosize(t);
  int oldhsize = allocsizenode(t);
  Node *nold = t->node;  /* save old hash ... */
  if (nasize > oldasize)  /* should we grow? */
    setarrayvector(L, t, nasize);
  /* create new hash part with appropriate size */
  setnodevector(L, t, nhsize);
  if (nasize < oldasize) {  /* should we shrink? */
    t->alimit = nasize;
    setrealasize(t);
    /* re-insert elements from vanishing slice */
    for (i = oldasize - 1; i >= nasize; i--) {
      if (!isempty(&nold[i])) {  /* wait... nold is old array */
      }
    }
    /* shrink array */
    t->array = luaM_reallocvector(L, t->array, oldasize, nasize, TValue);
  }
  /* re-insert elements from old hash part */
  for (j = oldhsize - 1; j >= 0; j--) {
    Node *old = nold + j;
    if (!isempty(gval(old))) {
      TValue k;
      getnodekey(L, &k, old);
      luaH_set(L, t, &k);
      /* set value */
      TValue *slot = luaH_set(L, t, &k);
      setobj(L, slot, gval(old));
    }
  }
  if (oldhsize > 0)
    luaM_freearray(L, nold, cast_sizet(oldhsize));
}

void luaH_resizearray (lua_State *L, Table *t, unsigned int nasize) {
  int nsize = allocsizenode(t);
  luaH_resize(L, t, nasize, nsize);
}

static void luaH_rehash (lua_State *L, Table *t, const TValue *ek) {
  rehash(L, t, ek);
}

/* Functions to find values */
const TValue *luaH_getint (Table *t, lua_Integer key) {
  if (l_castS2U(key) - 1u < t->alimit)
    return &t->array[key - 1];
  else if (!limitequalsasize(t) &&
           (unsigned int)key == t->alimit + 1 &&
           !isempty(&t->array[t->alimit - 1])) {
    setlimittosize(t);
    if (l_castS2U(key) - 1u < t->alimit)
      return &t->array[key - 1];
  }
  {
    Node *n = hashpow2(t, l_castS2U(key));
    for (;;) {
      if (keyisinteger(n) && keyival(n) == key)
        return gval(n);
      else {
        int nx = gnext(n);
        if (nx == 0) break;
        n += nx;
      }
    }
  }
  return &absentkey;
}

const TValue *luaH_getshortstr (Table *t, TString *key) {
  Node *n = hashstr(t, key);
  lua_assert(key->tt == LUA_VSHRSTR);
  for (;;) {
    if (keyisshrstr(n) && eqshrstr(keystrval(n), key))
      return gval(n);
    else {
      int nx = gnext(n);
      if (nx == 0) break;
      n += nx;
    }
  }
  return &absentkey;
}

const TValue *luaH_getstr (Table *t, TString *key) {
  if (key->tt == LUA_VSHRSTR)
    return luaH_getshortstr(t, key);
  else {
    TValue ko;
    setsvalue(cast_state(NULL), &ko, key);
    return luaH_get(t, &ko);
  }
}

const TValue *luaH_get (Table *t, const TValue *key) {
  switch (ttypetag(key)) {
    case LUA_VNIL: return &absentkey;
    case LUA_VNUMINT: return luaH_getint(t, ivalue(key));
    case LUA_VSHRSTR: return luaH_getshortstr(t, tsvalue(key));
    case LUA_VNUMFLT: {
      lua_Integer k;
      if (luaV_flttointeger(fltvalue(key), &k, F2Ieq))
        return luaH_getint(t, k);
      /* else fall through */
    }
    default: {
      Node *n = mainpositionTV(t, key);
      for (;;) {
        if (equalkey(key, n, 0))
          return gval(n);
        else {
          int nx = gnext(n);
          if (nx == 0) break;
          n += nx;
        }
      }
      return &absentkey;
    }
  }
}

static TValue *newkey (lua_State *L, Table *t, const TValue *key,
                                               Node *mp) {
  Node *othern;
  Node *f = getfreepos(t);
  if (f == NULL) {
    luaH_rehash(L, t, key);
    return luaH_set(L, t, key);
  }
  lua_assert(!isdummy(t));
  othern = mainpositionfromnode(t, mp);
  if (othern != mp) {
    /* other node collided here; move it */
    while (othern + gnext(othern) != mp)
      othern += gnext(othern);
    gnext(othern) = cast_int(f - othern);
    *f = *mp;
    if (gnext(mp) != 0) {
      gnext(f) += cast_int(mp - f);
      gnext(mp) = 0;
    }
    setempty(gval(mp));
  }
  else {
    if (gnext(mp) != 0)
      gnext(f) = cast_int((mp + gnext(mp)) - f);
    else
      lua_assert(gnext(f) == 0);
    gnext(mp) = cast_int(f - mp);
    mp = f;
  }
  setnodekey(L, mp, key);
  luaC_barrierback(L, obj2gco(t), key);
  lua_assert(isempty(gval(mp)));
  return gval(mp);
}

void luaH_newkey (lua_State *L, Table *t, const TValue *key, TValue *value) {
  TValue *slot = newkey(L, t, key, mainpositionTV(t, key));
  setobj(L, slot, value);
}

TValue *luaH_set (lua_State *L, Table *t, const TValue *key) {
  const TValue *p = luaH_get(t, key);
  if (!isempty(p))
    return cast(TValue *, p);
  else
    return newkey(L, t, key, mainpositionTV(t, key));
}

void luaH_setint (lua_State *L, Table *t, lua_Integer key, TValue *value) {
  const TValue *p = luaH_getint(t, key);
  TValue *cell;
  if (!isempty(p))
    cell = cast(TValue *, p);
  else {
    TValue k;
    setivalue(&k, key);
    cell = newkey(L, t, &k, hashpow2(t, l_castS2U(key)));
  }
  setobj(L, cell, value);
}

void luaH_fastset (lua_State *L, Table *t, const TValue *slot, TValue *value) {
  lua_assert(!isempty(slot));
  setobj(L, cast(TValue *, slot), value);
  luaC_barrierback(L, obj2gco(t), value);
}

void luaH_fastsets (lua_State *L, Table *t, const TValue *slot, TValue *value) {
  luaH_fastset(L, t, slot, value);
}

int luaH_next (lua_State *L, Table *t, StkId key) {
  unsigned int asize = luaH_realasize(t);
  unsigned int i = luaH_getn(t);
  if (ttisnil(s2v(key))) {
    i = 0;
  }
  else if (ttisinteger(s2v(key))) {
    lua_Integer ki = ivalue(s2v(key));
    if (l_castS2U(ki) - 1u < asize) {
      i = (unsigned int)(ki - 1);
      /* find next non-empty array slot */
      for (i++; i < asize; i++) {
        if (!isempty(&t->array[i])) {
          setivalue(s2v(key), i + 1);
          setobj(L, s2v(key+1), &t->array[i]);
          return 1;
        }
      }
      /* continue with hash part */
      i = 0;
      goto hashpart;
    }
    i = (unsigned int)~0;  /* skip array part */
    goto hashpart;
  }
  else {
    /* find in hash */
    i = (unsigned int)~0;
    goto hashpart;
  }
  /* scan array part */
  for (; i < asize; i++) {
    if (!isempty(&t->array[i])) {
      setivalue(s2v(key), i + 1);
      setobj(L, s2v(key+1), &t->array[i]);
      return 1;
    }
  }
  i = 0;
hashpart:
  for (; i < sizenode(t); i++) {
    Node *n = gnode(t, i);
    if (!isempty(gval(n))) {
      getnodekey(L, s2v(key), n);
      setobj(L, s2v(key+1), gval(n));
      return 1;
    }
  }
  return 0;  /* no more elements */
}

void luaH_free (lua_State *L, Table *t) {
  if (!isdummy(t))
    luaM_freearray(L, t->node, cast_sizet(sizenode(t)));
  luaM_freearray(L, t->array, luaH_realasize(t));
  luaM_free(L, t);
}

