static void callclose (lua_State *L, TValue *func, TValue *err) {
  ptrdiff_t top = savestack(L, L->top);
  setobj2s(L, L->top, func);
  if (err) setobj2s(L, L->top + 1, err);
  else setnilvalue(s2v(L->top + 1));
