  lu_byte extra_[LUA_EXTRASPACE];
  lua_State l;
} LX;

/*
** Main thread combines (in the same block) a thread state and the
** global state; the global state is at the end (to be compatible
** with 32-bit compilers that don't accept 2Gb-aligned blocks)
*/
typedef struct LG {
  LX l;
