/*
** Compute an initial seed as random as possible. Rely on Address Space
** Layout Randomization (if present) to increase randomness..
*/
static unsigned int makeseed (lua_State *L) {
  char buff[4 * sizeof(size_t)];
  unsigned int h = cast_uint(time(NULL));
  int p = 0;
  union { int volatile x; } u;
  u.x = 0;
  luaO_hashptr(buff + p, (void*)&h); p += sizeof(size_t);
  luaO_hashptr(buff + p, (void*)L); p += sizeof(size_t);
  luaO_hashptr(buff + p, (void*)luaO_pushfstring); p += sizeof(size_t);
  luaO_hashptr(buff + p, (void*)malloc); p += sizeof(size_t);
  return luaS_hash(buff, p, h);
