  t = lua_absindex(L, t);
  if (lua_rawgeti(L, t, 0) == LUA_TNIL) {
    ref = cast_int(lua_rawlen(L, t)) + 1;
  }
  else {
    ref = cast_int(lua_tointeger(L, -1));
    lua_rawgeti(L, t, ref);
    lua_rawseti(L, t, 0);
  }
  lua_pop(L, 1);
  lua_rawseti(L, t, ref);
  return ref;
}

