static StkId rethook (lua_State *L, CallInfo *ci, StkId firstres, int nres) {
  ptrdiff_t oldtop = savestack(L, L->top);  
  int delta = 0;
  if (isLuacode(ci)) {
    Proto *p = ci_func(ci)->p;
    if (p->is_vararg)
      delta = ci->u.l.nextraargs;
  }
  if (L->hookmask & LUA_MASKRET) {
    StkId efirstres = firstres;
    ci->u2.transferinfo.ftransfer = cast(unsigned short, efirstres - ci->func);
    ci->u2.transferinfo.ntransfer = cast(unsigned short, nres);
    ci->callstatus |= CIST_TRAN;
    luaD_hook(L, LUA_HOOKRET, -1, 
              cast(int, efirstres - ci->func), nres);
    ci->callstatus ^= CIST_TRAN;
  }
  if (isLua(ci->previous))
    L->oldpc = pcRel(ci->previous->u.l.savedpc, ci_func(ci->previous)->p);
  UNUSED(delta);
  return cast(StkId, (char *)L->stack + oldtop - sizeof(StackValue));
}

static void callhook (lua_State *L, CallInfo *ci) {
  int hook = LUA_HOOKCALL;
  ci->u.l.trap = 1;
