static CallInfo *next_ci (lua_State *L) {
  CallInfo *ci;
  if (L->ci->next) {
    ci = L->ci->next;
  }
  else {
    ci = luaE_extendCI(L);
  }
  L->ci = ci;
  return ci;
}

#define isLuacode(ci) (!((ci)->callstatus & CIST_C))

static int precall (lua_State *L, StkId func, int nresults) {
  lua_CFunction f;
  CallInfo *ci;
  switch (ttypetag(s2v(func))) {
    case LUA_VCCL:
    case LUA_VLCCL: {
      f = ttislcf(s2v(func)) ? fvalue(s2v(func)) : clCvalue(s2v(func))->f;
      int n;
      checkstackGC(L, LUA_MINSTACK);
      ci = next_ci(L);
      ci->nresults = nresults;
      ci->callstatus = CIST_C;
      ci->top = L->top + LUA_MINSTACK;
      ci->func = func;
      if (L->hookmask & LUA_MASKCALL) {
        int narg = cast_int(L->top - func) - 1;
        luaD_hook(L, LUA_HOOKCALL, -1, 1, narg);
      }
      lua_unlock(L);
      n = (*f)(L);
      lua_lock(L);
      api_checknelems(L, n);
      luaD_poscall(L, ci, n);
      return 0;
    }
    case LUA_VLCL: {
      LClosure *cl = clLvalue(s2v(func));
      Proto *p = cl->p;
      int n;
      int narg = cast_int(L->top - func) - 1;
      int nfixparams = p->numparams;
      int fsize = p->maxstacksize;
      StkId base;
      checkstackGC(L, fsize);
      ci = next_ci(L);
      ci->nresults = nresults;
      ci->callstatus = 0;
      ci->top = func + 1 + fsize;
      ci->func = func;
      L->ci = ci;
      if (narg < nfixparams) {
        for (n = narg; n < nfixparams; n++)
          setnilvalue(s2v(L->top++));
        base = func + 1;
      }
      else if (p->is_vararg) {
        base = adjust_varargs(L, p, narg);
        ci->func = base - 1;
      }
      else
        base = func + 1;
      ci->u.l.savedpc = p->code;
      ci->u.l.trap = 0;
      ci->u.l.nextraargs = 0;
      L->top = ci->top;
      if (L->hookmask & LUA_MASKCALL) {
        ci->u2.transferinfo.ftransfer = cast(unsigned short, base - func);
        ci->u2.transferinfo.ntransfer = cast(unsigned short, narg);
        luaD_hook(L, LUA_HOOKCALL, -1, cast(int, base - func), narg);
      }
      return 1;  /* Lua function: need to execute bytecode */
    }
    default:
      checkstackGC(L, 1);
      tryfuncTM(L, func);
      return precall(L, func, nresults);
  }
}

CallInfo *luaD_precall (lua_State *L, StkId func, int nResults) {
  if (!precall(L, func, nResults))
    return NULL;
  return L->ci;
}

void luaD_poscall (lua_State *L, CallInfo *ci, int nres) {
  int wanted = ci->nresults;
  int i;
  StkId res = ci->func;
  StkId firstres = L->top - nres;
  if (l_unlikely(ci->callstatus & CIST_CLSRET)) {
    res = cast(StkId, (char *)L->stack + ci->u2.nres);
    firstres = L->top - nres;
  }
  if (L->hookmask & (LUA_MASKRET | LUA_MASKLINE))
    firstres = rethook(L, ci, firstres, nres);
  L->ci = ci->previous;
  /* adjust results */
  if (wanted == LUA_MULTRET) {
    int totalres = cast_int(L->top - firstres);
    for (i = 0; i < totalres; i++)
      setobjs2s(L, res + i, firstres + i);
    L->top = res + totalres;
  }
  else {
    for (i = 0; i < nres && i < wanted; i++)
      setobjs2s(L, res + i, firstres + i);
    for (; i < wanted; i++)
      setnilvalue(s2v(res + i));
    L->top = res + wanted;
  }
}

#define errorstatus(s) ((s) > LUA_YIELD)

void luaD_call (lua_State *L, StkId func, int nResults) {
  luaE_incCstack(L);
  if (!precall(L, func, nResults)) {
    luaV_execute(L, L->ci);
  }
  decCcalls(L);
}

void luaD_callnoyield (lua_State *L, StkId func, int nResults) {
  L->nCcalls += 0x10000;
  luaD_call(L, func, nResults);
  L->nCcalls -= 0x10000;
}

static int resume_error (lua_State *L, const char *msg, int narg) {
  L->top -= narg;
  setsvalue2s(L, L->top, luaS_new(L, msg));
  api_incr_top(L);
  return LUA_ERRRUN;
}

static void f_resume (lua_State *L, void *ud) {
  int n = *(cast(int *, ud));
  StkId firstArg = L->top - n;
  CallInfo *ci = L->ci;
  if (L->status == LUA_OK) {
    precall(L, firstArg - 1, LUA_MULTRET);
    luaV_execute(L, L->ci);
  }
  else {
    lua_assert(L->status == LUA_YIELD);
    L->status = LUA_OK;
    if (isLua(ci)) {
      luaV_execute(L, ci);
    }
    else {
      lua_CFunction k = ci->u.c.k;
      if (k != NULL) {
        lua_unlock(L);
        n = (*k)(L, LUA_YIELD, ci->u.c.ctx);
        lua_lock(L);
        api_checknelems(L, n);
      }
      luaD_poscall(L, ci, n);
    }
    unroll(L, NULL);
  }
}

static void unroll (lua_State *L, void *ud) {
  CallInfo *ci;
  UNUSED(ud);
  if ((ci = L->ci)->previous == NULL)
    return;
  for (;;) {
    if (!isLuacode(ci))
      luaD_poscall(L, ci, 0);
    else {
      luaV_finishOp(L);
      luaV_execute(L, ci);
    }
    ci = L->ci;
    if (ci->previous == NULL)
      return;
  }
}

static int resume (lua_State *L, lua_State *from, int nargs) {
  int status;
  int oldnCcalls = (from ? from->nCcalls : 0);
  if (getCcalls(L) >= LUAI_MAXCCALLS)
    return resume_error(L, "C stack overflow", nargs);
  L->nCcalls = (from ? from->nCcalls : 0) + 1;
  if (L->status != LUA_OK && L->status != LUA_YIELD)
    return resume_error(L, "cannot resume dead coroutine", nargs);
  if (L->status == LUA_OK && L->ci->previous != NULL)
    return resume_error(L, "cannot resume non-suspended coroutine", nargs);
  status = luaD_rawrunprotected(L, f_resume, &nargs);
  if (l_unlikely(status == -1))
    status = LUA_ERRRUN;
  else {
    while (status != LUA_OK && status != LUA_YIELD) {
      if (handleProtectedCallError(from, L, status))
        status = luaD_rawrunprotected(L, unroll, NULL);
      else {
        L->status = cast_byte(status);
        break;
      }
    }
    lua_assert(status == L->status);
  }
  L->nCcalls = oldnCcalls;
  return status;
}

LUA_API int lua_resume (lua_State *L, lua_State *from, int narg, int *nres) {
  int status;
  lua_lock(L);
  status = resume(L, from, narg);
  if (status == LUA_OK || status == LUA_YIELD) {
    int tresults = cast_int(L->top - (L->ci->func + 1));
    if (nres) *nres = tresults;
    if (tresults > L->ci->top - (L->ci->func + 1)) {
      if (l_unlikely(!lua_checkstack(L, tresults - (int)(L->ci->top - L->ci->func - 1))))
        status = LUA_ERRRUN;
    }
  }
  else if (nres) *nres = 0;
  lua_unlock(L);
  return status;
}

LUA_API int lua_isyieldable (lua_State *L) {
  return yieldable(L);
}

LUA_API int lua_yieldk (lua_State *L, int nresults, lua_KContext ctx,
                        lua_KFunction k) {
  CallInfo *ci;
  luai_userstateyield(L, nresults);
  lua_lock(L);
  ci = L->ci;
  api_checknelems(L, nresults);
  if (l_unlikely(!yieldable(L))) {
    if (L != G(L)->mainthread)
      luaG_runerror(L, "attempt to yield across a C-call boundary");
    else
      luaG_runerror(L, "attempt to yield from outside a coroutine");
  }
  L->status = LUA_YIELD;
  ci->u2.nyield = nresults;
  if (isLua(ci)) {
    lua_unlock(L);
    return -1;
  }
  else {
    if ((ci->u.c.k = k) != NULL) {
      ci->u.c.ctx = ctx;
    }
    luaD_throw(L, LUA_YIELD);
  }
}

int luaD_pcall (lua_State *L, Pfunc func, void *u,
                ptrdiff_t old_top, ptrdiff_t ef) {
  int status;
  CallInfo *old_ci = L->ci;
  lu_byte old_allowhooks = L->allowhook;
  ptrdiff_t old_errfunc = L->errfunc;
  L->errfunc = ef;
  status = luaD_rawrunprotected(L, func, u);
  if (l_unlikely(status != LUA_OK)) {
    StkId oldtop = restorestack(L, old_top);
    L->ci = old_ci;
    L->allowhook = old_allowhooks;
    status = luaF_close(L, oldtop, status, 0) != oldtop
             ? CLOSEKTOP : status;
    luaD_seterrorobj(L, status, oldtop);
    luaD_shrinkstack(L);
