int luaD_closeprotected (lua_State *L, ptrdiff_t level, int status) {
  CallInfo *old_ci = L->ci;
  lu_byte old_allowhooks = L->allowhook;
  for (;;) {
    int nstatus = luaD_rawrunprotected(L, NULL, NULL);
    if (nstatus == LUA_OK)
      break;
    luaD_seterrorobj(L, nstatus, L->top - 1);
    if (nstatus < status)
      status = nstatus;
  }
  L->ci = old_ci;
  L->allowhook = old_allowhooks;
  return status;
}

int luaD_protectedparser (lua_State *L, ZIO *z, const char *name,
                                              const char *mode) {
  struct SParser w;
  int status;
  incnewwhite(G(L));
  w.z = z; w.name = name; w.mode = mode;
  w.dyd.actvar.arr = NULL; w.dyd.actvar.size = 0;
  w.dyd.gt.arr = NULL; w.dyd.gt.size = 0;
  w.dyd.label.arr = NULL; w.dyd.label.size = 0;
  luaZ_initbuffer(L, &w.buff);
  status = luaD_pcall(L, f_parser, &w, savestack(L, L->top), L->errfunc);
  luaZ_freebuffer(L, &w.buff);
  luaM_freearray(L, w.dyd.actvar.arr, w.dyd.actvar.size);
  luaM_freearray(L, w.dyd.gt.arr, w.dyd.gt.size);
  luaM_freearray(L, w.dyd.label.arr, w.dyd.label.size);
  return status;
}

static void f_parser (lua_State *L, void *ud) {
  LClosure *cl;
  struct SParser *p = cast(struct SParser *, ud);
  int c = zgetc(p->z);
  if (c == LUA_SIGNATURE[0]) {
    checkmode(L, p->mode, "binary");
    cl = luaU_undump(L, p->z, p->name);
  }
  else {
    checkmode(L, p->mode, "text");
    cl = luaY_parser(L, p->z, &p->buff, &p->dyd, p->name, c);
  }
  lua_assert(cl->nupvalues == cl->p->sizeupvalues);
  luaF_initupvals(L, cl);
  if (cl->nupvalues >= 1) {
    Table *reg = hvalue(&G(L)->l_registry);
    const TValue *gt = luaH_getint(reg, LUA_RIDX_GLOBALS);
    setobj(L, cl->upvals[0]->v.p, gt);
  }
  setclLvalue2s(L, L->top, cl);
  api_incr_top(L);
}

struct SParser {
  ZIO *z;
  Mbuffer buff;
  Dyndata dyd;
  const char *mode;
  const char *name;
