/* correction for C function stack */
#define CSTACKERR  200

struct lua_longjmp {
  struct lua_longjmp *previous;
  volatile int status;
  jmp_buf b;
};

#if !defined(LUAI_THROW)
#define LUAI_THROW(L,c)   longjmp((c)->b, 1)
#define LUAI_TRY(L,c,a)   if (setjmp((c)->b) == 0) { a }
#define luai_jmpbuf       jmp_buf
#endif


void luaD_seterrorobj (lua_State *L, int errcode, StkId oldtop) {
  switch (errcode) {
    case LUA_ERRMEM: {
      setsvalue2s(L, oldtop, G(L)->memerrmsg);
      break;
    }
    case LUA_ERRERR: {
      setsvalue2s(L, oldtop, luaS_newliteral(L, "error in error handling"));
      break;
    }
    case LUA_OK: {
      setnilvalue(s2v(oldtop));
      break;
    }
    default: {
      lua_assert(errorstatus(errcode));
      setobjs2s(L, oldtop, L->top - 1);
      break;
    }
  }
  L->top = oldtop + 1;
}

l_noret luaD_throw (lua_State *L, int errcode) {
  if (L->errorJmp) {
    L->errorJmp->status = errcode;
    LUAI_THROW(L, L->errorJmp);
  }
  else {
    global_State *g = G(L);
    errcode = luaE_resetthread(L, errcode);
    if (g->panic) {
      lua_unlock(L);
      g->panic(L);
    }
    abort();
  }
}

int luaD_rawrunprotected (lua_State *L, Pfunc f, void *ud) {
  unsigned short oldnCcalls = L->nCcalls;
  struct lua_longjmp lj;
  lj.status = LUA_OK;
  lj.previous = L->errorJmp;
  L->errorJmp = &lj;
  LUAI_TRY(L, &lj, (*f)(L, ud););
  L->errorJmp = lj.previous;
  L->nCcalls = oldnCcalls;
  return lj.status;
}

static void f_stackerror (lua_State *L, void *ud) {
  (void)ud;
  luaG_runerror(L, "C stack overflow");
}

static void restore_stack_limit (lua_State *L) {
  lua_assert(stacksize(L) == BASIC_STACK_SIZE + EXTRA_STACK);
}

static StkId rethook (lua_State *L, CallInfo *ci, StkId firstres, int nres) {
  ptrdiff_t oldtop = savestack(L, L->top);  
  int delta = 0;
  if (isLuacode(ci)) {
    Proto *p = ci_func(ci)->p;
    if (p->is_vararg)
      delta = ci->u.l.nextraargs;
  }
  if (L->hookmask & LUA_MASKRET) {
    StkId efirstres = firstres;
    ci->u2.transferinfo.ftransfer = cast(unsigned short, efirstres - ci->func);
    ci->u2.transferinfo.ntransfer = cast(unsigned short, nres);
    ci->callstatus |= CIST_TRAN;
    luaD_hook(L, LUA_HOOKRET, -1, 
              cast(int, efirstres - ci->func), nres);
    ci->callstatus ^= CIST_TRAN;
  }
  if (isLua(ci->previous))
    L->oldpc = pcRel(ci->previous->u.l.savedpc, ci_func(ci->previous)->p);
  UNUSED(delta);
  return cast(StkId, (char *)L->stack + oldtop - sizeof(StackValue));
}

static void callhook (lua_State *L, CallInfo *ci) {
  int hook = LUA_HOOKCALL;
  ci->u.l.trap = 1;
  if (isLua(ci)) {
    Proto *p = ci_func(ci)->p;
    if (p->is_vararg)
      hook = LUA_HOOKTAILCALL;
  }
  luaD_hook(L, hook, -1, 1, 0);
}

static StkId adjust_varargs (lua_State *L, Proto *p, int actual) {
  int i;
  int nfixparams = p->numparams;
  StkId base, fixed;
  for (; actual < nfixparams; actual++)  /* complete missing arguments */
    setnilvalue(s2v(L->top++));
  fixed = L->top - actual;
  base = L->top;
  for (i = 0; i < nfixparams; i++) {
    setobjs2s(L, L->top++, fixed + i);
    setnilvalue(s2v(fixed + i));
  }
  return base;
}

static void tryfuncTM (lua_State *L, StkId func) {
  const TValue *tm;
  StkId p;
  checkstackGC(L, 1);
  tm = luaT_gettmbyobj(L, s2v(func), TM_CALL);
  if (l_unlikely(!ttisfunction(tm)))
    luaG_callerror(L, s2v(func));
  for (p = L->top; p > func; p--)
    setobjs2s(L, p, p - 1);
  L->top++;
  setobj2s(L, func, tm);
}

StkId luaD_tryfuncTM (lua_State *L, StkId func) {
  tryfuncTM(L, func);
  return func;
}

static CallInfo *next_ci (lua_State *L) {
  CallInfo *ci;
  if (L->ci->next) {
    ci = L->ci->next;
  }
  else {
    ci = luaE_extendCI(L);
  }
  L->ci = ci;
  return ci;
}

#define isLuacode(ci) (!((ci)->callstatus & CIST_C))

static int precall (lua_State *L, StkId func, int nresults) {
  lua_CFunction f;
  CallInfo *ci;
  switch (ttypetag(s2v(func))) {
    case LUA_VCCL:
    case LUA_VLCCL: {
      f = ttislcf(s2v(func)) ? fvalue(s2v(func)) : clCvalue(s2v(func))->f;
      int n;
      checkstackGC(L, LUA_MINSTACK);
      ci = next_ci(L);
      ci->nresults = nresults;
      ci->callstatus = CIST_C;
      ci->top = L->top + LUA_MINSTACK;
      ci->func = func;
      if (L->hookmask & LUA_MASKCALL) {
        int narg = cast_int(L->top - func) - 1;
        luaD_hook(L, LUA_HOOKCALL, -1, 1, narg);
      }
      lua_unlock(L);
      n = (*f)(L);
      lua_lock(L);
      api_checknelems(L, n);
      luaD_poscall(L, ci, n);
      return 0;
    }
    case LUA_VLCL: {
      LClosure *cl = clLvalue(s2v(func));
      Proto *p = cl->p;
      int n;
      int narg = cast_int(L->top - func) - 1;
      int nfixparams = p->numparams;
      int fsize = p->maxstacksize;
      StkId base;
      checkstackGC(L, fsize);
      ci = next_ci(L);
      ci->nresults = nresults;
      ci->callstatus = 0;
      ci->top = func + 1 + fsize;
      ci->func = func;
      L->ci = ci;
      if (narg < nfixparams) {
        for (n = narg; n < nfixparams; n++)
          setnilvalue(s2v(L->top++));
        base = func + 1;
      }
      else if (p->is_vararg) {
        base = adjust_varargs(L, p, narg);
        ci->func = base - 1;
      }
      else
        base = func + 1;
      ci->u.l.savedpc = p->code;
      ci->u.l.trap = 0;
      ci->u.l.nextraargs = 0;
      L->top = ci->top;
      if (L->hookmask & LUA_MASKCALL) {
        ci->u2.transferinfo.ftransfer = cast(unsigned short, base - func);
        ci->u2.transferinfo.ntransfer = cast(unsigned short, narg);
        luaD_hook(L, LUA_HOOKCALL, -1, cast(int, base - func), narg);
      }
      return 1;  /* Lua function: need to execute bytecode */
    }
    default:
      checkstackGC(L, 1);
      tryfuncTM(L, func);
      return precall(L, func, nresults);
  }
}

CallInfo *luaD_precall (lua_State *L, StkId func, int nResults) {
  if (!precall(L, func, nResults))
    return NULL;
  return L->ci;
}

void luaD_poscall (lua_State *L, CallInfo *ci, int nres) {
  int wanted = ci->nresults;
  int i;
  StkId res = ci->func;
  StkId firstres = L->top - nres;
  if (l_unlikely(ci->callstatus & CIST_CLSRET)) {
    res = cast(StkId, (char *)L->stack + ci->u2.nres);
    firstres = L->top - nres;
  }
  if (L->hookmask & (LUA_MASKRET | LUA_MASKLINE))
    firstres = rethook(L, ci, firstres, nres);
  L->ci = ci->previous;
  /* adjust results */
  if (wanted == LUA_MULTRET) {
    int totalres = cast_int(L->top - firstres);
    for (i = 0; i < totalres; i++)
      setobjs2s(L, res + i, firstres + i);
    L->top = res + totalres;
  }
  else {
    for (i = 0; i < nres && i < wanted; i++)
      setobjs2s(L, res + i, firstres + i);
    for (; i < wanted; i++)
      setnilvalue(s2v(res + i));
    L->top = res + wanted;
  }
}

#define errorstatus(s) ((s) > LUA_YIELD)

void luaD_call (lua_State *L, StkId func, int nResults) {
  luaE_incCstack(L);
  if (!precall(L, func, nResults)) {
    luaV_execute(L, L->ci);
  }
  decCcalls(L);
}

void luaD_callnoyield (lua_State *L, StkId func, int nResults) {
  L->nCcalls += 0x10000;
  luaD_call(L, func, nResults);
  L->nCcalls -= 0x10000;
}

static int resume_error (lua_State *L, const char *msg, int narg) {
  L->top -= narg;
  setsvalue2s(L, L->top, luaS_new(L, msg));
  api_incr_top(L);
  return LUA_ERRRUN;
}

static void f_resume (lua_State *L, void *ud) {
  int n = *(cast(int *, ud));
  StkId firstArg = L->top - n;
  CallInfo *ci = L->ci;
  if (L->status == LUA_OK) {
    precall(L, firstArg - 1, LUA_MULTRET);
    luaV_execute(L, L->ci);
  }
  else {
    lua_assert(L->status == LUA_YIELD);
    L->status = LUA_OK;
    if (isLua(ci)) {
      luaV_execute(L, ci);
    }
    else {
      lua_CFunction k = ci->u.c.k;
      if (k != NULL) {
        lua_unlock(L);
        n = (*k)(L, LUA_YIELD, ci->u.c.ctx);
        lua_lock(L);
        api_checknelems(L, n);
      }
      luaD_poscall(L, ci, n);
    }
    unroll(L, NULL);
  }
}

static void unroll (lua_State *L, void *ud) {
  CallInfo *ci;
  UNUSED(ud);
  if ((ci = L->ci)->previous == NULL)
    return;
  for (;;) {
    if (!isLuacode(ci))
      luaD_poscall(L, ci, 0);
    else {
      luaV_finishOp(L);
      luaV_execute(L, ci);
    }
    ci = L->ci;
    if (ci->previous == NULL)
      return;
  }
}

static int resume (lua_State *L, lua_State *from, int nargs) {
  int status;
  int oldnCcalls = (from ? from->nCcalls : 0);
  if (getCcalls(L) >= LUAI_MAXCCALLS)
    return resume_error(L, "C stack overflow", nargs);
  L->nCcalls = (from ? from->nCcalls : 0) + 1;
  if (L->status != LUA_OK && L->status != LUA_YIELD)
    return resume_error(L, "cannot resume dead coroutine", nargs);
  if (L->status == LUA_OK && L->ci->previous != NULL)
    return resume_error(L, "cannot resume non-suspended coroutine", nargs);
  status = luaD_rawrunprotected(L, f_resume, &nargs);
  if (l_unlikely(status == -1))
    status = LUA_ERRRUN;
  else {
    while (status != LUA_OK && status != LUA_YIELD) {
      if (handleProtectedCallError(from, L, status))
        status = luaD_rawrunprotected(L, unroll, NULL);
      else {
        L->status = cast_byte(status);
        break;
      }
    }
    lua_assert(status == L->status);
  }
  L->nCcalls = oldnCcalls;
  return status;
}

LUA_API int lua_resume (lua_State *L, lua_State *from, int narg, int *nres) {
  int status;
  lua_lock(L);
  status = resume(L, from, narg);
  if (status == LUA_OK || status == LUA_YIELD) {
    int tresults = cast_int(L->top - (L->ci->func + 1));
    if (nres) *nres = tresults;
    if (tresults > L->ci->top - (L->ci->func + 1)) {
      if (l_unlikely(!lua_checkstack(L, tresults - (int)(L->ci->top - L->ci->func - 1))))
        status = LUA_ERRRUN;
    }
  }
  else if (nres) *nres = 0;
  lua_unlock(L);
  return status;
}

LUA_API int lua_isyieldable (lua_State *L) {
  return yieldable(L);
}

LUA_API int lua_yieldk (lua_State *L, int nresults, lua_KContext ctx,
                        lua_KFunction k) {
  CallInfo *ci;
  luai_userstateyield(L, nresults);
  lua_lock(L);
  ci = L->ci;
  api_checknelems(L, nresults);
  if (l_unlikely(!yieldable(L))) {
    if (L != G(L)->mainthread)
      luaG_runerror(L, "attempt to yield across a C-call boundary");
    else
      luaG_runerror(L, "attempt to yield from outside a coroutine");
  }
  L->status = LUA_YIELD;
  ci->u2.nyield = nresults;
  if (isLua(ci)) {
    lua_unlock(L);
    return -1;
  }
  else {
    if ((ci->u.c.k = k) != NULL) {
      ci->u.c.ctx = ctx;
    }
    luaD_throw(L, LUA_YIELD);
  }
}

int luaD_pcall (lua_State *L, Pfunc func, void *u,
                ptrdiff_t old_top, ptrdiff_t ef) {
  int status;
  CallInfo *old_ci = L->ci;
  lu_byte old_allowhooks = L->allowhook;
  ptrdiff_t old_errfunc = L->errfunc;
  L->errfunc = ef;
  status = luaD_rawrunprotected(L, func, u);
  if (l_unlikely(status != LUA_OK)) {
    StkId oldtop = restorestack(L, old_top);
    L->ci = old_ci;
    L->allowhook = old_allowhooks;
    status = luaF_close(L, oldtop, status, 0) != oldtop
             ? CLOSEKTOP : status;
    luaD_seterrorobj(L, status, oldtop);
    luaD_shrinkstack(L);
  }
  L->errfunc = old_errfunc;
  return status;
}

int luaD_closeprotected (lua_State *L, ptrdiff_t level, int status) {
  CallInfo *old_ci = L->ci;
  lu_byte old_allowhooks = L->allowhook;
  for (;;) {
    int nstatus = luaD_rawrunprotected(L, NULL, NULL);
    if (nstatus == LUA_OK)
      break;
    luaD_seterrorobj(L, nstatus, L->top - 1);
    if (nstatus < status)
      status = nstatus;
  }
  L->ci = old_ci;
  L->allowhook = old_allowhooks;
  return status;
}

int luaD_protectedparser (lua_State *L, ZIO *z, const char *name,
                                              const char *mode) {
  struct SParser w;
  int status;
  incnewwhite(G(L));
  w.z = z; w.name = name; w.mode = mode;
  w.dyd.actvar.arr = NULL; w.dyd.actvar.size = 0;
  w.dyd.gt.arr = NULL; w.dyd.gt.size = 0;
  w.dyd.label.arr = NULL; w.dyd.label.size = 0;
  luaZ_initbuffer(L, &w.buff);
  status = luaD_pcall(L, f_parser, &w, savestack(L, L->top), L->errfunc);
  luaZ_freebuffer(L, &w.buff);
  luaM_freearray(L, w.dyd.actvar.arr, w.dyd.actvar.size);
  luaM_freearray(L, w.dyd.gt.arr, w.dyd.gt.size);
  luaM_freearray(L, w.dyd.label.arr, w.dyd.label.size);
  return status;
}

static void f_parser (lua_State *L, void *ud) {
  LClosure *cl;
  struct SParser *p = cast(struct SParser *, ud);
  int c = zgetc(p->z);
  if (c == LUA_SIGNATURE[0]) {
    checkmode(L, p->mode, "binary");
    cl = luaU_undump(L, p->z, p->name);
  }
  else {
    checkmode(L, p->mode, "text");
    cl = luaY_parser(L, p->z, &p->buff, &p->dyd, p->name, c);
  }
  lua_assert(cl->nupvalues == cl->p->sizeupvalues);
  luaF_initupvals(L, cl);
  if (cl->nupvalues >= 1) {
    Table *reg = hvalue(&G(L)->l_registry);
    const TValue *gt = luaH_getint(reg, LUA_RIDX_GLOBALS);
    setobj(L, cl->upvals[0]->v.p, gt);
  }
  setclLvalue2s(L, L->top, cl);
  api_incr_top(L);
}

struct SParser {
  ZIO *z;
  Mbuffer buff;
  Dyndata dyd;
  const char *mode;
  const char *name;
};

static void checkmode (lua_State *L, const char *mode, const char *x) {
  if (mode && strchr(mode, x[0]) == NULL) {
    luaO_pushfstring(L, "attempt to load a %s chunk (mode is '%s')", x, mode);
    luaD_throw(L, LUA_ERRSYNTAX);
  }
}

static void reallocstack (lua_State *L, int newsize, int raiseerror) {
  int lim = stacksize(L);
  StkId newstack = luaM_reallocvector(L, L->stack, lim + EXTRA_STACK, newsize + EXTRA_STACK, StackValue);
  lua_assert(newstack != NULL);
  {
    int i;
    for (i = lim; i < newsize; i++)
      setnilvalue(s2v(newstack + i));
  }
  correctstack(L, L->stack, newstack);
  L->stack = newstack;
  L->stack_last = L->stack + newsize;
}

static void correctstack (lua_State *L, StkId oldstack, StkId newstack) {
  CallInfo *ci;
  UpVal *up;
  L->top = newstack + (L->top - oldstack);
  L->tbclist = newstack + (L->tbclist - oldstack);
  for (up = L->openupval; up != NULL; up = up->u.open.next)
    up->v.p = s2v(newstack + (uplevel(up) - oldstack));
  for (ci = L->ci; ci != NULL; ci = ci->previous) {
    ci->top = newstack + (ci->top - oldstack);
    ci->func = newstack + (ci->func - oldstack);
    if (isLua(ci))
      ci->u.l.savedpc = ci->u.l.savedpc;  /* stays the same */
  }
}

int luaD_reallocstack (lua_State *L, int newsize, int raiseerror) {
  int lim = stacksize(L);
  lua_assert(newsize <= LUAI_MAXSTACK || newsize == ERRORSTACKSIZE);
  lua_assert(L->stack_last == L->stack + lim);
  if (l_unlikely(newsize > LUAI_MAXSTACK)) {
    if (raiseerror)
      luaG_runerror(L, "stack overflow");
    return 0;
  }
  reallocstack(L, newsize, raiseerror);
  return 1;
}

int luaD_growstack (lua_State *L, int n, int raiseerror) {
  int size = stacksize(L);
  if (l_unlikely(size > LUAI_MAXSTACK)) {
    lua_assert(stacksize(L) == ERRORSTACKSIZE);
    if (raiseerror)
      luaD_throw(L, LUA_ERRERR);
    return 0;
  }
  else {
    int newsize = 2 * size;
    int needed = cast_int(L->top - L->stack) + n + EXTRA_STACK;
    if (newsize > LUAI_MAXSTACK)
      newsize = LUAI_MAXSTACK;
    if (newsize < needed)
      newsize = needed;
    if (l_unlikely(newsize > LUAI_MAXSTACK)) {
      luaD_reallocstack(L, ERRORSTACKSIZE, raiseerror);
      if (raiseerror)
        luaG_runerror(L, "stack overflow");
      return 0;
    }
    return luaD_reallocstack(L, newsize, raiseerror);
  }
}

void luaD_shrinkstack (lua_State *L) {
  int inuse = cast_int(L->top - L->stack);
  int nvalid = 0;
  CallInfo *ci;
  for (ci = L->ci; ci != NULL; ci = ci->previous)
    nvalid += 2 + cast_int(ci->top - ci->func);
  if (nvalid >= (inuse / 4)) return;
  int limit = inuse + nvalid;
  if (limit < BASIC_STACK_SIZE) limit = BASIC_STACK_SIZE;
  if (limit >= stacksize(L)) return;
  luaD_reallocstack(L, limit, 0);
}

void luaD_inctop (lua_State *L) {
  luaD_checkstack(L, 1);
  L->top++;
}

void luaD_hook (lua_State *L, int event, int line,
                int fTransfer, int nTransfer) {
  lua_Hook hook = L->hook;
  if (hook && L->allowhook) {
    int mask = CIST_HOOKED;
    CallInfo *ci = L->ci;
    ptrdiff_t top = savestack(L, L->top);
    ptrdiff_t ci_top = savestack(L, ci->top);
    lua_Debug ar;
    ar.event = event;
    ar.currentline = line;
    ar.i_ci = ci;
    if (fTransfer != 0) {
      ci->u2.transferinfo.ftransfer = fTransfer;
      ci->u2.transferinfo.ntransfer = nTransfer;
      ci->callstatus |= CIST_TRAN;
    }
    if (isLua(ci) && L->top < ci->top)
      L->top = ci->top;
    luaD_checkstack(L, LUA_MINSTACK);
    if (ci->top < L->top + LUA_MINSTACK)
      ci->top = L->top + LUA_MINSTACK;
    L->allowhook = 0;
    ci->callstatus |= mask;
    lua_unlock(L);
    (*hook)(L, &ar);
    lua_lock(L);
    lua_assert(!L->allowhook);
    L->allowhook = 1;
    ci->top = restorestack(L, ci_top);
    L->top = restorestack(L, top);
    ci->callstatus &= ~mask;
    ci->callstatus &= ~CIST_TRAN;
  }
}

void luaD_hookcall (lua_State *L, CallInfo *ci) {
  L->oldpc = 0;
  if (L->hookmask & LUA_MASKCALL) {
    int event;
    if (ci->callstatus & CIST_TAIL)
      event = LUA_HOOKTAILCALL;
    else
      event = LUA_HOOKCALL;
    proto_lineinfo(ci_func(ci)->p);  /* ensure line info */
    luaD_hook(L, event, -1, 1, 0);
  }
}

int luaD_pretailcall (lua_State *L, CallInfo *ci, StkId func, int narg1,
                      int delta) {
  switch (ttypetag(s2v(func))) {
    case LUA_VCCL:
    case LUA_VLCCL: {
      return precall(L, func, LUA_MULTRET);
    }
    case LUA_VLCL: {
      Proto *p = clLvalue(s2v(func))->p;
      int fsize = p->maxstacksize;
      int nfixparams = p->numparams;
      int i;
      checkstackGC(L, fsize);
      ci->func -= delta;
      for (i = 0; i < narg1; i++)
        setobjs2s(L, ci->func + i, func + i);
      func = ci->func;
      if (narg1 <= nfixparams) {
        for (; narg1 <= nfixparams; narg1++)
          setnilvalue(s2v(func + narg1));
      }
      ci->top = func + 1 + fsize;
      ci->u.l.savedpc = p->code;
      ci->callstatus |= CIST_TAIL;
      L->top = ci->top;
      return -1;
    }
    default: {
      return precall(L, func, LUA_MULTRET);
    }
  }
}

