  if (!(mask & (LUA_MASKLINE | LUA_MASKCOUNT))) {
    ci->u.l.trap = 0;
    return 0;
  }
  pc++;
  ci->u.l.savedpc = pc;
  counthook = (--L->hookcount == 0 && (mask & LUA_MASKCOUNT));
  if (counthook) {
    resethookcount(L);
    luaD_hook(L, LUA_HOOKCOUNT, -1, 0, 0);
  }
  if (mask & LUA_MASKLINE) {
    const ls_byte *lp;
    int newline;
    if (p->lineinfo == NULL)
      return 0;
    if (pc == p->code)
      newline = p->linedefined;
    else
      newline = luaG_getfuncline(p, pcRel(pc, p));
    if (newline != L->oldpc || counthook || ci->callstatus & CIST_HOOKYIELD) {
      luaD_hook(L, LUA_HOOKLINE, newline, 0, 0);
      ci = L->ci;
