static void funcinfo (lua_Debug *ar, Closure *cl) {
  if (noLuaClosure(cl)) {
    ar->source = "=[C]";
    ar->srclen = UD_SRCLEN;
    ar->linedefined = -1;
    ar->lastlinedefined = -1;
    ar->what = "C";
  }
  else {
    const Proto *p = cl->l.p;
    if (p->source) {
      ar->source = getstr(p->source);
      ar->srclen = tsslen(p->source);
    }
    else {
      ar->source = "=?";
      ar->srclen = 2;
    }
    ar->linedefined = p->linedefined;
    ar->lastlinedefined = p->lastlinedefined;
    ar->what = (ar->linedefined == 0) ? "main" : "Lua";
  }
  luaO_chunkid(ar->short_src, ar->source, ar->srclen);
}

#define UD_SRCLEN  2

static int nextline (const Proto *p, int currentline, int pc) {
  if (p->lineinfo != NULL)
    return luaG_getfuncline(p, pc);
  else return currentline;
}

int luaG_getfuncline (const Proto *f, int pc) {
  if (f->lineinfo == NULL)
    return -1;
  {
    int basepc = 0;
    int baseline = f->linedefined;
    int i;
    for (i = 0; i < f->sizeabslineinfo && f->abslineinfo[i].pc <= pc; i++) {
      basepc = f->abslineinfo[i].pc;
      baseline = f->abslineinfo[i].line;
    }
    {
      int curpc;
      for (curpc = basepc; curpc < pc; curpc++) {
        int delta = f->lineinfo[curpc];
        if (delta == ABSLINEINFO) {
          /* should not happen if abslineinfo is correct */
          return -1;
        }
        baseline += delta;
      }
    }
    return baseline;
  }
}

static int currentline (CallInfo *ci) {
  return luaG_getfuncline(ci_func(ci)->p, currentpc(ci));
}

#define currentpc(ci)  ((int)((ci)->u.l.savedpc - ci_func(ci)->p->code) - 1)

