static const char *findupvalue (Closure *cl, int n) {
  if (cl->c.tt == LUA_VLCL) {
    int i;
    const Proto *p = cl->l.p;
    for (i = 0; i < p->sizeupvalues; i++) {
      if (p->upvalues[i].name)
        n--;
      if (n == 0)
        return getstr(p->upvalues[i].name);
    }
  }
  return NULL;
}

LUA_API const char *lua_getupvalue (lua_State *L, int funcindex, int n) {
  const char *name;
  TValue *val = NULL;
  lua_lock(L);
  name = aux_upvalue(index2value(L, funcindex), n, &val, NULL, NULL);
  if (name) {
    setobj2s(L, L->top, val);
    api_incr_top(L);
  }
  lua_unlock(L);
  return name;
}

LUA_API const char *lua_setupvalue (lua_State *L, int funcindex, int n) {
  const char *name;
  TValue *val = NULL;
  GCObject **owner = NULL;
  UpVal *uv = NULL;
  TValue *fi;
  lua_lock(L);
  fi = index2value(L, funcindex);
  name = aux_upvalue(fi, n, &val, &owner, &uv);
  if (name) {
    L->top--;
    setobj(L, val, s2v(L->top));
    if (uv != NULL)
      luaC_barrier(L, uv, s2v(L->top));
    else {
      lua_assert(owner != NULL);
      luaC_barrier(L, obj2gco(gcvalue(fi)), s2v(L->top));
    }
  }
  lua_unlock(L);
  return name;
}

static const char *aux_upvalue (TValue *fi, int n, TValue **val,
                                GCObject **owner, UpVal **uv) {
  switch (ttypetag(fi)) {
    case LUA_VCCL: {
      CClosure *f = clCvalue(fi);
      if (!(1 <= n && n <= f->nupvalues)) return NULL;
      *val = &f->upvalue[n-1];
      if (owner) *owner = obj2gco(f);
      return "";
    }
    case LUA_VLCL: {
      LClosure *f = clLvalue(fi);
      TString *name;
      Proto *p = f->p;
      if (!(1 <= n && n <= p->sizeupvalues)) return NULL;
      *val = f->upvals[n-1]->v.p;
      if (uv) *uv = f->upvals[n-1];
      name = p->upvalues[n-1].name;
      return (name == NULL) ? "(no name)" : getstr(name);
    }
    default: return NULL;
  }
}

LUA_API void *lua_upvalueid (lua_State *L, int fidx, int n) {
  TValue *fi = index2value(L, fidx);
  switch (ttypetag(fi)) {
    case LUA_VLCL: {
      return f_upvalues(clLvalue(fi)->upvals, n);
    }
    case LUA_VCCL: {
      CClosure *f = clCvalue(fi);
      if (1 <= n && n <= f->nupvalues)
        return &f->upvalue[n - 1];
      return NULL;
    }
    default: return NULL;
  }
}

static void *f_upvalues (UpVal **upvals, int n) {
  return (void *)upvals[n-1];
}

LUA_API void lua_upvaluejoin (lua_State *L, int fidx1, int n1,
                                           int fidx2, int n2) {
  LClosure *f1;
  UpVal **up1 = getupvalref(L, fidx1, n1, &f1);
  UpVal **up2 = getupvalref(L, fidx2, n2, NULL);
  luaF_unlinkupval(*up1);
  *up1 = *up2;
  luaC_objbarrier(L, f1, *up1);
}

static UpVal **getupvalref (lua_State *L, int fidx, int n, LClosure **pf) {
  static UpVal *const dummyup = NULL;
  LClosure *f = NULL;
  TValue *fi = index2value(L, fidx);
  if (pf) *pf = NULL;
  if (ttypetag(fi) != LUA_VLCL || n < 1 || n > clLvalue(fi)->nupvalues)
    return cast(UpVal **, cast_voidp(&dummyup));
  f = clLvalue(fi);
  if (pf) *pf = f;
  return &f->upvals[n - 1];
}

int luaG_traceexec (lua_State *L, const Instruction *pc) {
  CallInfo *ci = L->ci;
  lu_byte mask = L->hookmask;
  const Proto *p = ci_func(ci)->p;
  int counthook;
  if (!(mask & (LUA_MASKLINE | LUA_MASKCOUNT))) {
    ci->u.l.trap = 0;
    return 0;
  }
  pc++;
  ci->u.l.savedpc = pc;
  counthook = (--L->hookcount == 0 && (mask & LUA_MASKCOUNT));
  if (counthook) {
    resethookcount(L);
    luaD_hook(L, LUA_HOOKCOUNT, -1, 0, 0);
  }
  if (mask & LUA_MASKLINE) {
    const ls_byte *lp;
    int newline;
    if (p->lineinfo == NULL)
      return 0;
    if (pc == p->code)
      newline = p->linedefined;
    else
      newline = luaG_getfuncline(p, pcRel(pc, p));
    if (newline != L->oldpc || counthook || ci->callstatus & CIST_HOOKYIELD) {
      luaD_hook(L, LUA_HOOKLINE, newline, 0, 0);
      ci = L->ci;
      L->oldpc = newline;
    }
  }
  if (l_unlikely(L->status == LUA_YIELD)) {
    ci->u.l.savedpc--;  /* undo 'pc++' */
    ci->u2.nyield = 0;
    setivalue(s2v(L->top++), 0);
    luaD_throw(L, LUA_YIELD);
  }
  return (mask & LUA_MASKLINE) ? 1 : 0;
}

