LUA_API int lua_getstack (lua_State *L, int level, lua_Debug *ar) {
  int status;
  CallInfo *ci;
  if (level < 0) return 0;
  lua_lock(L);
  for (ci = L->ci; level > 0 && ci != &L->base_ci; ci = ci->previous)
    level--;
  if (level == 0 && ci != &L->base_ci) {
    ar->i_ci = ci;
    status = 1;
  }
  else status = 0;
  lua_unlock(L);
  return status;
}

static int isinstack (CallInfo *ci, const TValue *o) {
  StkId p;
  for (p = ci->func + 1; p < ci->top; p++)
    if (s2v(p) == o) return cast_int(p - ci->func);
  return 0;
}

static void funcname (lua_State *L, CallInfo *ci, const char **name) {
  /* simplified version */
  TMS tm = (TMS)0;
  StkId base = ci->func + 1;
  *name = "?";
}

LUA_API int lua_getinfo (lua_State *L, const char *what, lua_Debug *ar) {
  int status = 1;
  Closure *cl;
  CallInfo *ci;
  TValue *f;
  lua_lock(L);
  if (*what == '>') {
    ci = NULL;
    f = s2v(L->top - 1);
    api_check(L, ttisfunction(f), "function expected");
    what++;
    L->top--;
  }
  else {
    ci = ar->i_ci;
    f = s2v(ci->func);
    lua_assert(ttisfunction(f));
  }
  cl = ttisclosure(f) ? clvalue(f) : NULL;
  for (; *what; what++) {
    switch (*what) {
      case 'S': {
        funcinfo(ar, cl);
        break;
      }
      case 'l': {
        ar->currentline = (ci && isLua(ci)) ? currentline(ci) : -1;
        break;
      }
      case 'u': {
        ar->nups = (cl == NULL) ? 0 : cl->c.nupvalues;
        if (noLuaClosure(cl)) {
          ar->isvararg = 1;
          ar->nparams = 0;
        }
        else {
          ar->isvararg = cl->l.p->is_vararg;
          ar->nparams = cl->l.p->numparams;
        }
        break;
      }
      case 't': {
        ar->istailcall = (ci) ? ci->callstatus & CIST_TAIL : 0;
        break;
      }
      case 'n': {
        ar->namewhat = "?";
        ar->name = NULL;
        if (ci) {
          funcname(L, ci, &ar->name);
        }
        if (ar->name == NULL) {
          ar->namewhat = "";
          ar->name = NULL;
        }
        break;
      }
      case 'r': {
        if (ci == NULL || !(ci->callstatus & CIST_TRAN)) {
          ar->ftransfer = ar->ntransfer = 0;
        }
        else {
          ar->ftransfer = ci->u2.transferinfo.ftransfer;
          ar->ntransfer = ci->u2.transferinfo.ntransfer;
        }
        break;
      }
      case 'L':
      case 'f': {
        if (*what == 'f') {
          setobj2s(L, L->top, f);
          api_incr_top(L);
        }
        else {
          /* push table of valid lines */
          if (!noLuaClosure(cl)) {
            Proto *p = cl->l.p;
            int i;
            lua_createtable(L, 0, 0);
            for (i = 0; i < p->sizelineinfo; i++) {
              lua_pushboolean(L, 1);
              lua_rawseti(L, -2, luaG_getfuncline(p, i));
            }
          }
          else
            lua_pushnil(L);
        }
        break;
      }
      default: status = 0; break;
    }
  }
  lua_unlock(L);
  return status;
}

l_noret luaG_typeerror (lua_State *L, const TValue *o, const char *opname) {
