#define luai_verifycode(L,f)  /* empty */
#endif

typedef struct {
  lua_State *L;
  ZIO *Z;
  const char *name;
} LoadState;

static l_noret error (LoadState *S, const char *why) {
  luaO_pushfstring(S->L, "%s: bad binary format (%s)", S->name, why);
  luaD_throw(S->L, LUA_ERRSYNTAX);
}

#define load_var(S,x)   load_block(S, &x, sizeof(x))

static void load_block (LoadState *S, void *b, size_t size) {
  if (luaZ_read(S->Z, b, size) != 0)
    error(S, "truncated chunk");
}

static lu_byte loadByte (LoadState *S) {
  int b = zgetc(S->Z);
  if (b == EOZ) error(S, "truncated chunk");
  return cast_byte(b);
}

static size_t loadVarint (LoadState *S) {
  size_t x = 0;
  int b;
  int limit = 0;
  do {
    b = loadByte(S);
    if (limit++ > 9) error(S, "integer too large");
    x = (x << 7) | (b & 0x7F);
  } while ((b & 0x80) != 0);
  return x;
}

static lua_Integer loadInteger (LoadState *S) {
  return cast(lua_Integer, loadVarint(S));
}

static lua_Number loadNumber (LoadState *S) {
  lua_Number x;
  load_var(S, x);
  return x;
}

static TString *loadString (LoadState *S, const Proto *f) {
  size_t size = loadVarint(S);
  if (size == 0)
    return NULL;
  else if (size == 0xFF) {
    TString *ts;
    size = loadVarint(S);
    char *b = luaM_newvector(S->L, size, char);
    load_block(S, b, size);
    ts = luaS_newlstr(S->L, b, size);
    luaM_freearray(S->L, b, size);
    return ts;
  }
  else {
    char *b = luaM_newvector(S->L, size, char);
    load_block(S, b, size);
    TString *ts = luaS_newlstr(S->L, b, size);
    luaM_freearray(S->L, b, size);
    return ts;
  }
}

static void loadCode (LoadState *S, Proto *f) {
  int n = cast_int(loadVarint(S));
  f->code = luaM_newvector(S->L, n, Instruction);
  f->sizecode = n;
  load_block(S, f->code, cast_sizet(n) * sizeof(Instruction));
}

static void loadFunction (LoadState *S, Proto *f, TString *psource);

static void loadConstants (LoadState *S, Proto *f) {
  int i, n;
  n = cast_int(loadVarint(S));
  f->k = luaM_newvector(S->L, n, TValue);
  f->sizek = n;
  for (i = 0; i < n; i++) setnilvalue(&f->k[i]);
  for (i = 0; i < n; i++) {
    TValue *o = &f->k[i];
    int t = loadByte(S);
    switch (t) {
      case LUA_VNIL:
        setnilvalue(o);
        break;
      case LUA_VFALSE:
        setbvalue(o, 0);
        break;
      case LUA_VTRUE:
        setbvalue(o, 1);
        break;
      case LUA_VNUMFLT:
        setfltvalue(o, loadNumber(S));
        break;
      case LUA_VNUMINT:
        setivalue(o, loadInteger(S));
        break;
      case LUA_VSHRSTR:
      case LUA_VLNGSTR:
        setsvalue(S->L, o, loadString(S, f));
        break;
      default: error(S, "unknown constant type");
    }
  }
}

static void loadProtos (LoadState *S, Proto *f) {
  int i, n;
  n = cast_int(loadVarint(S));
  f->p = luaM_newvector(S->L, n, Proto *);
  f->sizep = n;
  for (i = 0; i < n; i++) f->p[i] = NULL;
  for (i = 0; i < n; i++) {
    f->p[i] = luaF_newproto(S->L);
    loadFunction(S, f->p[i], f->source);
  }
}

static void loadUpvalues (LoadState *S, Proto *f) {
  int i, n;
  n = cast_int(loadVarint(S));
  f->upvalues = luaM_newvector(S->L, n, Upvaldesc);
  f->sizeupvalues = n;
  for (i = 0; i < n; i++) {
    f->upvalues[i].name = NULL;
    f->upvalues[i].instack = loadByte(S);
    f->upvalues[i].idx = loadByte(S);
    f->upvalues[i].kind = loadByte(S);
  }
}

static void loadDebug (LoadState *S, Proto *f) {
  int i, n;
  n = cast_int(loadVarint(S));
  f->lineinfo = luaM_newvector(S->L, n, ls_byte);
  f->sizelineinfo = n;
  load_block(S, f->lineinfo, cast_sizet(n) * sizeof(ls_byte));
  n = cast_int(loadVarint(S));
  f->abslineinfo = luaM_newvector(S->L, n, AbsLineInfo);
  f->sizeabslineinfo = n;
  load_block(S, f->abslineinfo, cast_sizet(n) * sizeof(AbsLineInfo));
  n = cast_int(loadVarint(S));
  f->locvars = luaM_newvector(S->L, n, LocVar);
  f->sizelocvars = n;
  for (i = 0; i < n; i++) {
    f->locvars[i].varname = NULL;
    f->locvars[i].startpc = 0;
    f->locvars[i].endpc = 0;
  }
  for (i = 0; i < n; i++) {
    f->locvars[i].varname = loadString(S, f);
    f->locvars[i].startpc = cast_int(loadVarint(S));
    f->locvars[i].endpc = cast_int(loadVarint(S));
  }
  n = cast_int(loadVarint(S));
  for (i = 0; i < n; i++) {
    f->upvalues[i].name = loadString(S, f);
  }
}

static void loadFunction (LoadState *S, Proto *f, TString *psource) {
  f->source = loadString(S, f);
  if (f->source == NULL) f->source = psource;
  f->linedefined = cast_int(loadVarint(S));
  f->lastlinedefined = cast_int(loadVarint(S));
  f->numparams = loadByte(S);
  f->is_vararg = loadByte(S);
  f->maxstacksize = loadByte(S);
  loadCode(S, f);
  loadConstants(S, f);
  loadUpvalues(S, f);
  loadProtos(S, f);
  loadDebug(S, f);
}

static void checkHeader (LoadState *S) {
  char buff[sizeof(LUA_SIGNATURE) - sizeof(char)];
  char luac_data[sizeof(LUAC_DATA)];
  load_block(S, buff, sizeof(buff));
  if (memcmp(buff, LUA_SIGNATURE + sizeof(char), sizeof(buff)) != 0)
    error(S, "not a binary chunk");
  if (loadByte(S) != LUAC_VERSION)
    error(S, "version mismatch");
  if (loadByte(S) != LUAC_FORMAT)
