static void checkHeader (LoadState *S) {
  char buff[sizeof(LUA_SIGNATURE) - sizeof(char)];
  char luac_data[sizeof(LUAC_DATA)];
  load_block(S, buff, sizeof(buff));
  if (memcmp(buff, LUA_SIGNATURE + sizeof(char), sizeof(buff)) != 0)
    error(S, "not a binary chunk");
  if (loadByte(S) != LUAC_VERSION)
    error(S, "version mismatch");
  if (loadByte(S) != LUAC_FORMAT)
    error(S, "format mismatch");
  load_block(S, luac_data, sizeof(luac_data));
  if (memcmp(luac_data, LUAC_DATA, sizeof(luac_data)) != 0)
    error(S, "corrupted chunk");
  if (loadByte(S) != cast_byte(sizeof(Instruction)))
    error(S, "instruction size mismatch");
  {
    lua_Integer x = LUAC_INT;
    lua_Integer y;
    load_var(S, y);
    if (y != x) error(S, "integer format mismatch");
  }
  {
    lua_Number x = LUAC_NUM;
    lua_Number y;
    load_var(S, y);
    if (y != x) error(S, "float format mismatch");
  }
