static void dumpBlock (DumpState *D, const void *b, size_t size) {
  if (D->status == 0 && size > 0) {
    lua_unlock(D->L);
    D->status = (*D->writer)(D->L, b, size, D->data);
    lua_lock(D->L);
  }
}

static void dumpByte (DumpState *D, int y) {
  lu_byte x = cast_byte(y);
  dumpBlock(D, &x, sizeof(x));
}

static void dumpVarint (DumpState *D, size_t x) {
  lu_byte buff[10];
  int n = 1;
  buff[9] = x & 0x7F;
  while ((x >>= 7) != 0) {
    buff[10 - (++n)] = cast_byte((x & 0x7F) | 0x80);
  }
  dumpBlock(D, buff + 10 - n, n);
}

static void dumpSize (DumpState *D, size_t x) {
  dumpVarint(D, x);
}

static void dumpInt (DumpState *D, int x) {
  dumpVarint(D, cast_sizet(x));
}

static void dumpNumber (DumpState *D, lua_Number x) {
  dumpVar(D, x);
}

static void dumpInteger (DumpState *D, lua_Integer x) {
  dumpVarint(D, cast_sizet(x));
}

static void dumpString (DumpState *D, const TString *s) {
  if (s == NULL)
    dumpSize(D, 0);
  else {
    size_t l = tsslen(s);
    const char *str = getstr(s);
    dumpSize(D, l + 1);
    dumpBlock(D, str, l * sizeof(char));
  }
}

static void dumpCode (DumpState *D, const Proto *f) {
  dumpInt(D, f->sizecode);
  dumpBlock(D, f->code, cast_sizet(f->sizecode) * sizeof(Instruction));
}

static void dumpFunction (DumpState *D, const Proto *f, TString *psource);

static void dumpConstants (DumpState *D, const Proto *f) {
  int i, n = f->sizek;
  dumpInt(D, n);
  for (i = 0; i < n; i++) {
    const TValue *o = &f->k[i];
    int tt = ttypetag(o);
    dumpByte(D, tt);
    switch (tt) {
      case LUA_VNIL: break;
      case LUA_VFALSE: break;
      case LUA_VTRUE: break;
      case LUA_VNUMFLT:
        dumpNumber(D, fltvalue(o));
        break;
      case LUA_VNUMINT:
        dumpInteger(D, ivalue(o));
        break;
      case LUA_VSHRSTR:
      case LUA_VLNGSTR:
        dumpString(D, tsvalue(o));
        break;
      default: lua_assert(0);
    }
  }
}

static void dumpProtos (DumpState *D, const Proto *f) {
  int i, n = f->sizep;
  dumpInt(D, n);
  for (i = 0; i < n; i++)
    dumpFunction(D, f->p[i], f->source);
}

static void dumpUpvalues (DumpState *D, const Proto *f) {
  int i, n = f->sizeupvalues;
  dumpInt(D, n);
  for (i = 0; i < n; i++) {
    dumpByte(D, f->upvalues[i].instack);
    dumpByte(D, f->upvalues[i].idx);
    dumpByte(D, f->upvalues[i].kind);
  }
}

static void dumpDebug (DumpState *D, const Proto *f) {
  int i, n;
  n = D->strip ? 0 : f->sizelineinfo;
  dumpInt(D, n);
  dumpBlock(D, f->lineinfo, cast_sizet(n) * sizeof(ls_byte));
  n = D->strip ? 0 : f->sizeabslineinfo;
  dumpInt(D, n);
  dumpBlock(D, f->abslineinfo, cast_sizet(n) * sizeof(AbsLineInfo));
  n = D->strip ? 0 : f->sizelocvars;
  dumpInt(D, n);
  for (i = 0; i < n; i++) {
    dumpString(D, f->locvars[i].varname);
    dumpInt(D, f->locvars[i].startpc);
    dumpInt(D, f->locvars[i].endpc);
  }
  n = D->strip ? 0 : f->sizeupvalues;
  dumpInt(D, n);
  for (i = 0; i < n; i++)
    dumpString(D, f->upvalues[i].name);
}

static void dumpFunction (DumpState *D, const Proto *f, TString *psource) {
  if (D->strip || f->source == psource)
    dumpString(D, NULL);
  else
    dumpString(D, f->source);
  dumpInt(D, f->linedefined);
  dumpInt(D, f->lastlinedefined);
  dumpByte(D, f->numparams);
  dumpByte(D, f->is_vararg);
  dumpByte(D, f->maxstacksize);
  dumpCode(D, f);
  dumpConstants(D, f);
  dumpUpvalues(D, f);
  dumpProtos(D, f);
  dumpDebug(D, f);
}

static void dumpHeader (DumpState *D) {
  dumpBlock(D, LUA_SIGNATURE, sizeof(LUA_SIGNATURE) - sizeof(char));
  dumpByte(D, LUAC_VERSION);
  dumpByte(D, LUAC_FORMAT);
  dumpBlock(D, LUAC_DATA, sizeof(LUAC_DATA));
  dumpByte(D, cast_byte(sizeof(Instruction)));
  {
    lua_Integer x = LUAC_INT;
    dumpVar(D, x);
  }
  {
    lua_Number x = LUAC_NUM;
    dumpVar(D, x);
  }
}

int luaU_dump (lua_State *L, const Proto *f, lua_Writer w, void *data,
               int strip) {
  DumpState D;
  D.L = L;
  D.writer = w;
  D.data = data;
  D.strip = strip;
  D.status = 0;
  dumpHeader(&D);
  dumpByte(&D, f->sizeupvalues);
  dumpFunction(&D, f, NULL);
  return D.status;
}

