LUA_API void lua_rotate (lua_State *L, int idx, int n) {
  StkId p, t, m;
  lua_lock(L);
  t = L->top - 1;
  p = index2stack(L, idx);
  api_check(L, (n >= 0 ? n : -n) <= (t - p + 1), "invalid 'n'");
  m = (n >= 0 ? t - n : p - n - 1);
  reverse(p, m);
  reverse(m + 1, t);
  reverse(p, t);
  lua_unlock(L);
}

static void reverse (StkId from, StkId to) {
  for (; from < to; from++, to--) {
    TValue temp;
    setobj(cast_state(NULL), &temp, s2v(from));
    setobjs2s(cast_state(NULL), from, to);
    setobj2s(cast_state(NULL), to, &temp);
