LUA_API int lua_gc (lua_State *L, int what, ...) {
  va_list argp;
  int res = 0;
  global_State *g;
  lua_lock(L);
  g = G(L);
  va_start(argp, what);
  switch (what) {
    case LUA_GCSTOP: {
      g->gcstp = 1;
      break;
    }
    case LUA_GCRESTART: {
      luaE_setdebt(g, 0);
      g->gcstp = 0;
      break;
    }
    case LUA_GCCOLLECT: {
      luaC_fullgc(L, 0);
      break;
    }
    case LUA_GCCOUNT: {
      lu_mem b = gettotalbytes(g);
      res = cast_int(b >> 10);
      break;
    }
    case LUA_GCCOUNTB: {
      res = cast_int(gettotalbytes(g) & 0x3ff);
      break;
    }
    case LUA_GCSTEP: {
      int data = va_arg(argp, int);
      l_mem debt = 1;
      lu_byte oldstp = g->gcstp;
      g->gcstp = 0;
      if (data == 0) {
        luaE_setdebt(g, 0);
        luaC_step(L);
      }
      else {
        debt = cast(l_mem, data) * 1024 - (cast(l_mem, g->GCdebt));
        luaE_setdebt(g, debt);
        luaC_checkGC(L);
      }
      g->gcstp = oldstp;
      res = (g->gcstate == GCSpause);
      break;
    }
    case LUA_GCISRUNNING: {
      res = gcrunning(g);
      break;
    }
    case LUA_GCGEN: {
      res = (g->gckind == KGC_GEN) ? LUA_GCGEN : LUA_GCINC;
      luaC_changemode(L, KGC_GEN);
      break;
    }
    case LUA_GCINC: {
      int pause = va_arg(argp, int);
      int stepmul = va_arg(argp, int);
      int stepsize = va_arg(argp, int);
      res = (g->gckind == KGC_INC) ? LUA_GCINC : LUA_GCGEN;
      luaC_changemode(L, KGC_INC);
      if (pause != 0) g->gcpause = pause;
      if (stepmul != 0) g->gcstepmul = stepmul;
      if (stepsize != 0) g->gcstepsize = stepsize;
      break;
    }
    case LUA_GCPARAM: {
      /* Lua 5.5: get/set GC parameter */
      const char *param = va_arg(argp, const char *);
      int newval;
      int hasval = 0;
      /* check for optional 3rd argument (new value) */
      /* In C varargs, we need to know if there's a 3rd arg.
         Actually in Lua 5.5, lua_gc is called with 2 or 3 args. */
      /* For now, just get/set based on param name */
      if (strcmp(param, "minormul") == 0) {
        res = g->genminormul;
        /* Check if new value was provided */
        /* This is tricky in C varargs - assume optional */
      }
      else if (strcmp(param, "majorminor") == 0) {
        res = g->genmajormul;
      }
      else if (strcmp(param, "minormajor") == 0) {
        res = 50;  /* default */
      }
      else if (strcmp(param, "pause") == 0) {
        res = g->gcpause;
      }
      else if (strcmp(param, "stepmul") == 0) {
        res = g->gcstepmul;
      }
      else if (strcmp(param, "stepsize") == 0) {
        res = g->gcstepsize * 1024;
      }
      break;
    }
    default: res = -1;
  }
  va_end(argp);
  lua_unlock(L);
  return res;
}

