/*
** $Id: loadlib.c $
** Dynamic library loader for Lua
** See Copyright Notice in lua.h
*/

#define loadlib_c
#define LUA_LIB

#include "lprefix.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "lua.h"
#include "lauxlib.h"
#include "lualib.h"

#define LIB_FAIL	"open"
#define setprogdir(L)		((void)0)

#if defined(LUA_USE_POSIX)
#include <dlfcn.h>

static void ll_unloadlib (void *lib) {
  dlclose(lib);
}

static void *ll_load (lua_State *L, const char *path, int seeglb) {
  void *lib = dlopen(path, RTLD_NOW | (seeglb ? RTLD_GLOBAL : RTLD_LOCAL));
  if (lib == NULL) lua_pushstring(L, dlerror());
  return lib;
}

static lua_CFunction ll_sym (lua_State *L, void *lib, const char *sym) {
  lua_CFunction f = (lua_CFunction)(intptr_t)dlsym(lib, sym);
  if (f == NULL) lua_pushstring(L, dlerror());
  return f;
}

#elif defined(LUA_USE_WINDOWS)
#include <windows.h>

static void ll_unloadlib (void *lib) {
  FreeLibrary((HMODULE)lib);
}

static void *ll_load (lua_State *L, const char *path, int seeglb) {
  HMODULE lib = LoadLibraryExA(path, NULL, LUA_LIB_FLAG);
  (void)seeglb;
  if (lib == NULL) {
    char buff[128];
    DWORD err = GetLastError();
    sprintf(buff, "error loading: Win32 error %d", (int)err);
    lua_pushstring(L, buff);
  }
  return lib;
}

static lua_CFunction ll_sym (lua_State *L, void *lib, const char *sym) {
  lua_CFunction f = (lua_CFunction)(intptr_t)GetProcAddress((HMODULE)lib, sym);
  if (f == NULL) lua_pushfstring(L, "symbol '%s' not found", sym);
  return f;
}

#else
/* stub for unsupported platforms */
static void ll_unloadlib (void *lib) { (void)lib; }
static void *ll_load (lua_State *L, const char *path, int seeglb) {
  (void)path; (void)seeglb;
  lua_pushstring(L, "dynamic libraries not enabled; check your Lua installation");
  return NULL;
}
static lua_CFunction ll_sym (lua_State *L, void *lib, const char *sym) {
  (void)lib; (void)sym;
  lua_pushstring(L, "dynamic libraries not enabled");
  return NULL;
}
#endif

/* -- Userdata tag for library handles */
static const char *const LLHANDLE = "LOADLIB: library handles";

typedef struct Udata_Lib {
  void *lib;
} Udata_Lib;

static Udata_Lib *plib (lua_State *L, int idx) {
  return (Udata_Lib *)luaL_checkudata(L, idx, LLHANDLE);
}

static int gctm (lua_State *L) {
  Udata_Lib *lib = plib(L, 1);
  if (lib->lib != NULL) {
    ll_unloadlib(lib->lib);
    lib->lib = NULL;
  }
  return 0;
}

static int ll_loadfunc (lua_State *L, const char *path, const char *sym) {
  Udata_Lib *reg;
  void *lib;
  int status;
  if (*path == '*') {
    lib = ll_load(L, NULL, 1);
    path = NULL;
  }
  else
    lib = ll_load(L, path, 0);
  if (lib == NULL) return ERRLIB;
  reg = (Udata_Lib *)lua_newuserdatauv(L, sizeof(Udata_Lib), 0);
  reg->lib = NULL;
  luaL_setmetatable(L, LLHANDLE);
  reg->lib = lib;
  lua_CFunction f = ll_sym(L, lib, sym);
  if (f == NULL) {
    lua_pop(L, 1);
    ll_unloadlib(lib);
    reg->lib = NULL;
    return ERRSYM;
  }
  lua_pushcfunction(L, f);
  lua_remove(L, -2);
  return LUA_OK;
}

#define ERRLIB		1
#define ERRSYM		2

static int ll_require (lua_State *L) {
  const char *name = luaL_checkstring(L, 1);
  lua_settop(L, 1);
  lua_getfield(L, LUA_REGISTRYINDEX, LUA_LOADED_TABLE);
  lua_getfield(L, 2, name);
  if (lua_toboolean(L, -1))
    return 1;
  lua_pop(L, 1);
  /* call searchers */
  lua_getfield(L, LUA_REGISTRYINDEX, "_SEARCHERS");
  if (!lua_istable(L, -1))
    luaL_error(L, "'package.searchers' must be a table");
  {
    int i;
    for (i = 1; ; i++) {
      luaL_Buffer msg;
      lua_Integer n;
      luaL_buffinit(L, &msg);
      if (lua_rawgeti(L, -1, i) == LUA_TNIL) {
        lua_pop(L, 1);
        luaL_pushresult(&msg);
        return luaL_error(L, "module '%s' not found:\n%s",
                             name, lua_tostring(L, -1));
      }
      lua_pushstring(L, name);
      lua_call(L, 1, 2);
      if (lua_isfunction(L, -2)) {
        lua_pushstring(L, name);
        lua_call(L, 1, 1);
        if (lua_isnil(L, -1))
          lua_pushboolean(L, 1);
        lua_setfield(L, 2, name);
        lua_getfield(L, 2, name);
        return 1;
      }
      lua_pop(L, 2);
    }
  }
}

/* -- Searchers */
static int searcher_preload (lua_State *L) {
  const char *name = luaL_checkstring(L, 1);
  lua_getfield(L, LUA_REGISTRYINDEX, LUA_PRELOAD_TABLE);
  if (lua_getfield(L, -1, name) == LUA_TNIL) {
    lua_pushfstring(L, "\n\tno field package.preload['%s']", name);
    return 1;
  }
  else {
    lua_pushliteral(L, ":preload:");
    return 2;
  }
}

static int searcher_lua (lua_State *L) {
  const char *name = luaL_checkstring(L, 1);
  const char *filename;
  lua_getfield(L, lua_upvalueindex(1), "path");
  if (!lua_isstring(L, -1))
    return luaL_error(L, "'package.path' must be a string");
  filename = luaL_searchpath(L, name, lua_tostring(L, -1), ".", LUA_DIRSEP);
  if (filename == NULL) return 1;
  return checkload(L, (luaL_loadfile(L, filename) == LUA_OK), filename);
}

static int searcher_clib (lua_State *L) {
  const char *name = luaL_checkstring(L, 1);
  const char *filename;
  lua_getfield(L, lua_upvalueindex(1), "cpath");
  if (!lua_isstring(L, -1))
    return luaL_error(L, "'package.cpath' must be a string");
  filename = luaL_searchpath(L, name, lua_tostring(L, -1), ".", LUA_DIRSEP);
  if (filename == NULL) return 1;
  {
    const char *funcname = pushfuncname(L, name);
    if (ll_loadfunc(L, filename, funcname) != LUA_OK)
      return checkload(L, 0, filename);
    return 1;
  }
}

static const char *pushfuncname (lua_State *L, const char *name) {
  const char *p = strchr(name, '-');
  const char *end = strchr(name, '\0');
  if (p == NULL) p = end;
  lua_pushlstring(L, name, p - name);
  lua_pushfstring(L, "luaopen_%s", lua_tostring(L, -1));
  lua_remove(L, -2);
  {
    const char *fname = lua_tostring(L, -1);
    luaL_gsub(L, fname, ".", "_");
    lua_remove(L, -2);
    return lua_tostring(L, -1);
  }
}

static int checkload (lua_State *L, int stat, const char *filename) {
  if (stat) {
    lua_pushstring(L, filename);
    return 2;
  }
  else
    return luaL_error(L, "error loading module '%s' from file '%s':\n\t%s",
                          lua_tostring(L, 1), filename, lua_tostring(L, -1));
}

static int ll_searchpath (lua_State *L) {
  const char *f = luaL_searchpath(L, luaL_checkstring(L, 1),
                                     luaL_checkstring(L, 2),
                                     luaL_optstring(L, 3, "."),
                                     luaL_optstring(L, 4, LUA_DIRSEP));
  if (f != NULL) return 1;
  else {
    luaL_pushfail(L);
    lua_insert(L, -2);
    return 2;
  }
}

static const char *luaL_searchpath (lua_State *L, const char *name,
                                    const char *path, const char *sep,
                                    const char *dirsep) {
  luaL_Buffer msg;
  luaL_buffinit(L, &msg);
  if (*sep != '\0')
    name = luaL_gsub(L, name, sep, dirsep);
  while (*path != '\0') {
    const char *epath;
    epath = strchr(path, ';');
    if (epath == NULL) epath = path + strlen(path);
    {
      char *filename;
      size_t len = epath - path;
      char buff[len + strlen(name) + 10];
      const char *wild;
      memcpy(buff, path, len);
      buff[len] = '\0';
      wild = strchr(buff, '?');
      if (wild == NULL) {
        filename = buff;
      }
      else {
        /* replace ? with name */
        size_t nlen = strlen(name);
        size_t pos = wild - buff;
        char *newbuff = (char *)malloc(len + nlen + 1);
        memcpy(newbuff, buff, pos);
        memcpy(newbuff + pos, name, nlen);
        memcpy(newbuff + pos + nlen, wild + 1, len - pos - 1);
        newbuff[pos + nlen + (len - pos - 1)] = '\0';
        filename = newbuff;
      }
      {
        FILE *f = fopen(filename, "r");
        if (f != NULL) {
          fclose(f);
          lua_pushstring(L, filename);
          if (filename != buff) free(filename);
          return lua_tostring(L, -1);
        }
        luaL_addstring(&msg, "\n\tno file '");
        luaL_addstring(&msg, filename);
        luaL_addstring(&msg, "'");
        if (filename != buff) free(filename);
      }
    }
    path = epath + 1;
    if (*path == '\0') break;
  }
  luaL_pushresult(&msg);
  return NULL;
}

static int ll_loadlib (lua_State *L) {
  const char *path = luaL_checkstring(L, 1);
  const char *init = luaL_checkstring(L, 2);
  int stat = ll_loadfunc(L, path, init);
  if (stat == LUA_OK) return 1;
  else {
    luaL_pushfail(L);
    lua_insert(L, -2);
    lua_pushstring(L, (stat == ERRLIB) ? LIB_FAIL : "init");
    return 3;
  }
}

static const luaL_Reg pk_funcs[] = {
  {"loadlib", ll_loadlib},
  {"searchpath", ll_searchpath},
  {NULL, NULL}
};

static const luaL_Reg ll_funcs[] = {
  {"require", ll_require},
  {NULL, NULL}
};

static void createclibstable (lua_State *L) {
  luaL_getsubtable(L, LUA_REGISTRYINDEX, LUA_LOADED_TABLE);
  lua_setfield(L, -2, "loaded");
  luaL_getsubtable(L, LUA_REGISTRYINDEX, LUA_PRELOAD_TABLE);
  lua_setfield(L, -2, "preload");
}

static void createbuiltin_searchers (lua_State *L) {
  lua_createtable(L, 4, 0);
  /* preload searcher */
  lua_pushcfunction(L, searcher_preload);
  lua_rawseti(L, -2, 1);
  /* lua file searcher */
  lua_pushvalue(L, 1);  /* package table */
  lua_pushcclosure(L, searcher_lua, 1);
  lua_rawseti(L, -2, 2);
  /* clib searcher */
  lua_pushvalue(L, 1);
  lua_pushcclosure(L, searcher_clib, 1);
  lua_rawseti(L, -2, 3);
  lua_setfield(L, 1, "searchers");
  lua_getfield(L, 1, "searchers");
  lua_setfield(L, LUA_REGISTRYINDEX, "_SEARCHERS");
}

LUAMOD_API int luaopen_package (lua_State *L) {
  luaL_newmetatable(L, LLHANDLE);
  lua_pushcfunction(L, gctm);
  lua_setfield(L, -2, "__gc");
  lua_pop(L, 1);

  luaL_newlib(L, pk_funcs);
  createclibstable(L);
  lua_pushstring(L, LUA_PATH_DEFAULT);
  lua_setfield(L, -2, "path");
  lua_pushstring(L, LUA_CPATH_DEFAULT);
  lua_setfield(L, -2, "cpath");
  lua_pushstring(L, LUA_DIRSEP);
  lua_setfield(L, -2, "config");
  createbuiltin_searchers(L);
  lua_pushvalue(L, -1);
  luaL_setfuncs(L, ll_funcs, 0);
  lua_setglobal(L, "require");
  return 1;
}

