#if !defined(l_unlikely)
#define l_unlikely(x) (x)
#define l_likely(x) (x)
#endif

/* maximum size of each string buffer */
#define MAXSIZE   (sizeof(size_t) < sizeof(int) ? MAX_SIZET : (size_t)INT_MAX)

static int checknopts (lua_State *L, int *opts) {
  *opts = 0;
  return *opts;
}

static int str_len (lua_State *L) {
  size_t l;
  luaL_checklstring(L, 1, &l);
  lua_pushinteger(L, (lua_Integer)l);
  return 1;
}

static lua_Integer posrelat (lua_Integer pos, size_t len) {
  if (pos >= 0) return pos;
  else if (0u - (size_t)pos > len) return 0;
  else return (lua_Integer)len + pos + 1;
}

static int str_sub (lua_State *L) {
  size_t l;
  const char *s = luaL_checklstring(L, 1, &l);
  lua_Integer si = posrelat(luaL_checkinteger(L, 2), l);
  lua_Integer ei = posrelat(luaL_optinteger(L, 3, -1), l);
  if (si < 1) si = 1;
  if (ei > (lua_Integer)l) ei = (lua_Integer)l;
  if (si > ei) lua_pushliteral(L, "");
  else lua_pushlstring(L, s + si - 1, (size_t)(ei - si) + 1);
  return 1;
}

static int str_rep (lua_State *L) {
  size_t l, lsep;
  const char *s = luaL_checklstring(L, 1, &l);
  lua_Integer n = luaL_checkinteger(L, 2);
  const char *sep = luaL_optlstring(L, 3, "", &lsep);
  if (n <= 0) lua_pushliteral(L, "");
  else if (l_unlikely(l + lsep < l || l + lsep > MAXSIZE/n))
    return luaL_error(L, "resulting string too large");
  else {
    size_t totallen = (size_t)n * l + (size_t)(n - 1) * lsep;
    luaL_Buffer b;
    char *p = luaL_buffinitsize(L, &b, totallen);
    while (n-- > 1) {
      memcpy(p, s, l * sizeof(char)); p += l;
      if (lsep > 0) {
        memcpy(p, sep, lsep * sizeof(char));
        p += lsep;
      }
    }
    memcpy(p, s, l * sizeof(char));
    luaL_pushresultsize(&b, totallen);
  }
  return 1;
}

static int str_reverse (lua_State *L) {
  size_t l, i;
  luaL_Buffer b;
  const char *s = luaL_checklstring(L, 1, &l);
  char *p = luaL_buffinitsize(L, &b, l);
  for (i = 0; i < l; i++)
    p[i] = s[l - i - 1];
  luaL_pushresultsize(&b, l);
  return 1;
}

static int str_upper (lua_State *L) {
  size_t l, i;
  luaL_Buffer b;
  const char *s = luaL_checklstring(L, 1, &l);
  char *p = luaL_buffinitsize(L, &b, l);
  for (i = 0; i < l; i++)
    p[i] = toupper(uchar(s[i]));
  luaL_pushresultsize(&b, l);
  return 1;
}

static int str_lower (lua_State *L) {
  size_t l, i;
  luaL_Buffer b;
  const char *s = luaL_checklstring(L, 1, &l);
  char *p = luaL_buffinitsize(L, &b, l);
  for (i = 0; i < l; i++)
    p[i] = tolower(uchar(s[i]));
  luaL_pushresultsize(&b, l);
  return 1;
}

#define uchar(c) ((unsigned char)(c))

static int str_byte (lua_State *L) {
  size_t l;
  const char *s = luaL_checklstring(L, 1, &l);
  lua_Integer pi = posrelat(luaL_optinteger(L, 2, 1), l);
  lua_Integer pe = posrelat(luaL_optinteger(L, 3, pi), l);
  int n, i;
  if (pi < 1) pi = 1;
  if (pe > (lua_Integer)l) pe = (lua_Integer)l;
  if (pi > pe) return 0;
  n = (int)(pe - pi + 1);
  if (l_unlikely(n < 0))
    return luaL_error(L, "string slice too long");
  luaL_checkstack(L, n, "string slice too long");
  for (i=0; i<n; i++)
    lua_pushinteger(L, uchar(s[pi+i-1]));
  return n;
}

static int str_char (lua_State *L) {
  int n = lua_gettop(L);
  int i;
  luaL_Buffer b;
  char *p = luaL_buffinitsize(L, &b, n);
  for (i=1; i<=n; i++) {
    lua_Unsigned c = (lua_Unsigned)luaL_checkinteger(L, i);
    luaL_argcheck(L, c <= (lua_Unsigned)UCHAR_MAX, i, "value out of range");
    p[i - 1] = uchar(c);
  }
  luaL_pushresultsize(&b, n);
  return 1;
}

static int str_dump (lua_State *L) {
  luaL_Buffer b;
  int strip = lua_toboolean(L, 2);
  luaL_checktype(L, 1, LUA_TFUNCTION);
  lua_settop(L, 1);
  luaL_buffinit(L, &b);
  if (lua_dump(L, writer, &b, strip) != 0)
    return luaL_error(L, "unable to dump given function");
  luaL_pushresult(&b);
  return 1;
}

static int writer (lua_State *L, const void *b, size_t size, void *ud) {
  (void)L;
  luaL_addlstring((luaL_Buffer *)ud, (const char *)b, size);
  return 0;
}

/* pattern matching */
#define CAP_UNFINISHED	(-1)
#define CAP_POSITION	(-2)
#define MAXCAPTURES	32
#define MAXCCALLS	200

#define L_ESC		'%'
#define SPECIALS	"^$*+?.([%-"

typedef struct MatchState {
  const char *src_init;
  const char *src_end;
  const char *p_end;
  lua_State *L;
  int level;
  int matchdepth;
  struct {
    const char *init;
    ptrdiff_t len;
  } capture[MAXCAPTURES];
} MatchState;

static const char *match (MatchState *ms, const char *s, const char *p);

static int matchclass (int c, int cl) {
  int res;
  switch (tolower(cl)) {
    case 'a': res = isalpha(c); break;
    case 'c': res = iscntrl(c); break;
    case 'd': res = isdigit(c); break;
    case 'g': res = isgraph(c); break;
    case 'l': res = islower(c); break;
    case 'p': res = ispunct(c); break;
    case 's': res = isspace(c); break;
    case 'u': res = isupper(c); break;
    case 'w': res = isalnum(c); break;
    case 'x': res = isxdigit(c); break;
    default: return (cl == c);
  }
  if (isupper(cl)) res = !res;
  return res;
}

static int singlematch (MatchState *ms, const char *s, const char *p,
                        const char *ep) {
  if (s >= ms->src_end)
    return 0;
  int c = uchar(*s);
  switch (*p) {
    case '.': return 1;
    case L_ESC: return matchclass(c, uchar(*(p+1)));
    case '[': {
      const char *endp = ep - 1;
      int negate = (*(p+1) == '^') ? 1 : 0;
      const char *pp = p + (negate ? 2 : 1);
      while (pp < endp) {
        if (*(pp+1) == '-' && pp+2 < endp) {
          if (uchar(*pp) <= c && c <= uchar(*(pp+2)))
            return !negate;
          pp += 3;
        }
        else {
          if (uchar(*pp) == c) return !negate;
          pp++;
        }
      }
      return negate;
    }
    default: return (uchar(*p) == c);
  }
}

static const char *matchbalance (MatchState *ms, const char *s, const char *p) {
  if (p >= ms->p_end - 1)
    luaL_error(ms->L, "malformed pattern (missing arguments to '%%b')");
  if (*s != *p) return NULL;
  else {
    int b = *p, e = *(p+1);
    int cont = 1;
    while (++s < ms->src_end) {
      if (*s == e) {
        if (--cont == 0) return s+1;
      }
      else if (*s == b) cont++;
    }
  }
  return NULL;
}

static const char *max_expand (MatchState *ms, const char *s,
                               const char *p, const char *ep) {
  int i = 0;
  while (singlematch(ms, s+i, p, ep))
    i++;
  while (i>=0) {
    const char *res = match(ms, s+i, ep);
    if (res) return res;
    i--;
  }
  return NULL;
}

static const char *min_expand (MatchState *ms, const char *s,
                               const char *p, const char *ep) {
  for (;;) {
    const char *res = match(ms, s, ep);
    if (res != NULL) return res;
    else if (singlematch(ms, s, p, ep))
      s++;
    else return NULL;
  }
}

static const char *start_capture (MatchState *ms, const char *s,
                                   const char *p, int what) {
  int level = ms->level;
  if (level >= MAXCAPTURES) luaL_error(ms->L, "too many captures");
  ms->capture[level].init = s;
  ms->capture[level].len = what;
  ms->level = level+1;
  const char *res = match(ms, s, p);
  if (res == NULL)
    ms->level--;
  return res;
}

static const char *end_capture (MatchState *ms, const char *s, const char *p) {
  int l = capture_to_close(ms);
  const char *res;
  ms->capture[l].len = s - ms->capture[l].init;
  if ((res = match(ms, s, p)) == NULL)
    ms->capture[l].len = CAP_UNFINISHED;
  return res;
}

static int capture_to_close (MatchState *ms) {
  int level = ms->level;
  for (level--; level>=0; level--)
    if (ms->capture[level].len == CAP_UNFINISHED) return level;
  return luaL_error(ms->L, "invalid pattern capture");
}

static const char *match_capture (MatchState *ms, const char *s, int l) {
  l -= '1';
  if (l < 0 || l >= ms->level || ms->capture[l].len == CAP_UNFINISHED)
    return luaL_error(ms->L, "invalid back capture"), NULL;
  size_t len = ms->capture[l].len;
  if ((size_t)(ms->src_end-s) >= len &&
      memcmp(ms->capture[l].init, s, len) == 0)
    return s+len;
  else return NULL;
}

static const char *classend (MatchState *ms, const char *p) {
  switch (*p++) {
    case 0:
      luaL_error(ms->L, "malformed pattern (ends with '%')", *p);
      return p;
    case L_ESC:
      if (*p == '\0')
        luaL_error(ms->L, "malformed pattern (ends with '%%')");
      return p+1;
    case '[':
      if (*p == '^') p++;
      do {
        if (*p == '\0')
          luaL_error(ms->L, "malformed pattern (missing ']')");
        if (*(p++) == L_ESC && *p != '\0')
          p++;
      } while (*p != ']');
      return p+1;
    default:
      return p;
  }
}

static const char *match (MatchState *ms, const char *s, const char *p) {
  if (ms->matchdepth-- == 0)
    luaL_error(ms->L, "pattern too complex");
  init:
  if (p >= ms->p_end) goto ret;
  switch (*p) {
    case '(': {
      if (*(p+1) == ')')
        s = start_capture(ms, s, p+2, CAP_POSITION);
      else
        s = start_capture(ms, s, p+1, CAP_UNFINISHED);
      break;
    }
    case ')': {
      s = end_capture(ms, s, p+1);
      break;
    }
    case '$': {
      if ((p+1) >= ms->p_end)
        s = (s == ms->src_end) ? s : NULL;
      else goto dflt;
      break;
    }
    case L_ESC: {
      switch (*(p+1)) {
        case 'b': {
          s = matchbalance(ms, s, p+2);
          if (s != NULL) { p += 4; goto init; }
          break;
        }
        case 'f': {
          const char *ep;
          char previous;
          p += 2;
          if (*p != '[') luaL_error(ms->L, "missing '[' after '%%f' in pattern");
          ep = classend(ms, p);
          previous = (s == ms->src_init) ? '\0' : *(s-1);
          if (!singlematch(ms, &previous, p, ep) && singlematch(ms, s, p, ep)) {
            p = ep; goto init;
          }
          s = NULL;
          break;
        }
        default: {
          if (isdigit(uchar(*(p+1)))) {
            s = match_capture(ms, s, *(p+1));
            if (s != NULL) { p += 2; goto init; }
            break;
          }
          goto dflt;
        }
      }
      break;
    }
    default: dflt: {
      const char *ep = classend(ms, p);
      int m = singlematch(ms, s, p, ep);
      switch (*ep) {
        case '?': {
          const char *res;
          if (m && ((res=match(ms, s+1, ep+1)) != NULL))
            s = res;
          else {
            p = ep+1; goto init;
          }
          break;
        }
        case '+': {
          if (m) s = max_expand(ms, s+1, p, ep);
          else s = NULL;
          break;
        }
        case '*': {
          s = max_expand(ms, s, p, ep);
          break;
        }
        case '-': {
          s = min_expand(ms, s, p, ep);
          break;
        }
        default: {
          if (!m) s = NULL;
          else { s++; p = ep; goto init; }
        }
      }
    }
  }
  ret:
  ms->matchdepth++;
  return s;
}

static const char *lmemfind (const char *s1, size_t l1,
                              const char *s2, size_t l2) {
  if (l2 == 0) return s1;
  else if (l2 > l1) return NULL;
  else {
    const char *init;
    l2--;
    l1 = l1-l2;
    while (l1 > 0 && (init = (const char *)memchr(s1, *s2, l1)) != NULL) {
      init++;
      if (memcmp(init, s2+1, l2) == 0)
        return init-1;
      else {
        l1 -= init-s1;
        s1 = init;
      }
    }
    return NULL;
  }
}

static void push_onecapture (MatchState *ms, int i, const char *s,
                             const char *e) {
  if (i >= ms->level) {
    if (i == 0) lua_pushlstring(ms->L, s, e - s);
    else luaL_error(ms->L, "invalid capture index %%%d", i + 1);
  }
  else {
    ptrdiff_t l = ms->capture[i].len;
    if (l == CAP_UNFINISHED) luaL_error(ms->L, "unfinished capture");
    if (l == CAP_POSITION)
      lua_pushinteger(ms->L, (ms->capture[i].init - ms->src_init) + 1);
    else
      lua_pushlstring(ms->L, ms->capture[i].init, l);
  }
}

static int push_captures (MatchState *ms, const char *s, const char *e) {
  int i;
  int nlevels = (ms->level == 0 && s) ? 1 : ms->level;
  luaL_checkstack(ms->L, nlevels, "too many captures");
  for (i = 0; i < nlevels; i++)
    push_onecapture(ms, i, s, e);
  return nlevels;
}

static int nospecials (const char *p, size_t l) {
  size_t upto = 0;
  do {
    if (strpbrk(p + upto, SPECIALS))
      return 0;
    upto += strlen(p + upto) + 1;
  } while (upto <= l);
  return 1;
}

static void prepstate (MatchState *ms, lua_State *L,
                       const char *s, size_t ls, const char *p, size_t lp) {
  ms->L = L;
  ms->matchdepth = MAXCCALLS;
  ms->src_init = s;
  ms->src_end = s + ls;
  ms->p_end = p + lp;
}

static void reprepstate (MatchState *ms) {
  ms->level = 0;
  ms->matchdepth = MAXCCALLS;
}

static int str_find_aux (lua_State *L, int find) {
  size_t ls, lp;
  const char *s = luaL_checklstring(L, 1, &ls);
  const char *p = luaL_checklstring(L, 2, &lp);
  lua_Integer init = posrelat(luaL_optinteger(L, 3, 1), ls);
  if (init < 1) init = 1;
  else if (init > (lua_Integer)ls + 1) {
    luaL_pushfail(L);
    return 1;
  }
  if (find && (lua_toboolean(L, 4) || nospecials(p, lp))) {
    const char *s2 = lmemfind(s + init - 1, ls - (size_t)init + 1, p, lp);
    if (s2) {
      lua_pushinteger(L, (s2 - s) + 1);
      lua_pushinteger(L, (s2 - s) + lp);
      return 2;
    }
  }
  else {
    MatchState ms;
    const char *s1 = s + init - 1;
    int anchor = (*p == '^');
    if (anchor) { p++; lp--; }
    prepstate(&ms, L, s, ls, p, lp);
    do {
      const char *res;
      reprepstate(&ms);
      if ((res=match(&ms, s1, p)) != NULL) {
        if (find) {
          lua_pushinteger(L, (s1 - s) + 1);
          lua_pushinteger(L, res - s);
          return push_captures(&ms, NULL, 0) + 2;
        }
        else
          return push_captures(&ms, s1, res);
      }
    } while (s1++ < ms.src_end && !anchor);
  }
  luaL_pushfail(L);
  return 1;
}

static int str_find (lua_State *L) {
  return str_find_aux(L, 1);
}

static int str_match (lua_State *L) {
  return str_find_aux(L, 0);
}

typedef struct GMatchState {
  const char *src;
  const char *p;
  const char *lastmatch;
  MatchState ms;
} GMatchState;

static int gmatch_aux (lua_State *L) {
  GMatchState *gms = (GMatchState *)lua_touserdata(L, lua_upvalueindex(3));
  const char *src = gms->src;
  gms->ms.L = L;
  for (; src <= gms->ms.src_end; src++) {
    const char *e;
    reprepstate(&gms->ms);
    if ((e = match(&gms->ms, src, gms->p)) != NULL &&
        e != gms->lastmatch) {
      gms->src = e;
      gms->lastmatch = e;
      return push_captures(&gms->ms, src, e);
    }
  }
  return 0;
}

static int str_gmatch (lua_State *L) {
  size_t ls, lp;
  const char *s = luaL_checklstring(L, 1, &ls);
  const char *p = luaL_checklstring(L, 2, &lp);
  size_t init = 0;
  GMatchState *gms;
  lua_settop(L, 2);
  gms = (GMatchState *)lua_newuserdatauv(L, sizeof(GMatchState), 0);
  prepstate(&gms->ms, L, s, ls, p, lp);
  gms->src = s + init; gms->p = p; gms->lastmatch = NULL;
  lua_pushcclosure(L, gmatch_aux, 3);
  return 1;
}

static void add_s (MatchState *ms, luaL_Buffer *b, const char *s,
                   const char *e) {
  size_t l;
  lua_State *L = ms->L;
  const char *news = lua_tolstring(L, 3, &l);
  const char *p;
  for (p = news; p < news + l; p++) {
    if (*p != L_ESC)
      luaL_addchar(b, *p);
    else {
      p++;
      if (!isdigit(uchar(*p))) {
        if (*p != L_ESC)
          luaL_error(L, "invalid use of '%c' in replacement string", L_ESC);
        luaL_addchar(b, *p);
      }
      else if (*p == '0')
        luaL_addlstring(b, s, e - s);
      else {
        push_onecapture(ms, *p - '1', s, e);
        luaL_tolstring(L, -1, &l);
        lua_remove(L, -2);
        luaL_addlstring(b, lua_tostring(L, -1), l);
        lua_pop(L, 1);
      }
    }
  }
}

static void add_value (MatchState *ms, luaL_Buffer *b, const char *s,
                       const char *e, int tr) {
  lua_State *L = ms->L;
  switch (tr) {
    case LUA_TFUNCTION: {
      int n;
      lua_pushvalue(L, 3);
      n = push_captures(ms, s, e);
      lua_call(L, n, 1);
      break;
    }
    case LUA_TTABLE: {
      push_onecapture(ms, 0, s, e);
      lua_gettable(L, 3);
      break;
    }
    default: {
      add_s(ms, b, s, e);
      return;
    }
  }
  if (!lua_toboolean(L, -1)) {
    lua_pop(L, 1);
    luaL_addlstring(b, s, e - s);
  }
  else {
    if (!lua_isstring(L, -1))
      luaL_error(L, "invalid replacement value (a %s)",
                    luaL_typename(L, -1));
    luaL_addvalue(b);
  }
}

static int str_gsub (lua_State *L) {
  size_t srcl, lp;
  const char *src = luaL_checklstring(L, 1, &srcl);
  const char *p = luaL_checklstring(L, 2, &lp);
  const char *e;
  int tr = lua_type(L, 3);
  lua_Integer max_s = luaL_optinteger(L, 4, (lua_Integer)srcl + 1);
  int anchor = (*p == '^');
  lua_Integer n = 0;
  int changed = 0;
  MatchState ms;
  luaL_Buffer b;
  luaL_argexpected(L, tr == LUA_TNUMBER || tr == LUA_TSTRING ||
                 tr == LUA_TFUNCTION || tr == LUA_TTABLE, 3,
                   "string/function/table");
  luaL_buffinit(L, &b);
  if (anchor) { p++; lp--; }
  prepstate(&ms, L, src, srcl, p, lp);
  while (n < max_s) {
    const char *s1;
    reprepstate(&ms);
    e = match(&ms, src, p);
    if (e && e>src) {
      n++;
      add_value(&ms, &b, src, e, tr);
      src = e;
      changed = 1;
    }
    else if (src < ms.src_end) {
      luaL_addchar(&b, *src++);
    }
    else break;
    if (anchor) break;
  }
  luaL_addlstring(&b, src, ms.src_end - src);
  luaL_pushresult(&b);
  lua_pushinteger(L, n);
  return 2;
}

/* string.format */
#define MAX_ITEM	120

static int str_format (lua_State *L) {
  int top = lua_gettop(L);
  int arg = 1;
  size_t sfl;
  const char *strfrmt = luaL_checklstring(L, arg, &sfl);
  const char *strfrmt_end = strfrmt + sfl;
  luaL_Buffer b;
  luaL_buffinit(L, &b);
  while (strfrmt < strfrmt_end) {
    if (*strfrmt != '%')
      luaL_addchar(&b, *strfrmt++);
    else if (*++strfrmt == '%')
      luaL_addchar(&b, *strfrmt++);
    else {
      char form[MAX_ITEM];
      int maxitem = MAX_ITEM;
      char *buff = luaL_prepbuffsize(&b, maxitem);
      int nb = 0;
      arg++;
      if (arg > top)
        luaL_argerror(L, arg, "no value");
      strfrmt = scanformat(L, strfrmt, form);
      switch (*strfrmt++) {
        case 'c': {
          nb = l_sprintf(buff, maxitem, form, (int)luaL_checkinteger(L, arg));
          break;
        }
        case 'd': case 'i': {
          lua_Integer n = luaL_checkinteger(L, arg);
          addlenmod(form, LUA_INTEGER_FRMLEN);
          nb = l_sprintf(buff, maxitem, form, (LUAI_UACINT)n);
          break;
        }
        case 'u': {
