      if (*(p+1) == ')')
        s = start_capture(ms, s, p+2, CAP_POSITION);
      else
        s = start_capture(ms, s, p+1, CAP_UNFINISHED);
      break;
    }
    case ')': {
      s = end_capture(ms, s, p+1);
      break;
    }
    case '$': {
      if ((p+1) >= ms->p_end)
        s = (s == ms->src_end) ? s : NULL;
      else goto dflt;
      break;
    }
    case L_ESC: {
      switch (*(p+1)) {
        case 'b': {
          s = matchbalance(ms, s, p+2);
          if (s != NULL) { p += 4; goto init; }
          break;
        }
        case 'f': {
          const char *ep;
          char previous;
          p += 2;
          if (*p != '[') luaL_error(ms->L, "missing '[' after '%%f' in pattern");
          ep = classend(ms, p);
          previous = (s == ms->src_init) ? '\0' : *(s-1);
          if (!singlematch(ms, &previous, p, ep) && singlematch(ms, s, p, ep)) {
            p = ep; goto init;
          }
          s = NULL;
          break;
        }
        default: {
          if (isdigit(uchar(*(p+1)))) {
            s = match_capture(ms, s, *(p+1));
            if (s != NULL) { p += 2; goto init; }
            break;
          }
          goto dflt;
        }
      }
      break;
    }
    default: dflt: {
      const char *ep = classend(ms, p);
      int m = singlematch(ms, s, p, ep);
      switch (*ep) {
        case '?': {
          const char *res;
          if (m && ((res=match(ms, s+1, ep+1)) != NULL))
            s = res;
          else {
            p = ep+1; goto init;
          }
          break;
        }
        case '+': {
          if (m) s = max_expand(ms, s+1, p, ep);
          else s = NULL;
          break;
        }
        case '*': {
          s = max_expand(ms, s, p, ep);
          break;
        }
        case '-': {
          s = min_expand(ms, s, p, ep);
          break;
        }
        default: {
          if (!m) s = NULL;
          else { s++; p = ep; goto init; }
        }
      }
    }
  }
  ret:
  ms->matchdepth++;
  return s;
}

static const char *lmemfind (const char *s1, size_t l1,
                              const char *s2, size_t l2) {
  if (l2 == 0) return s1;
  else if (l2 > l1) return NULL;
  else {
    const char *init;
    l2--;
    l1 = l1-l2;
    while (l1 > 0 && (init = (const char *)memchr(s1, *s2, l1)) != NULL) {
      init++;
      if (memcmp(init, s2+1, l2) == 0)
        return init-1;
      else {
        l1 -= init-s1;
        s1 = init;
      }
    }
    return NULL;
  }
}

static void push_onecapture (MatchState *ms, int i, const char *s,
                             const char *e) {
  if (i >= ms->level) {
    if (i == 0) lua_pushlstring(ms->L, s, e - s);
    else luaL_error(ms->L, "invalid capture index %%%d", i + 1);
  }
  else {
    ptrdiff_t l = ms->capture[i].len;
    if (l == CAP_UNFINISHED) luaL_error(ms->L, "unfinished capture");
    if (l == CAP_POSITION)
      lua_pushinteger(ms->L, (ms->capture[i].init - ms->src_init) + 1);
    else
      lua_pushlstring(ms->L, ms->capture[i].init, l);
  }
}

static int push_captures (MatchState *ms, const char *s, const char *e) {
  int i;
  int nlevels = (ms->level == 0 && s) ? 1 : ms->level;
  luaL_checkstack(ms->L, nlevels, "too many captures");
  for (i = 0; i < nlevels; i++)
    push_onecapture(ms, i, s, e);
  return nlevels;
}

static int nospecials (const char *p, size_t l) {
  size_t upto = 0;
  do {
    if (strpbrk(p + upto, SPECIALS))
      return 0;
    upto += strlen(p + upto) + 1;
  } while (upto <= l);
  return 1;
}

static void prepstate (MatchState *ms, lua_State *L,
                       const char *s, size_t ls, const char *p, size_t lp) {
  ms->L = L;
  ms->matchdepth = MAXCCALLS;
  ms->src_init = s;
  ms->src_end = s + ls;
  ms->p_end = p + lp;
}

static void reprepstate (MatchState *ms) {
  ms->level = 0;
  ms->matchdepth = MAXCCALLS;
}

static int str_find_aux (lua_State *L, int find) {
  size_t ls, lp;
  const char *s = luaL_checklstring(L, 1, &ls);
  const char *p = luaL_checklstring(L, 2, &lp);
  lua_Integer init = posrelat(luaL_optinteger(L, 3, 1), ls);
  if (init < 1) init = 1;
  else if (init > (lua_Integer)ls + 1) {
    luaL_pushfail(L);
    return 1;
  }
  if (find && (lua_toboolean(L, 4) || nospecials(p, lp))) {
    const char *s2 = lmemfind(s + init - 1, ls - (size_t)init + 1, p, lp);
    if (s2) {
      lua_pushinteger(L, (s2 - s) + 1);
      lua_pushinteger(L, (s2 - s) + lp);
      return 2;
    }
  }
  else {
    MatchState ms;
    const char *s1 = s + init - 1;
    int anchor = (*p == '^');
    if (anchor) { p++; lp--; }
    prepstate(&ms, L, s, ls, p, lp);
    do {
      const char *res;
      reprepstate(&ms);
      if ((res=match(&ms, s1, p)) != NULL) {
        if (find) {
          lua_pushinteger(L, (s1 - s) + 1);
          lua_pushinteger(L, res - s);
          return push_captures(&ms, NULL, 0) + 2;
        }
        else
          return push_captures(&ms, s1, res);
      }
    } while (s1++ < ms.src_end && !anchor);
  }
  luaL_pushfail(L);
  return 1;
}

static int str_find (lua_State *L) {
  return str_find_aux(L, 1);
}

static int str_match (lua_State *L) {
  return str_find_aux(L, 0);
}

typedef struct GMatchState {
  const char *src;
  const char *p;
  const char *lastmatch;
  MatchState ms;
} GMatchState;

static int gmatch_aux (lua_State *L) {
  GMatchState *gms = (GMatchState *)lua_touserdata(L, lua_upvalueindex(3));
  const char *src = gms->src;
  gms->ms.L = L;
  for (; src <= gms->ms.src_end; src++) {
    const char *e;
    reprepstate(&gms->ms);
    if ((e = match(&gms->ms, src, gms->p)) != NULL &&
        e != gms->lastmatch) {
      gms->src = e;
      gms->lastmatch = e;
      return push_captures(&gms->ms, src, e);
    }
  }
  return 0;
}

static int str_gmatch (lua_State *L) {
  size_t ls, lp;
  const char *s = luaL_checklstring(L, 1, &ls);
  const char *p = luaL_checklstring(L, 2, &lp);
  size_t init = 0;
  GMatchState *gms;
  lua_settop(L, 2);
  gms = (GMatchState *)lua_newuserdatauv(L, sizeof(GMatchState), 0);
  prepstate(&gms->ms, L, s, ls, p, lp);
  gms->src = s + init; gms->p = p; gms->lastmatch = NULL;
  lua_pushcclosure(L, gmatch_aux, 3);
  return 1;
}

static void add_s (MatchState *ms, luaL_Buffer *b, const char *s,
                   const char *e) {
  size_t l;
  lua_State *L = ms->L;
  const char *news = lua_tolstring(L, 3, &l);
  const char *p;
  for (p = news; p < news + l; p++) {
    if (*p != L_ESC)
      luaL_addchar(b, *p);
    else {
      p++;
      if (!isdigit(uchar(*p))) {
        if (*p != L_ESC)
          luaL_error(L, "invalid use of '%c' in replacement string", L_ESC);
        luaL_addchar(b, *p);
      }
      else if (*p == '0')
        luaL_addlstring(b, s, e - s);
      else {
        push_onecapture(ms, *p - '1', s, e);
        luaL_tolstring(L, -1, &l);
        lua_remove(L, -2);
        luaL_addlstring(b, lua_tostring(L, -1), l);
        lua_pop(L, 1);
      }
    }
  }
}

static void add_value (MatchState *ms, luaL_Buffer *b, const char *s,
                       const char *e, int tr) {
  lua_State *L = ms->L;
  switch (tr) {
    case LUA_TFUNCTION: {
      int n;
      lua_pushvalue(L, 3);
      n = push_captures(ms, s, e);
      lua_call(L, n, 1);
      break;
    }
    case LUA_TTABLE: {
      push_onecapture(ms, 0, s, e);
      lua_gettable(L, 3);
      break;
    }
    default: {
      add_s(ms, b, s, e);
      return;
    }
  }
  if (!lua_toboolean(L, -1)) {
    lua_pop(L, 1);
    luaL_addlstring(b, s, e - s);
  }
  else {
    if (!lua_isstring(L, -1))
      luaL_error(L, "invalid replacement value (a %s)",
                    luaL_typename(L, -1));
    luaL_addvalue(b);
  }
}

static int str_gsub (lua_State *L) {
  size_t srcl, lp;
  const char *src = luaL_checklstring(L, 1, &srcl);
  const char *p = luaL_checklstring(L, 2, &lp);
  const char *e;
  int tr = lua_type(L, 3);
  lua_Integer max_s = luaL_optinteger(L, 4, (lua_Integer)srcl + 1);
  int anchor = (*p == '^');
  lua_Integer n = 0;
  int changed = 0;
  MatchState ms;
  luaL_Buffer b;
  luaL_argexpected(L, tr == LUA_TNUMBER || tr == LUA_TSTRING ||
                 tr == LUA_TFUNCTION || tr == LUA_TTABLE, 3,
                   "string/function/table");
  luaL_buffinit(L, &b);
  if (anchor) { p++; lp--; }
  prepstate(&ms, L, src, srcl, p, lp);
  while (n < max_s) {
    const char *s1;
    reprepstate(&ms);
    e = match(&ms, src, p);
    if (e && e>src) {
      n++;
      add_value(&ms, &b, src, e, tr);
      src = e;
      changed = 1;
    }
    else if (src < ms.src_end) {
      luaL_addchar(&b, *src++);
    }
    else break;
    if (anchor) break;
  }
  luaL_addlstring(&b, src, ms.src_end - src);
  luaL_pushresult(&b);
  lua_pushinteger(L, n);
  return 2;
}

/* string.format */
#define MAX_ITEM	120

static int str_format (lua_State *L) {
  int top = lua_gettop(L);
  int arg = 1;
  size_t sfl;
  const char *strfrmt = luaL_checklstring(L, arg, &sfl);
  const char *strfrmt_end = strfrmt + sfl;
  luaL_Buffer b;
  luaL_buffinit(L, &b);
  while (strfrmt < strfrmt_end) {
    if (*strfrmt != '%')
      luaL_addchar(&b, *strfrmt++);
    else if (*++strfrmt == '%')
      luaL_addchar(&b, *strfrmt++);
    else {
      char form[MAX_ITEM];
      int maxitem = MAX_ITEM;
      char *buff = luaL_prepbuffsize(&b, maxitem);
      int nb = 0;
      arg++;
      if (arg > top)
        luaL_argerror(L, arg, "no value");
      strfrmt = scanformat(L, strfrmt, form);
      switch (*strfrmt++) {
        case 'c': {
          nb = l_sprintf(buff, maxitem, form, (int)luaL_checkinteger(L, arg));
          break;
        }
        case 'd': case 'i': {
          lua_Integer n = luaL_checkinteger(L, arg);
          addlenmod(form, LUA_INTEGER_FRMLEN);
          nb = l_sprintf(buff, maxitem, form, (LUAI_UACINT)n);
          break;
        }
        case 'u': {
          lua_Unsigned n = (lua_Unsigned)luaL_checkinteger(L, arg);
          addlenmod(form, LUA_INTEGER_FRMLEN);
          nb = l_sprintf(buff, maxitem, form, (lua_Unsigned)n);
          break;
        }
        case 'o': {
          lua_Unsigned n = (lua_Unsigned)luaL_checkinteger(L, arg);
          addlenmod(form, LUA_INTEGER_FRMLEN);
          nb = l_sprintf(buff, maxitem, form, n);
          break;
        }
        case 'x': {
          lua_Unsigned n = (lua_Unsigned)luaL_checkinteger(L, arg);
          addlenmod(form, LUA_INTEGER_FRMLEN);
          nb = l_sprintf(buff, maxitem, form, n);
          break;
        }
        case 'X': {
          lua_Unsigned n = (lua_Unsigned)luaL_checkinteger(L, arg);
          addlenmod(form, LUA_INTEGER_FRMLEN);
          nb = l_sprintf(buff, maxitem, form, n);
          break;
        }
        case 'e': case 'E': case 'f':
        case 'g': case 'G': {
          lua_Number n = luaL_checknumber(L, arg);
          nb = lua_number2strx(buff, maxitem, form, n);
          break;
        }
        case 'p': {
          const void *p = lua_topointer(L, arg);
          nb = l_sprintf(buff, maxitem, form, p);
          break;
        }
        case 'q': {
          addquoted(L, &b, arg);
          break;
        }
        case 's': {
          size_t l;
          const char *s = luaL_tolstring(L, arg, &l);
          if (form[2] == '\0')
            luaL_addstring(&b, s);
          else {
            luaL_argcheck(L, l == strlen(s), arg, "string contains zeros");
            nb = l_sprintf(buff, maxitem, form, s);
            lua_pop(L, 1);
          }
          break;
        }
        default: {
          return luaL_error(L, "invalid option '%%%c' to 'format'",
                               strfrmt[-1]);
        }
      }
      luaL_addsize(&b, nb);
    }
  }
  luaL_pushresult(&b);
  return 1;
}

static const char *scanformat (lua_State *L, const char *strfrmt, char *form) {
  const char *p = strfrmt;
  while (*p != '\0' && strchr("-+ #0", *p) != NULL) p++;
  if ((size_t)(p - strfrmt) >= sizeof(char *))
    luaL_error(L, "invalid format string to 'format'");
  if (isdigit(uchar(*p))) p++;
  if (isdigit(uchar(*p))) p++;
  if (*p == '.') {
    p++;
    if (isdigit(uchar(*p))) p++;
    if (isdigit(uchar(*p))) p++;
  }
  if (isdigit(uchar(*p)))
    luaL_error(L, "invalid format string to 'format'");
  *(form++) = '%';
  memcpy(form, strfrmt, ((p - strfrmt) + 1) * sizeof(char));
  form += (p - strfrmt) + 1;
  *form = '\0';
  return p;
}

static void addlenmod (char *form, const char *lenmod) {
  size_t l = strlen(form);
  size_t lm = strlen(lenmod);
  char spec = form[l - 1];
  strcpy(form + l - 1, lenmod);
  form[l + lm - 1] = spec;
  form[l + lm] = '\0';
}

static void addquoted (lua_State *L, luaL_Buffer *b, int arg) {
  size_t l;
  const char *s = luaL_checklstring(L, arg, &l);
  luaL_addchar(b, '"');
  while (l--) {
    if (*s == '"' || *s == '\\' || *s == '\n') {
      luaL_addchar(b, '\\');
      luaL_addchar(b, *s);
    }
    else if (iscntrl(uchar(*s))) {
      char buff[10];
      if (!isdigit(uchar(*(s+1))))
        l_sprintf(buff, sizeof(buff), "\\%d", (int)uchar(*s));
      else
        l_sprintf(buff, sizeof(buff), "\\%03d", (int)uchar(*s));
      luaL_addstring(b, buff);
    }
    else
      luaL_addchar(b, *s);
    s++;
  }
  luaL_addchar(b, '"');
}

static int lua_number2strx (char *buff, int sz, const char *fmt, lua_Number x) {
  int nb = l_sprintf(buff, sz, fmt, (double)x);
  if (buff[strspn(buff, "-0123456789")] == '\0') {
    buff[nb++] = '.';
    buff[nb++] = '0';
    buff[nb] = '\0';
  }
  return nb;
}

