static const char *skipmode (const char *mode) {
  const char *m = mode;
  switch (*m++) {
    case 'r': case 'w': case 'a': break;
    default: return mode;
  }
  if (*m == 'b') m++;
  if (*m == '+') m++;
  if (*m == 'b') m++;
  return m;
}

