#define IOPREF_LEN  2
#define IO_INPUT	"_IO_input"
#define IO_OUTPUT	"_IO_output"

static int g_iofile (lua_State *L, const char *f, const char *mode) {
  if (!lua_isnoneornil(L, 1)) {
