/* reading lines */
#define MAXRLINE 512

static int read_line (lua_State *L, FILE *f, int chop) {
  luaL_Buffer b;
  int c;
  luaL_buffinit(L, &b);
  while ((c = getc(f)) != EOF) {
    luaL_addchar(&b, c);
    if (c == '\n') {
      if (chop) luaL_buffsub(&b, 1);
      break;
    }
