  int n = (int)lua_tointeger(L, lua_upvalueindex(2));
  if (p->f == NULL) {
    luaL_pushfail(L);
    return 1;
  }
  for (i = 1; i <= n; i++)
    lua_pushvalue(L, lua_upvalueindex(3 + i));
