/*
** $Id: lutf8lib.c $
** Standard library for UTF-8 manipulation
** See Copyright Notice in lua.h
*/

#define lutf8lib_c
#define LUA_LIB

#include "lprefix.h"
#include <assert.h>
#include <limits.h>
#include <stdlib.h>
#include <string.h>

#include "lua.h"
#include "lauxlib.h"
#include "lualib.h"

#define MAXUNICODE	0x7FFFFFFFu
#define MAXUTF		6  /* maximum length of one UTF-8 sequence */

#define MSGInvalidChar "invalid UTF-8 code"
#define CONT(b)  (((b) & 0xC0) == 0x80)  /* is continuation byte? */

static const char *utf8_decode (const char *s, lua_Unsigned *val, int strict) {
  static const lua_Unsigned limits[] = {~(lua_Unsigned)0, 0x80, 0x800, 0x10000u,
                                         0x200000u, 0x4000000u};
  unsigned int c = (unsigned char)*s;
  lua_Unsigned res = 0;
  if (c < 0x80) {
    res = c;
    s++;
  }
  else {
    int count = 0;
    for (; c & 0x40; c <<= 1) {
      int cc = (unsigned char)*(++s);
      if ((cc & 0xC0) != 0x80)
        return NULL;
      res = (res << 6) | (cc & 0x3F);
      count++;
    }
    res |= ((lua_Unsigned)(c & 0x7F) << (count * 6));
    if (strict && (count >= 4 || res > MAXUNICODE || res < limits[count] ||
        (0xD800u <= res && res <= 0xDFFFu)))
      return NULL;
  }
  if (val) *val = res;
  return s + 1;
}

static lua_Unsigned utf8_decode_safe (const char *s, int strict) {
  lua_Unsigned val = 0;
  if (!utf8_decode(s, &val, strict))
    return (lua_Unsigned)-1;
  return val;
}

static int utflen (lua_State *L) {
  lua_Integer n = 0;
  size_t len;
  const char *s = luaL_checklstring(L, 1, &len);
  lua_Integer posi = luaL_optinteger(L, 2, 1);
  lua_Integer posj = luaL_optinteger(L, 3, -1);
  int noerr = lua_toboolean(L, 4);
  const char *e;
  if (posi < 0) posi += len + 1;
  if (posj < 0) posj += len + 1;
  luaL_argcheck(L, 1 <= posi && (posi - 1) <= (lua_Integer)len, 2, "initial position out of bounds");
  luaL_argcheck(L, posj <= (lua_Integer)len, 3, "final position out of bounds");
  for (e = s + posi - 1; e < s + posj; n++) {
    if (CONT((unsigned char)*e)) {
      if (!noerr)
        return luaL_error(L, "invalid UTF-8 code");
      luaL_pushfail(L);
      lua_pushinteger(L, e - s + 1);
      return 2;
    }
    e += 1;
    while (e < s + posj && CONT((unsigned char)*e)) e++;
  }
  lua_pushinteger(L, n);
  return 1;
}

static int codepoint (lua_State *L) {
  size_t len;
  const char *s = luaL_checklstring(L, 1, &len);
  lua_Integer posi = luaL_optinteger(L, 2, 1);
  lua_Integer pose = luaL_optinteger(L, 3, posi);
  int lax = lua_toboolean(L, 4);
  int n;
  const char *se;
  if (posi < 0) posi += len + 1;
  if (pose < 0) pose += len + 1;
  if (posi < 1) return luaL_error(L, "bad argument #2 (initial position out of bounds)");
  if (pose > (lua_Integer)len) pose = (lua_Integer)len;
  if (posi > pose) return 0;
  se = s + pose;
  s += posi - 1;
  for (n = 0; s < se; n++) {
    lua_Unsigned code;
    const char *ns = utf8_decode(s, &code, !lax);
    if (ns == NULL)
      return luaL_error(L, MSGInvalidChar);
    luaL_checkstack(L, 1, "too many results");
    lua_pushinteger(L, (lua_Integer)code);
    s = ns;
  }
  return n;
}

static void pushutfchar (lua_State *L, int arg) {
  lua_Unsigned code = (lua_Unsigned)luaL_checkinteger(L, arg);
  luaL_argcheck(L, code <= MAXUNICODE, arg, "value out of range");
  lua_pushfstring(L, "%U", (long)code);
}

static int utfchar (lua_State *L) {
  int n = lua_gettop(L);
  if (n == 1)
    pushutfchar(L, 1);
  else {
    int i;
    luaL_Buffer b;
    luaL_buffinit(L, &b);
    for (i = 1; i <= n; i++) {
      pushutfchar(L, i);
      luaL_addvalue(&b);
    }
    luaL_pushresult(&b);
  }
  return 1;
