static int byteoffset (lua_State *L) {
  size_t len;
  const char *s = luaL_checklstring(L, 1, &len);
  lua_Integer n  = luaL_checkinteger(L, 2);
  lua_Integer posi = (n >= 0) ? 1 : len + 1;
  posi = luaL_optinteger(L, 3, posi);
  if (posi < 0) posi += len + 1;
  luaL_argcheck(L, 1 <= posi && posi <= (lua_Integer)len + 1, 3, "position out of bounds");
  if (n == 0) {
    while (posi > 1 && CONT((unsigned char)s[posi - 1])) posi--;
  }
  else {
    if (CONT((unsigned char)s[posi - 1]))
      return luaL_error(L, "initial position is a continuation byte");
    if (n < 0) {
       while (n < 0 && posi > 1) {
         do {
           posi--;
         } while (posi > 1 && CONT((unsigned char)s[posi - 1]));
         n++;
       }
    }
    else {
      n--;
      while (n > 0 && posi <= (lua_Integer)len) {
        do {
          posi++;
        } while (CONT((unsigned char)s[posi - 1]));
        n--;
      }
    }
  }
  if (n != 0)
    luaL_pushfail(L);
  else
    lua_pushinteger(L, posi);
  return 1;
}

static int iter_aux (lua_State *L, int strict) {
  size_t len;
  const char *s = luaL_checklstring(L, 1, &len);
  lua_Unsigned n = (lua_Unsigned)luaL_checkinteger(L, 2);
  if (n < len) {
    lua_Unsigned code;
    const char *next = utf8_decode(s + n, &code, strict);
    if (next == NULL)
      return luaL_error(L, "invalid UTF-8 code");
    lua_pushinteger(L, (lua_Integer)(next - s));
    lua_pushinteger(L, (lua_Integer)code);
    return 2;
  }
  return 0;
}

static int iter_auxstrict (lua_State *L) {
  return iter_aux(L, 1);
}

static int iter_auxlax (lua_State *L) {
  return iter_aux(L, 0);
}

static int codes (lua_State *L) {
  int lax = lua_toboolean(L, 2);
