      if (step > 0) {
        count = (limit < init) ? 0 : ((lua_Unsigned)limit - init)/step + 1;
      }
      else {
        count = (limit > init) ? 0 : ((lua_Unsigned)init - limit)/(-step) + 1;
      }
      setivalue(s2v(ra), (lua_Integer)count);
      setivalue(s2v(ra + 1), step);
      setivalue(s2v(ra + 3), init);
