    if (!tonumber(pinit, &init)) luaG_forerror(L, pinit, "initial value");
    if (!tonumber(plimit, &limit)) luaG_forerror(L, plimit, "limit");
    if (!tonumber(pstep, &step)) luaG_forerror(L, pstep, "step");
    if (step == 0) luaG_runerror(L, "'for' step is zero");
    setfltvalue(s2v(ra), limit);
    setfltvalue(s2v(ra + 1), step);
