      setsvalue2s(L, top-n, luaS_newlstr(L, buffer, tl));
    }
    total -= n-1;
    L->top -= n-1;
  } while (total > 1);
}

static int tostring (lua_State *L, TValue *v) {
  if (ttisstring(v)) return 1;
  else if (ttisnumber(v)) {
    luaO_tostring(L, v);
    return 1;
  }
  return 0;
}

lua_Integer luaV_shiftl (lua_Integer x, lua_Integer y) {
  if (y < 0) {
    if (y <= -(lua_Integer)(sizeof(lua_Integer)*CHAR_BIT))
      return 0;
    else
      return intop(>>, x, -y);
  }
  else {
    if (y >= (lua_Integer)(sizeof(lua_Integer)*CHAR_BIT))
      return 0;
    else
      return intop(<<, x, y);
  }
}

lua_Integer luaV_idiv (lua_State *L, lua_Integer m, lua_Integer n) {
  if (l_unlikely(l_castS2U(n) + 1u <= 1u)) {
    if (n == 0)
      luaG_runerror(L, "attempt to perform 'n//0'");
    else return intop(-, 0, m);
  }
  else {
    lua_Integer q = m / n;
    if ((m ^ n) < 0 && q * n != m)
      q -= 1;
    return q;
  }
}

lua_Integer luaV_mod (lua_State *L, lua_Integer m, lua_Integer n) {
  if (l_unlikely(l_castS2U(n) + 1u <= 1u)) {
    if (n == 0)
      luaG_runerror(L, "attempt to perform 'n%%0'");
    else return 0;
  }
  else {
    lua_Integer r = m % n;
    if (r != 0 && (r ^ n) < 0)
      r += n;
    return r;
  }
}

lua_Number luaV_modf (lua_State *L, lua_Number m, lua_Number n) {
  lua_Number r;
  luai_nummod(L, m, n, r);
  return r;
}

void luaV_finishget (lua_State *L, const TValue *t, TValue *key, StkId val,
                    const TValue *slot) {
  int loop;
  const TValue *tm;
  for (loop = 0; loop < MAXTAGLOOP; loop++) {
    if (slot == NULL) {
      lua_assert(!ttistable(t));
      tm = luaT_gettmbyobj(L, t, TM_INDEX);
      if (isempty(tm))
        luaG_typeerror(L, t, "index");
    }
    else {
      lua_assert(isempty(slot));
      tm = luaT_gettmbyobj(L, t, TM_INDEX);
      if (isempty(tm)) {
        setnilvalue(s2v(val));
        return;
      }
    }
    if (ttisfunction(tm)) {
      luaT_callTMres(L, tm, t, key, val);
      return;
    }
    t = tm;
    if (luaV_fastget(L, t, key, slot, luaH_get)) {
      setobj2s(L, val, slot);
      return;
    }
  }
  luaG_runerror(L, "'__index' chain too long; possible loop");
}

void luaV_finishset (lua_State *L, const TValue *t, TValue *key,
                    TValue *val, const TValue *slot) {
  int loop;
  for (loop = 0; loop < MAXTAGLOOP; loop++) {
    const TValue *tm;
    if (slot != NULL) {
      Table *h = hvalue(t);
      lua_assert(isempty(slot));
      tm = luaT_gettmbyobj(L, t, TM_NEWINDEX);
      if (isempty(tm)) {
        luaH_newkey(L, h, key, val);
        invalidateTMcache(h);
        luaC_barrierback(L, obj2gco(h), val);
        return;
      }
    }
    else {
      tm = luaT_gettmbyobj(L, t, TM_NEWINDEX);
      if (isempty(tm))
        luaG_typeerror(L, t, "index");
    }
    if (ttisfunction(tm)) {
      luaT_callTM(L, tm, t, key, val);
      return;
    }
    t = tm;
    if (luaV_fastget(L, t, key, slot, luaH_get)) {
      luaH_fastset(L, hvalue(t), slot, val);
      luaC_barrierback(L, obj2gco(hvalue(t)), val);
      return;
    }
    slot = NULL;
  }
  luaG_runerror(L, "'__newindex' chain too long; possible loop");
}

static int luaV_tostring (lua_State *L, TValue *v) {
  if (ttisstring(v)) return 1;
  else if (ttisnumber(v)) {
    luaO_tostring(L, v);
    return 1;
  }
  return 0;
}

/* the VM dispatch loop */
void luaV_execute (lua_State *L, CallInfo *ci) {
  LClosure *cl;
  TValue *k;
  StkId base;
  const Instruction *pc;

  startfunc:
  cl = clLvalue(s2v(ci->func));
  k = cl->p->k;
  base = ci->func + 1;
  pc = ci->u.l.savedpc;

  for (;;) {
    Instruction i = *pc++;
    OpCode op;
    StkId ra;

    if (ci->u.l.trap) {
      if (luaG_traceexec(L, pc - 1)) {
        pc = ci->u.l.savedpc;
        base = ci->func + 1;
        continue;
      }
      pc = ci->u.l.savedpc;
    }

    op = GET_OPCODE(i);
    ra = base + GETARG_A(i);

    switch (op) {
      case OP_MOVE: {
        setobjs2s(L, ra, base + GETARG_B(i));
        break;
      }
      case OP_LOADI: {
        lua_Integer b = GETARG_sBx(i);
        setivalue(s2v(ra), b);
        break;
      }
      case OP_LOADF: {
        int b = GETARG_sBx(i);
        setfltvalue(s2v(ra), cast_num(b));
        break;
      }
      case OP_LOADK: {
        TValue *rb = k + GETARG_Bx(i);
        setobj2s(L, ra, rb);
        break;
      }
      case OP_LOADKX: {
        TValue *rb;
        lua_assert(GET_OPCODE(*pc) == OP_EXTRAARG);
        rb = k + GETARG_Ax(*pc++);
        setobj2s(L, ra, rb);
        break;
      }
      case OP_LOADFALSE: {
        setbvalue(s2v(ra), 0);
        break;
      }
      case OP_LFALSESKIP: {
        setbvalue(s2v(ra), 0);
        pc++;
        break;
      }
      case OP_LOADTRUE: {
        setbvalue(s2v(ra), 1);
        break;
      }
      case OP_LOADNIL: {
        int b = GETARG_B(i);
        do {
          setnilvalue(s2v(ra++));
        } while (b--);
        break;
      }
      case OP_GETUPVAL: {
        int b = GETARG_B(i);
        setobj2s(L, ra, cl->upvals[b]->v.p);
        break;
      }
      case OP_SETUPVAL: {
        UpVal *uv = cl->upvals[GETARG_B(i)];
        setobj(L, uv->v.p, s2v(ra));
        luaC_barrier(L, uv, s2v(ra));
        break;
      }
      case OP_GETTABUP: {
        const TValue *slot;
        TValue *upval = cl->upvals[GETARG_B(i)]->v.p;
        TValue *rc = k + GETARG_C(i);
        TString *key = tsvalue(rc);
        if (luaV_fastget(L, upval, key, slot, luaH_getstr)) {
          setobj2s(L, ra, slot);
        }
        else {
          L->top = ra + 1;
          luaV_finishget(L, upval, rc, ra, slot);
          ci->u.l.savedpc = pc;
          base = ci->func + 1;
        }
        break;
      }
      case OP_GETTABLE: {
        const TValue *slot;
        TValue *rb = s2v(base + GETARG_B(i));
        TValue *rc = s2v(base + GETARG_C(i));
        if (luaV_fastget(L, rb, rc, slot, luaH_get)) {
          setobj2s(L, ra, slot);
        }
        else {
          L->top = ra + 1;
          luaV_finishget(L, rb, rc, ra, slot);
          ci->u.l.savedpc = pc;
          base = ci->func + 1;
        }
        break;
      }
      case OP_GETI: {
        const TValue *slot;
        TValue *rb = s2v(base + GETARG_B(i));
        int c = GETARG_C(i);
        if (luaV_fastgeti(L, rb, c, slot)) {
          setobj2s(L, ra, slot);
        }
        else {
          TValue key;
          setivalue(&key, c);
          L->top = ra + 1;
          luaV_finishget(L, rb, &key, ra, slot);
          ci->u.l.savedpc = pc;
          base = ci->func + 1;
        }
        break;
      }
      case OP_GETFIELD: {
        const TValue *slot;
        TValue *rb = s2v(base + GETARG_B(i));
        TValue *rc = k + GETARG_C(i);
        TString *key = tsvalue(rc);
        if (luaV_fastget(L, rb, key, slot, luaH_getstr)) {
          setobj2s(L, ra, slot);
        }
        else {
          L->top = ra + 1;
          luaV_finishget(L, rb, rc, ra, slot);
          ci->u.l.savedpc = pc;
          base = ci->func + 1;
        }
        break;
      }
      case OP_SETTABUP: {
        const TValue *slot;
        TValue *upval = cl->upvals[GETARG_A(i)]->v.p;
        TValue *rb = k + GETARG_B(i);
        TValue *rc = (GETARG_k(i)) ? k + GETARG_C(i) : s2v(base + GETARG_C(i));
        if (luaV_fastget(L, upval, rb, slot, luaH_getstr)) {
          luaH_fastset(L, hvalue(upval), slot, rc);
          luaC_barrierback(L, obj2gco(hvalue(upval)), rc);
        }
        else {
          L->top = base;
          luaV_finishset(L, upval, rb, rc, slot);
          ci->u.l.savedpc = pc;
          base = ci->func + 1;
        }
        break;
      }
      case OP_SETTABLE: {
        const TValue *slot;
        TValue *rb = s2v(base + GETARG_B(i));
        TValue *rc = (GETARG_k(i)) ? k + GETARG_C(i) : s2v(base + GETARG_C(i));
        if (luaV_fastget(L, s2v(ra), rb, slot, luaH_get)) {
          luaH_fastset(L, hvalue(s2v(ra)), slot, rc);
          luaC_barrierback(L, obj2gco(hvalue(s2v(ra))), rc);
        }
        else {
          L->top = base;
          luaV_finishset(L, s2v(ra), rb, rc, slot);
          ci->u.l.savedpc = pc;
          base = ci->func + 1;
        }
        break;
      }
      case OP_SETI: {
        const TValue *slot;
        int b = GETARG_B(i);
        TValue *rc = (GETARG_k(i)) ? k + GETARG_C(i) : s2v(base + GETARG_C(i));
        if (luaV_fastgeti(L, s2v(ra), b, slot)) {
          luaH_fastset(L, hvalue(s2v(ra)), slot, rc);
          luaC_barrierback(L, obj2gco(hvalue(s2v(ra))), rc);
        }
        else {
          TValue key;
          setivalue(&key, b);
          L->top = base;
          luaV_finishset(L, s2v(ra), &key, rc, slot);
          ci->u.l.savedpc = pc;
          base = ci->func + 1;
        }
        break;
      }
      case OP_SETFIELD: {
        const TValue *slot;
        TValue *rb = k + GETARG_B(i);
        TValue *rc = (GETARG_k(i)) ? k + GETARG_C(i) : s2v(base + GETARG_C(i));
        if (luaV_fastget(L, s2v(ra), rb, slot, luaH_getstr)) {
          luaH_fastset(L, hvalue(s2v(ra)), slot, rc);
          luaC_barrierback(L, obj2gco(hvalue(s2v(ra))), rc);
        }
        else {
          L->top = base;
          luaV_finishset(L, s2v(ra), rb, rc, slot);
          ci->u.l.savedpc = pc;
          base = ci->func + 1;
        }
        break;
      }
      case OP_NEWTABLE: {
        int b = GETARG_B(i);
        int c = GETARG_C(i);
        Table *t;
        if (b > 0) b = 1 << (b - 1);
        if (GETARG_k(i)) {
          lua_assert(GET_OPCODE(*pc) == OP_EXTRAARG);
          c += GETARG_Ax(*pc++) * (MAXARG_C + 1);
        }
        t = luaH_new(L);
        sethvalue2s(L, ra, t);
        if (b != 0 || c != 0)
          luaH_resize(L, t, b, c);
        checkGC(L, ra + 1);
        break;
      }
      case OP_SELF: {
        const TValue *slot;
        TValue *rb = s2v(base + GETARG_B(i));
        TValue *rc = k + GETARG_C(i);
        TString *key = tsvalue(rc);
        setobj2s(L, ra + 1, rb);
        if (luaV_fastget(L, rb, key, slot, luaH_getstr)) {
          setobj2s(L, ra, slot);
        }
        else {
          L->top = ra + 2;
          luaV_finishget(L, rb, rc, ra, slot);
          ci->u.l.savedpc = pc;
          base = ci->func + 1;
        }
        break;
      }
      case OP_ADDI: {
        TValue *rb = s2v(base + GETARG_B(i));
        int ic = GETARG_sC(i);
        if (ttisinteger(rb)) {
          setivalue(s2v(ra), intop(+, ivalue(rb), ic));
        }
        else if (ttisfloat(rb)) {
          setfltvalue(s2v(ra), luai_numadd(L, fltvalue(rb), cast_num(ic)));
        }
        else {
          TValue rc;
          setivalue(&rc, ic);
          luaT_trybiniTM(L, rb, ic, 0, ra, TM_ADD);
          ci->u.l.savedpc = pc;
          base = ci->func + 1;
        }
        break;
      }
      case OP_ADDK: case OP_SUBK: case OP_MULK: case OP_DIVK:
      case OP_MODK: case OP_POWK: case OP_IDIVK: {
        TValue *rb = s2v(base + GETARG_B(i));
        TValue *rc = k + GETARG_C(i);
        if (ttisinteger(rb) && ttisinteger(rc)) {
          lua_Integer ib = ivalue(rb), ic = ivalue(rc);
          switch (op) {
            case OP_ADDK: setivalue(s2v(ra), intop(+, ib, ic)); break;
            case OP_SUBK: setivalue(s2v(ra), intop(-, ib, ic)); break;
            case OP_MULK: setivalue(s2v(ra), intop(*, ib, ic)); break;
            default: {
              TValue tv; setobj(L, &tv, rc);
              luaO_arith(L, (op-OP_ADDK) + LUA_OPADD, rb, &tv, s2v(ra));
            }
          }
        }
        else if (ttisnumber(rb) && ttisnumber(rc)) {
          lua_Number n1 = ttisfloat(rb) ? fltvalue(rb) : cast_num(ivalue(rb));
          lua_Number n2 = ttisfloat(rc) ? fltvalue(rc) : cast_num(ivalue(rc));
          lua_Number r;
          switch (op) {
            case OP_ADDK: r = luai_numadd(L, n1, n2); break;
            case OP_SUBK: r = luai_numsub(L, n1, n2); break;
            case OP_MULK: r = luai_nummul(L, n1, n2); break;
            case OP_DIVK: r = luai_numdiv(L, n1, n2); break;
            case OP_MODK: luai_nummod(L, n1, n2, r); break;
            case OP_POWK: r = luai_numpow(L, n1, n2); break;
            case OP_IDIVK: r = luai_numidiv(L, n1, n2); break;
            default: r = 0; break;
          }
          setfltvalue(s2v(ra), r);
        }
        else {
          luaT_trybinTM(L, rb, rc, ra, cast(TMS, (op-OP_ADDK) + TM_ADD));
          ci->u.l.savedpc = pc;
          base = ci->func + 1;
        }
        break;
      }
      case OP_BANDK: case OP_BORK: case OP_BXORK: {
        TValue *rb = s2v(base + GETARG_B(i));
        TValue *rc = k + GETARG_C(i);
        if (ttisinteger(rb) && ttisinteger(rc)) {
          lua_Integer ib = ivalue(rb), ic = ivalue(rc);
          switch (op) {
            case OP_BANDK: setivalue(s2v(ra), intop(&, ib, ic)); break;
            case OP_BORK:  setivalue(s2v(ra), intop(|, ib, ic)); break;
            case OP_BXORK: setivalue(s2v(ra), intop(^, ib, ic)); break;
            default: break;
          }
        }
        else {
          luaT_trybinTM(L, rb, rc, ra, cast(TMS, (op-OP_BANDK) + TM_BAND));
          ci->u.l.savedpc = pc;
          base = ci->func + 1;
        }
        break;
      }
      case OP_SHRI: {
        TValue *rb = s2v(base + GETARG_B(i));
        int ic = GETARG_sC(i);
        lua_Integer ib;
        if (tointegerns(rb, &ib)) {
          setivalue(s2v(ra), luaV_shiftl(ib, -ic));
        }
        else {
          luaT_trybiniTM(L, rb, ic, 1, ra, TM_SHR);
          ci->u.l.savedpc = pc;
          base = ci->func + 1;
        }
        break;
      }
      case OP_SHLI: {
        TValue *rb = s2v(base + GETARG_B(i));
        int ic = GETARG_sC(i);
        lua_Integer ib;
        if (tointegerns(rb, &ib)) {
          setivalue(s2v(ra), luaV_shiftl(ic, ib));
        }
        else {
          luaT_trybiniTM(L, rb, ic, 0, ra, TM_SHL);
          ci->u.l.savedpc = pc;
          base = ci->func + 1;
        }
        break;
      }
      case OP_ADD: case OP_SUB: case OP_MUL: case OP_DIV:
      case OP_MOD: case OP_POW: case OP_IDIV: {
        TValue *rb = s2v(base + GETARG_B(i));
        TValue *rc = s2v(base + GETARG_C(i));
        if (ttisinteger(rb) && ttisinteger(rc)) {
          lua_Integer ib = ivalue(rb), ic = ivalue(rc);
          switch (op) {
            case OP_ADD: setivalue(s2v(ra), intop(+, ib, ic)); break;
            case OP_SUB: setivalue(s2v(ra), intop(-, ib, ic)); break;
            case OP_MUL: setivalue(s2v(ra), intop(*, ib, ic)); break;
            case OP_IDIV:
              if (ic == 0) luaG_runerror(L, "attempt to perform 'n//0'");
              setivalue(s2v(ra), luaV_idiv(L, ib, ic)); break;
            case OP_MOD:
              if (ic == 0) luaG_runerror(L, "attempt to perform 'n%%0'");
              setivalue(s2v(ra), luaV_mod(L, ib, ic)); break;
            default: goto floatops;
          }
        }
        else if (ttisnumber(rb) && ttisnumber(rc)) {
          floatops: {
            lua_Number n1 = ttisfloat(rb) ? fltvalue(rb) : cast_num(ivalue(rb));
            lua_Number n2 = ttisfloat(rc) ? fltvalue(rc) : cast_num(ivalue(rc));
            lua_Number r;
            switch (op) {
              case OP_ADD: r = luai_numadd(L, n1, n2); break;
              case OP_SUB: r = luai_numsub(L, n1, n2); break;
              case OP_MUL: r = luai_nummul(L, n1, n2); break;
              case OP_DIV: r = luai_numdiv(L, n1, n2); break;
              case OP_MOD: luai_nummod(L, n1, n2, r); break;
              case OP_POW: r = luai_numpow(L, n1, n2); break;
              case OP_IDIV: r = luai_numidiv(L, n1, n2); break;
              default: r = 0; break;
            }
            setfltvalue(s2v(ra), r);
          }
        }
        else {
          luaT_trybinTM(L, rb, rc, ra, cast(TMS, (op-OP_ADD) + TM_ADD));
          ci->u.l.savedpc = pc;
          base = ci->func + 1;
        }
        break;
      }
      case OP_BAND: case OP_BOR: case OP_BXOR: case OP_SHL: case OP_SHR: {
        TValue *rb = s2v(base + GETARG_B(i));
        TValue *rc = s2v(base + GETARG_C(i));
        lua_Integer ib, ic;
        if (tointegerns(rb, &ib) && tointegerns(rc, &ic)) {
          switch (op) {
            case OP_BAND: setivalue(s2v(ra), intop(&, ib, ic)); break;
            case OP_BOR:  setivalue(s2v(ra), intop(|, ib, ic)); break;
            case OP_BXOR: setivalue(s2v(ra), intop(^, ib, ic)); break;
            case OP_SHL:  setivalue(s2v(ra), luaV_shiftl(ib, ic)); break;
            case OP_SHR:  setivalue(s2v(ra), luaV_shiftl(ib, -ic)); break;
            default: break;
          }
        }
        else {
          luaT_trybinTM(L, rb, rc, ra, cast(TMS, (op-OP_BAND) + TM_BAND));
          ci->u.l.savedpc = pc;
          base = ci->func + 1;
        }
        break;
      }
      case OP_MMBIN: {
        Instruction ni = *(pc - 2);
        TValue *rb = s2v(base + GETARG_B(i));
        TMS event = cast(TMS, GETARG_C(i));
        TValue *ra2 = base + GETARG_A(ni);
        luaT_trybinTM(L, s2v(ra), rb, ra2, event);
        ci->u.l.savedpc = pc;
        base = ci->func + 1;
        break;
      }
      case OP_MMBINI: {
        Instruction ni = *(pc - 2);
        int imm = GETARG_sB(i);
        TMS event = cast(TMS, GETARG_C(i));
        TValue *ra2 = base + GETARG_A(ni);
        luaT_trybiniTM(L, s2v(ra), imm, GETARG_k(i), ra2, event);
        ci->u.l.savedpc = pc;
        base = ci->func + 1;
        break;
      }
      case OP_MMBINK: {
        Instruction ni = *(pc - 2);
        TValue *rb = k + GETARG_B(i);
        TMS event = cast(TMS, GETARG_C(i));
        TValue *ra2 = base + GETARG_A(ni);
        luaT_trybinassocTM(L, s2v(ra), rb, GETARG_k(i), ra2, event);
        ci->u.l.savedpc = pc;
        base = ci->func + 1;
        break;
      }
      case OP_UNM: {
        TValue *rb = s2v(base + GETARG_B(i));
        if (ttisinteger(rb)) {
          setivalue(s2v(ra), intop(-, 0, ivalue(rb)));
        }
        else if (ttisfloat(rb)) {
          setfltvalue(s2v(ra), luai_numunm(L, fltvalue(rb)));
        }
        else {
          luaT_trybinTM(L, rb, rb, ra, TM_UNM);
          ci->u.l.savedpc = pc;
          base = ci->func + 1;
        }
        break;
      }
      case OP_BNOT: {
        TValue *rb = s2v(base + GETARG_B(i));
        lua_Integer ib;
        if (tointegerns(rb, &ib)) {
          setivalue(s2v(ra), intop(^, ib, -1));
        }
        else {
          luaT_trybinTM(L, rb, rb, ra, TM_BNOT);
          ci->u.l.savedpc = pc;
          base = ci->func + 1;
        }
        break;
      }
      case OP_NOT: {
        TValue *rb = s2v(base + GETARG_B(i));
        setbvalue(s2v(ra), l_isfalse(rb));
        break;
      }
      case OP_LEN: {
        luaV_objlen(L, ra, s2v(base + GETARG_B(i)));
        ci->u.l.savedpc = pc;
        base = ci->func + 1;
        break;
      }
      case OP_CONCAT: {
        int n = GETARG_B(i);
        L->top = ra + n;
        luaV_concat(L, n);
        ci->u.l.savedpc = pc;
        base = ci->func + 1;
        checkGC(L, L->top);
        break;
