static int forprep (lua_State *L, StkId ra) {
  TValue *pinit = s2v(ra);
  TValue *plimit = s2v(ra + 1);
  TValue *pstep = s2v(ra + 2);
  if (ttisinteger(pinit) && ttisinteger(pstep)) {
    lua_Integer init = ivalue(pinit);
    lua_Integer step = ivalue(pstep);
    lua_Integer limit;
    if (step == 0) luaG_runerror(L, "'for' step is zero");
    if (ttisinteger(plimit)) limit = ivalue(plimit);
    else if (ttisfloat(plimit)) {
      lua_Number flimit = fltvalue(plimit);
      if (!luaV_flttointeger(flimit, &limit, (step < 0 ? F2Iceil : F2Ifloor)))
        goto try_float;
    }
    else luaG_forerror(L, plimit, "limit");
    {
      lua_Unsigned count;
      if (step > 0) {
        count = (limit < init) ? 0 : ((lua_Unsigned)limit - init)/step + 1;
      }
      else {
        count = (limit > init) ? 0 : ((lua_Unsigned)init - limit)/(-step) + 1;
      }
      setivalue(s2v(ra), (lua_Integer)count);
      setivalue(s2v(ra + 1), step);
      setivalue(s2v(ra + 3), init);
      return (count == 0);
    }
  }
  try_float:
  {
    lua_Number init, limit, step;
    if (!tonumber(pinit, &init)) luaG_forerror(L, pinit, "initial value");
    if (!tonumber(plimit, &limit)) luaG_forerror(L, plimit, "limit");
    if (!tonumber(pstep, &step)) luaG_forerror(L, pstep, "step");
    if (step == 0) luaG_runerror(L, "'for' step is zero");
    setfltvalue(s2v(ra), limit);
    setfltvalue(s2v(ra + 1), step);
    setfltvalue(s2v(ra + 3), init - step);
    return !luai_numlt(0, step ? (init <= limit) : (limit <= init));
  }
}

static void pushclosure (lua_State *L, Proto *p, UpVal **encup, StkId base, StkId ra) {
  int nup = p->sizeupvalues;
  Upvaldesc *uv = p->upvalues;
  int i;
  LClosure *ncl = luaF_newLclosure(L, nup);
  ncl->p = p;
  setclLvalue2s(L, ra, ncl);
  for (i = 0; i < nup; i++) {
    if (uv[i].instack)
      ncl->upvals[i] = luaF_findupval(L, base + uv[i].idx);
    else {
      ncl->upvals[i] = encup[uv[i].idx];
      luaC_objbarrier(L, ncl, ncl->upvals[i]);
    }
  }
}

