int luaV_lessthan (lua_State *L, const TValue *l, const TValue *r) {
  int res;
  if (ttisinteger(l) && ttisinteger(r))
    return (ivalue(l) < ivalue(r));
  else if (ttisnumber(l) && ttisnumber(r)) {
    lua_Number n1 = ttisfloat(l) ? fltvalue(l) : cast_num(ivalue(l));
    lua_Number n2 = ttisfloat(r) ? fltvalue(r) : cast_num(ivalue(r));
    return luai_numlt(n1, n2);
  }
  else if (ttisstring(l) && ttisstring(r))
    return l_strcmp(tsvalue(l), tsvalue(r)) < 0;
  else if ((res = luaT_callorderTM(L, l, r, TM_LT)) < 0)
    luaG_ordererror(L, l, r);
  return res;
}

int luaV_lessequal (lua_State *L, const TValue *l, const TValue *r) {
  int res;
  if (ttisinteger(l) && ttisinteger(r))
