int luaK_code (FuncState *fs, Instruction i) {
  Proto *f = fs->f;
  int pc = fs->pc;
  luaM_growvector(fs->ls->L, f->code, pc, f->sizecode, Instruction,
                  MAX_INT, "opcodes");
  f->code[pc] = i;
  /* line info */
  luaM_growvector(fs->ls->L, f->lineinfo, pc, f->sizelineinfo, ls_byte,
                  MAX_INT, "opcodes");
  {
    int linediff;
    if (fs->previousline == 0)
      linediff = 0;
    else
      linediff = fs->ls->lastline - fs->previousline;
    if (linediff < -0x80 || linediff > 0x7e) {
      /* need absolute line info */
      luaM_growvector(fs->ls->L, f->abslineinfo, fs->nabslineinfo,
                      f->sizeabslineinfo, AbsLineInfo, MAX_INT, "lines");
      f->abslineinfo[fs->nabslineinfo].pc = pc;
      f->abslineinfo[fs->nabslineinfo].line = fs->ls->lastline;
      fs->nabslineinfo++;
      linediff = ABSLINEINFO;
    }
    f->lineinfo[pc] = cast_byte(linediff);
    fs->previousline = fs->ls->lastline;
  }
  fs->pc = pc + 1;
