      int pfrom = GETARG_A(*previous);
      int pto = pfrom + GETARG_B(*previous);
      if ((pfrom <= from && from <= pto + 1) ||
          (from <= pfrom && pfrom <= from + n)) {
        if (pfrom < from) from = pfrom;
        if (pto > from + n - 1) n = pto - from + 1;
        SETARG_A(*previous, from);
