    finishbinexpval(fs, e2, e1, OP_SHLI, v2, 1, line, OP_MMBINI, event);
  }
  else if (luaK_exp2K(fs, e2)) {
    int v2 = e2->u.info;
    finishbinexpval(fs, e1, e2, opc + (OP_BANDK - OP_BAND), v2, 0, line,
