  if (e1->k != VKINT || e2->k != VKINT || hasjumps(e1) || hasjumps(e2))
    return 0;
  i1 = e1->u.ival;
  i2 = e2->u.ival;
  switch (op) {
    case OPR_ADD: r = intop(+, i1, i2); break;
    case OPR_SUB: r = intop(-, i1, i2); break;
    case OPR_MUL: r = intop(*, i1, i2); break;
    case OPR_IDIV: if (i2 == 0) return 0; r = luaV_idiv(NULL, i1, i2); break;
    case OPR_MOD: if (i2 == 0) return 0; r = luaV_mod(NULL, i1, i2); break;
    case OPR_BAND: r = intop(&, i1, i2); break;
    case OPR_BOR:  r = intop(|, i1, i2); break;
    case OPR_BXOR: r = intop(^, i1, i2); break;
    case OPR_SHL:  r = luaV_shiftl(i1, i2); break;
    case OPR_SHR:  r = luaV_shiftl(i1, -i2); break;
    default: return 0;
  }
  e1->u.ival = r;
  e1->k = VKINT;
  return 1;
}

