    im = cast_int(e2->u.ival);
    freeexp(fs, e1);
    e1->u.info = codeABC(fs, OP_EQI, r1, im, k);
  }
  else if (isSCint(e1)) {
    swapexp(fs, e1, e2);
    r1 = luaK_exp2anyreg(fs, e1);
    im = cast_int(e2->u.ival);
    freeexp(fs, e1);
    e1->u.info = codeABC(fs, OP_EQI, r1, im, k);
  }
  else {
    r1 = luaK_exp2anyreg(fs, e1);
    r2 = luaK_exp2RK(fs, e2);
    freeexps(fs, e1, e2);
    e1->u.info = codeABC(fs, OP_EQ, r1, r2, k);
  }
  e1->k = VJMP;
}

void luaK_indexed (FuncState *fs, expdesc *t, expdesc *k) {
  lua_assert(!hasjumps(t) && (vkisvar(t->k) || t->k == VNONRELOC));
  if (k->k == VKSTR && luaK_isKstr(fs, k)) {
    int str = luaK_stringK(fs, k->u.strval);
    t->u.ind.idx = str;
    if (t->k == VUPVAL) {
      t->k = VINDEXUP;
    }
    else {
      t->u.ind.t = t->u.info;
      t->k = VINDEXSTR;
    }
  }
  else if (k->k == VKINT && luaK_isKint(fs, k)) {
    t->u.ind.idx = cast_int(k->u.ival);
    t->u.ind.t = t->u.info;
    t->k = VINDEXI;
  }
  else {
    t->u.ind.idx = luaK_exp2anyreg(fs, k);
    t->u.ind.t = t->u.info;
    t->k = VINDEXED;
  }
}

static int luaK_isKstr (FuncState *fs, expdesc *e) {
  return (e->k == VKSTR && !hasjumps(e));
}

static int luaK_isKint (FuncState *fs, expdesc *e) {
  return (e->k == VKINT && !hasjumps(e) &&
          MINARG_C <= e->u.ival && e->u.ival <= MAXARG_C);
}

#define MINARG_C  0
#define NO_JUMP  (-1)

void luaK_goiftrue (FuncState *fs, expdesc *e) {
  int pc;
  luaK_dischargevars(fs, e);
  switch (e->k) {
    case VJMP: {
      invertjump(fs, e);
      pc = e->u.info;
      break;
    }
    case VK: case VKFLT: case VKINT: case VKSTR: case VTRUE: {
      pc = NO_JUMP;
      break;
    }
    default: {
      pc = jumponcond(fs, e, 0);
      break;
    }
  }
  luaK_concat(fs, &e->f, pc);
  luaK_patchtohere(fs, e->t);
  e->t = NO_JUMP;
}

void luaK_goiffalse (FuncState *fs, expdesc *e) {
  int pc;
  luaK_dischargevars(fs, e);
  switch (e->k) {
    case VJMP: {
      pc = e->u.info;
      break;
    }
    case VNIL: case VFALSE: {
      pc = NO_JUMP;
      break;
    }
    default: {
      pc = jumponcond(fs, e, 1);
      break;
    }
  }
  luaK_concat(fs, &e->t, pc);
  luaK_patchtohere(fs, e->f);
  e->f = NO_JUMP;
}

static void invertjump (FuncState *fs, expdesc *e) {
  Instruction *pc = getinstruction(fs, e);
  lua_assert(testTMode(GET_OPCODE(*pc)) && GET_OPCODE(*pc) != OP_TESTSET &&
             GET_OPCODE(*pc) != OP_TEST);
  SETARG_k(*pc, (GETARG_k(*pc) ^ 1));
}

static int jumponcond (FuncState *fs, expdesc *e, int cond) {
  if (e->k == VRELOC) {
    Instruction ie = *getinstruction(fs, e);
    if (GET_OPCODE(ie) == OP_NOT) {
      fs->pc--;
      return condjump(fs, OP_TEST, GETARG_B(ie), 0, 0, !cond);
    }
  }
  discharge2anyreg(fs, e);
  freeexp(fs, e);
  return condjump(fs, OP_TEST, e->u.info, 0, 0, cond);
}

static int condjump (FuncState *fs, OpCode op, int A, int B, int C, int k) {
  codeABC(fs, op, A, B, C);
  return luaK_jump(fs);
}

void luaK_storevar (FuncState *fs, expdesc *var, expdesc *ex) {
  switch (var->k) {
    case VLOCAL: {
      freeexp(fs, ex);
      exp2reg(fs, ex, var->u.var.ridx);
      return;
    }
    case VUPVAL: {
      int e = luaK_exp2anyreg(fs, ex);
      codeABC(fs, OP_SETUPVAL, e, var->u.info, 0);
      break;
    }
    case VINDEXUP: {
      int e = luaK_exp2RK(fs, ex);
      codeABC(fs, OP_SETTABUP, var->u.ind.t, var->u.ind.idx, e);
      break;
    }
    case VINDEXI: {
      int e = luaK_exp2RK(fs, ex);
      codeABC(fs, OP_SETI, var->u.ind.t, var->u.ind.idx, e);
      break;
    }
    case VINDEXSTR: {
      int e = luaK_exp2RK(fs, ex);
      codeABC(fs, OP_SETFIELD, var->u.ind.t, var->u.ind.idx, e);
      break;
    }
    case VINDEXED: {
      int e = luaK_exp2RK(fs, ex);
      codeABC(fs, OP_SETTABLE, var->u.ind.t, var->u.ind.idx, e);
      break;
    }
    default: lua_assert(0); break;
  }
  freeexp(fs, ex);
}

void luaK_self (FuncState *fs, expdesc *e, expdesc *key) {
  int ereg;
  luaK_exp2anyreg(fs, e);
  ereg = e->u.info;
  freeexp(fs, e);
  e->u.info = fs->freereg;
  e->k = VNONRELOC;
  luaK_reserveregs(fs, 2);
  {
    int str = luaK_stringK(fs, key->u.strval);
    codeABC(fs, OP_SELF, e->u.info, ereg, str);
  }
}

void luaK_setreturns (FuncState *fs, expdesc *e, int nresults) {
  if (e->k == VCALL) {
    SETARG_C(*getinstruction(fs, e), nresults + 1);
  }
  else if (e->k == VVARARG) {
    Instruction *pc = getinstruction(fs, e);
    SETARG_C(*pc, nresults + 1);
    SETARG_A(*pc, fs->freereg);
    luaK_reserveregs(fs, 1);
  }
}

void luaK_setoneret (FuncState *fs, expdesc *e) {
  if (e->k == VCALL) {
    lua_assert(GETARG_C(*getinstruction(fs, e)) == 2);
    e->k = VNONRELOC;
    e->u.info = GETARG_A(*getinstruction(fs, e));
  }
  else if (e->k == VVARARG) {
    SETARG_C(*getinstruction(fs, e), 2);
    e->k = VRELOC;
  }
}

static void fixline (FuncState *fs, int line) {
  fs->f->lineinfo[fs->pc - 1] = cast_byte(line - fs->previousline);
  fs->previousline = line;
}

void luaK_fixline (FuncState *fs, int line) {
  fixline(fs, line);
}

void luaK_settablesize (FuncState *fs, int pc, int ra, int asize, int hsize) {
  Instruction *inst = &fs->f->code[pc];
  int rb = (hsize != 0) ? luaO_int2fb(hsize) : 0;
  int extra = asize / (MAXARG_C + 1);
  int rc = asize % (MAXARG_C + 1);
  int k = (extra > 0);
  *inst = CREATE_ABCk(OP_NEWTABLE, ra, rb, rc, k);
  *(inst + 1) = CREATE_Ax(OP_EXTRAARG, extra);
}

void luaK_setlist (FuncState *fs, int base, int nelems, int tostore) {
  lua_assert(tostore != 0 && tostore <= LFIELDS_PER_FLUSH);
  if (tostore == LUA_MULTRET)
    tostore = 0;
  if (nelems <= MAXARG_C)
    codeABC(fs, OP_SETLIST, base, tostore, nelems);
  else {
    int extra = nelems / (MAXARG_C + 1);
    nelems %= (MAXARG_C + 1);
    codeABC(fs, OP_SETLIST, base, tostore, nelems);
    codeextraarg(fs, extra);
  }
  fs->freereg = base + 1;
}

void luaK_finish (FuncState *fs) {
  int i;
  Proto *f = fs->f;
  for (i = 0; i < fs->pc; i++) {
    Instruction *pc = &f->code[i];
    lua_assert(i == 0 || !isOT(*(pc-1)) || GET_OPCODE(*pc) == OP_JMP);
    if (GET_OPCODE(*pc) == OP_RETURN) {
      if (f->is_vararg) {
        SETARG_A(*pc, fs->nactvar);
      }
    }
  }
}

l_noret luaK_semerror (LexState *ls, const char *msg) {
  ls->t.token = 0;
  luaX_syntaxerror(ls, msg);
}

static void luaK_patchclose (FuncState *fs, int list, int level) {
  level++;
  for (; list != NO_JUMP; list = getjump(fs, list)) {
    Instruction *ins = &fs->f->code[list];
    SETARG_A(*ins, level);
  }
}

void luaK_prefix (FuncState *fs, UnOpr op, expdesc *e, int line) {
  static const expdesc emptye = {VFALSE, {0}, NO_JUMP, NO_JUMP};
  switch (op) {
    case OPR_MINUS: {
      if (tonumeral(e, NULL))
        foldneg(fs, e);
      else
        codeunexpval(fs, OP_UNM, e, line);
      break;
    }
    case OPR_BNOT: {
      if (tonumeral(e, NULL))
        foldbnot(fs, e);
      else
        codeunexpval(fs, OP_BNOT, e, line);
      break;
    }
    case OPR_NOT: {
      if (e->k == VFALSE || e->k == VNIL) {
        e->k = VTRUE;
      }
      else if (e->k == VTRUE || e->k == VK || e->k == VKINT ||
               e->k == VKFLT || e->k == VKSTR) {
        e->k = VFALSE;
      }
      else {
        codeunexpval(fs, OP_NOT, e, line);
        return;
      }
      {
        int temp = e->f;
        e->f = e->t;
        e->t = temp;
      }
      break;
    }
    case OPR_LEN: {
      codeunexpval(fs, OP_LEN, e, line);
      break;
    }
    default: lua_assert(0); break;
  }
}

static int tonumeral (expdesc *e, TValue *v) {
  if (hasjumps(e)) return 0;
  switch (e->k) {
    case VKINT: if (v) setivalue(v, e->u.ival); return 1;
    case VKFLT: if (v) setfltvalue(v, e->u.nval); return 1;
    default: return 0;
  }
}

static void foldneg (FuncState *fs, expdesc *e) {
  if (e->k == VKINT) {
    e->u.ival = intop(-, 0, e->u.ival);
  }
  else {
    lua_assert(e->k == VKFLT);
    e->u.nval = luai_numunm(fs->ls->L, e->u.nval);
  }
}

static void foldbnot (FuncState *fs, expdesc *e) {
  lua_assert(e->k == VKINT);
  e->u.ival = intop(^, e->u.ival, -1);
}

static void codenot (FuncState *fs, expdesc *e) {
  switch (e->k) {
    case VNIL: case VFALSE: e->k = VTRUE; break;
    case VK: case VKFLT: case VKINT: case VKSTR: case VTRUE: e->k = VFALSE; break;
    default: {
      codeunexpval(fs, OP_NOT, e, 0);
      return;
    }
  }
  {
    int temp = e->f;
    e->f = e->t;
    e->t = temp;
  }
}

void luaK_infix (FuncState *fs, BinOpr op, expdesc *v) {
  luaK_dischargevars(fs, v);
  switch (op) {
    case OPR_AND: {
      luaK_goiftrue(fs, v);
      break;
    }
    case OPR_OR: {
      luaK_goiffalse(fs, v);
      break;
    }
    case OPR_CONCAT: {
      luaK_exp2nextreg(fs, v);
      break;
    }
    case OPR_ADD: case OPR_SUB: case OPR_MUL: case OPR_DIV: case OPR_MOD:
    case OPR_POW: case OPR_IDIV: {
      if (!tonumeral(v, NULL))
        luaK_exp2anyreg(fs, v);
      break;
    }
    default: {
      if (!isSCint(v) && !isSCflt(v))
        luaK_exp2anyreg(fs, v);
      break;
    }
  }
}

static int isSCflt (expdesc *e) {
  if (e->k != VKFLT || hasjumps(e)) return 0;
  {
    lua_Number n = e->u.nval;
    lua_Number ni = l_floor(n);
    return (n == ni && MINARG_sB <= ni && ni <= MAXARG_sB);
  }
}

#define MINARG_sB  (-(1 << (SIZE_B - 1)))

void luaK_posfix (FuncState *fs, BinOpr op, expdesc *e1, expdesc *e2,
                 int line) {
  luaK_dischargevars(fs, e2);
  if (foldbinop(op) && luaK_intfolding(fs, op, e1, e2))
    return;
  switch (op) {
    case OPR_AND: {
      lua_assert(e1->t == NO_JUMP);
      luaK_concat(fs, &e2->f, e1->f);
      *e1 = *e2;
      break;
    }
    case OPR_OR: {
      lua_assert(e1->f == NO_JUMP);
      luaK_concat(fs, &e2->t, e1->t);
      *e1 = *e2;
      break;
    }
    case OPR_CONCAT: {
      luaK_exp2val(fs, e2);
      codeconcat(fs, e1, e2, line);
      break;
    }
    case OPR_ADD: case OPR_MUL: {
      /* check for commutative optimization */
      codearith(fs, op + (OP_ADD - OPR_ADD), e1, e2, 1, line);
      break;
    }
    case OPR_SUB: case OPR_DIV: case OPR_IDIV: case OPR_MOD: case OPR_POW: {
      codearith(fs, op + (OP_ADD - OPR_ADD), e1, e2, 0, line);
      break;
    }
    case OPR_BAND: case OPR_BOR: case OPR_BXOR: {
      codebitwise(fs, op, e1, e2, 1, line);
      break;
    }
    case OPR_SHL: {
      codebitwise(fs, op, e1, e2, 0, line);
      break;
    }
    case OPR_SHR: {
      codebitwise(fs, op, e1, e2, 0, line);
      break;
    }
    case OPR_EQ: case OPR_NE: {
      codeeq(fs, op, e1, e2);
      break;
    }
    case OPR_LT: case OPR_LE: {
      codeorder(fs, op + (OP_LT - OPR_LT), e1, e2);
      break;
    }
    case OPR_GT: case OPR_GE: {
      swapexp(fs, e1, e2);
      codeorder(fs, (op == OPR_GT ? OP_LT : OP_LE), e1, e2);
      break;
    }
    default: lua_assert(0);
  }
}

static void codearith (FuncState *fs, OpCode op, expdesc *e1, expdesc *e2,
                       int flip, int line) {
  TMS event = cast(TMS, (op - OP_ADD) + TM_ADD);
  if (isSCint(e2) && flip) {
    int v2 = cast_int(e2->u.ival);
    finishbinexpval(fs, e1, e2, op + (OP_ADDI - OP_ADD), v2, 0, line,
                    OP_MMBINI, event);
  }
  else if (isSCint(e1) && flip && commutativeop(op)) {
    int v2 = cast_int(e1->u.ival);
    finishbinexpval(fs, e2, e1, op + (OP_ADDI - OP_ADD), v2, 1, line,
                    OP_MMBINI, event);
  }
  else if (luaK_exp2K(fs, e2)) {
    int v2 = e2->u.info;
    finishbinexpval(fs, e1, e2, op + (OP_ADDK - OP_ADD), v2, 0, line,
                    OP_MMBINK, event);
  }
  else if (flip && commutativeop(op) && luaK_exp2K(fs, e1)) {
    int v2 = e1->u.info;
    finishbinexpval(fs, e2, e1, op + (OP_ADDK - OP_ADD), v2, 1, line,
                    OP_MMBINK, event);
  }
  else {
    codebinexpval(fs, op, e1, e2, line);
  }
}

static int commutativeop (OpCode op) {
  return (op == OP_ADD || op == OP_MUL ||
          op == OP_BAND || op == OP_BOR || op == OP_BXOR);
}

static void codebitwise (FuncState *fs, BinOpr op, expdesc *e1, expdesc *e2,
                         int flip, int line) {
  TMS event;
  OpCode opc;
  switch (op) {
    case OPR_BAND: opc = OP_BAND; event = TM_BAND; break;
    case OPR_BOR:  opc = OP_BOR;  event = TM_BOR; break;
    case OPR_BXOR: opc = OP_BXOR; event = TM_BXOR; break;
    case OPR_SHL:  opc = OP_SHL;  event = TM_SHL; break;
    case OPR_SHR:  opc = OP_SHR;  event = TM_SHR; break;
    default: opc = OP_BAND; event = TM_BAND; break;
  }
  if (isSCint(e2) && flip) {
    int v2 = cast_int(e2->u.ival);
    finishbinexpval(fs, e1, e2, opc + (OP_BANDK - OP_BAND), v2, 0, line,
                    OP_MMBINI, event);
  }
  else if (isSCint(e1) && (op == OPR_SHR) && flip) {
    int v2 = cast_int(e1->u.ival);
    finishbinexpval(fs, e2, e1, OP_SHLI, v2, 1, line, OP_MMBINI, event);
  }
  else if (luaK_exp2K(fs, e2)) {
    int v2 = e2->u.info;
    finishbinexpval(fs, e1, e2, opc + (OP_BANDK - OP_BAND), v2, 0, line,
                    OP_MMBINK, event);
  }
  else if (flip && (op != OPR_SHL && op != OPR_SHR) && luaK_exp2K(fs, e1)) {
    int v2 = e1->u.info;
    finishbinexpval(fs, e2, e1, opc + (OP_BANDK - OP_BAND), v2, 1, line,
                    OP_MMBINK, event);
  }
  else
    codebinexpval(fs, opc, e1, e2, line);
}

static int luaK_intfolding (FuncState *fs, BinOpr op, expdesc *e1, expdesc *e2) {
  lua_Integer i1, i2, r;
  if (!ttisinteger(e1->k == VKINT ? &(TValue){.i = e1->u.ival, .tt_ = LUA_VNUMINT} : NULL))
    return 0;
  /* simplified folding - just for integer constants */
  if (e1->k != VKINT || e2->k != VKINT || hasjumps(e1) || hasjumps(e2))
    return 0;
  i1 = e1->u.ival;
  i2 = e2->u.ival;
  switch (op) {
    case OPR_ADD: r = intop(+, i1, i2); break;
    case OPR_SUB: r = intop(-, i1, i2); break;
    case OPR_MUL: r = intop(*, i1, i2); break;
    case OPR_IDIV: if (i2 == 0) return 0; r = luaV_idiv(NULL, i1, i2); break;
    case OPR_MOD: if (i2 == 0) return 0; r = luaV_mod(NULL, i1, i2); break;
    case OPR_BAND: r = intop(&, i1, i2); break;
    case OPR_BOR:  r = intop(|, i1, i2); break;
    case OPR_BXOR: r = intop(^, i1, i2); break;
    case OPR_SHL:  r = luaV_shiftl(i1, i2); break;
    case OPR_SHR:  r = luaV_shiftl(i1, -i2); break;
    default: return 0;
  }
  e1->u.ival = r;
  e1->k = VKINT;
  return 1;
}

