  int line = ls->linenumber;
  switch (ls->t.token) {
    case '(': {
      luaX_next(ls);
      if (ls->t.token == ')')
        args.k = VVOID;
      else
        explist(ls, &args);
      check_condition(ls, ls->t.token == ')', "')' expected");
      luaX_next(ls);
      break;
