    case TK_NIL: {
      init_exp(v, VNIL, 0);
      luaX_next(ls);
      break;
    }
    case TK_TRUE: {
      init_exp(v, VTRUE, 0);
      luaX_next(ls);
      break;
    }
    case TK_FALSE: {
      init_exp(v, VFALSE, 0);
      luaX_next(ls);
