static void checknext (LexState *ls, int c) {
  check(ls, c);
  luaX_next(ls);
}

#define check_condition(ls,c,msg)  { if (!(c)) luaX_syntaxerror(ls, msg); }

static void checkname (LexState *ls, expdesc *e) {
  TString *ts;
  check(ls, TK_NAME);
  ts = ls->t.seminfo.ts;
  luaX_next(ls);
  init_exp(e, VKSTR, 0);
  e->u.strval = ts;
}

static void init_exp (expdesc *e, expkind k, int i) {
  e->t = e->f = NO_JUMP;
  e->k = k;
  e->u.info = i;
}

static void codestring (LexState *ls, expdesc *e, TString *s) {
  init_exp(e, VKSTR, 0);
  e->u.strval = s;
}

static void codename (LexState *ls, expdesc *e) {
  codestring(ls, e, str_checkname(ls));
}

static TString *str_checkname (LexState *ls) {
  TString *ts;
  check(ls, TK_NAME);
  ts = ls->t.seminfo.ts;
  luaX_next(ls);
  return ts;
}

/* variable handling */
static int registerlocalvar (LexState *ls, FuncState *fs, TString *varname) {
  Proto *f = fs->f;
  int oldsize = f->sizelocvars;
  luaM_growvector(ls->L, f->locvars, fs->ndebugvars, f->sizelocvars, LocVar, 
                  SHRT_MAX, "local variables");
  while (oldsize < f->sizelocvars)
    f->locvars[oldsize++].varname = NULL;
  f->locvars[fs->ndebugvars].varname = varname;
  f->locvars[fs->ndebugvars].startpc = fs->pc;
  luaC_objbarrier(ls->L, f, varname);
  return fs->ndebugvars++;
}

static int newupvalue (FuncState *fs, TString *name, expdesc *v) {
  Proto *f = fs->f;
  int oldsize = f->sizeupvalues;
  checklimit(fs, fs->nups + 1, MAXUPVAL, "upvalues");
  luaM_growvector(fs->ls->L, f->upvalues, fs->nups, f->sizeupvalues, Upvaldesc,
                  MAXUPVAL, "upvalues");
  while (oldsize < f->sizeupvalues)
    f->upvalues[oldsize++].name = NULL;
  f->upvalues[fs->nups].instack = (v->k == VLOCAL);
  f->upvalues[fs->nups].idx = cast_byte(v->u.info);
  f->upvalues[fs->nups].kind = VDKREG;
  f->upvalues[fs->nups].name = name;
  luaC_objbarrier(fs->ls->L, f, name);
  return fs->nups++;
}

static int searchupvalue (FuncState *fs, TString *name) {
  int i;
  Upvaldesc *up = fs->f->upvalues;
  for (i = 0; i < fs->nups; i++) {
    if (eqstr(up[i].name, name)) return i;
  }
  return -1;
}

#define eqstr(a,b)  ((a) == (b))

static int searchvar (FuncState *fs, TString *n, expdesc *var) {
  int i;
  for (i = cast_int(fs->nactvar) - 1; i >= 0; i--) {
    Vardesc *vd = getlocalvardesc(fs, i);
    if (eqstr(n, vd->vd.name)) {
      if (vd->vd.kind == RDKCTC)
        init_exp(var, VCONST, fs->firstlocal + i);
      else {
        init_exp(var, VLOCAL, 0);
        var->u.var.ridx = vd->vd.ridx;
        var->u.var.vidx = i;
      }
      return cast_int(var->k);
    }
  }
  return -1;
}

static Vardesc *getlocalvardesc (FuncState *fs, int vidx) {
  return &fs->ls->dyd->actvar.arr[fs->firstlocal + vidx];
}

static int reglevel (FuncState *fs, int nvar) {
  while (nvar-- > 0) {
    Vardesc *vd = getlocalvardesc(fs, nvar);
    if (vd->vd.kind != RDKCTC)
      return vd->vd.ridx + 1;
  }
  return 0;
}

int luaY_nvarstack (FuncState *fs) {
  return reglevel(fs, fs->nactvar);
}

static LexState *markupval (FuncState *fs, int level) {
  /* mark that there is a closure using local variable at level */
  fs->needclose = (level < reglevel(fs, fs->nactvar));
  return fs->ls;
}

static void singlevar (LexState *ls, expdesc *var) {
  TString *varname = str_checkname(ls);
  FuncState *fs = ls->fs;
  if (singlevaraux(fs, varname, var, 1) == VVOID) {
    expdesc key;
    singlevaraux(fs, ls->envn, var, 1);
    lua_assert(var->k == VLOCAL || var->k == VUPVAL);
    codestring(ls, &key, varname);
    luaK_indexed(fs, var, &key);
  }
}

static int singlevaraux (FuncState *fs, TString *n, expdesc *var, int base) {
  if (fs == NULL) {
    init_exp(var, VVOID, 0);
    return VVOID;
  }
  else {
    int v = searchvar(fs, n, var);
    if (v >= 0) {
      if (v == VLOCAL && !base) {
        markupval(fs, var->u.var.ridx);
      }
      return v;
    }
    else {
      if (singlevaraux(fs->prev, n, var, 0) == VVOID)
        return VVOID;
      else {
        int idx = searchupvalue(fs, n);
        if (idx < 0) {
          idx = newupvalue(fs, n, var);
        }
        init_exp(var, VUPVAL, idx);
        return VUPVAL;
      }
    }
  }
}

/* adjust assigned values */
static void adjust_assign (LexState *ls, int nvars, int nexps, expdesc *e) {
  FuncState *fs = ls->fs;
  int needed = nvars - nexps;
  if (hasmultret(e->k)) {
    int extra = needed + 1;
    if (extra < 0) extra = 0;
    luaK_setreturns(fs, e, extra);
    needed -= extra - 1;
  }
  else {
    if (e->k != VVOID)
      luaK_exp2nextreg(fs, e);
    if (needed > 0)
      luaK_nil(fs, fs->freereg, needed);
  }
  if (needed > 0)
    luaK_reserveregs(fs, needed);
  else
    fs->freereg += needed;
}

/* block management */
typedef struct BlockCnt {
  struct BlockCnt *previous;
  int firstlabel;
  int firstgoto;
  lu_byte nactvar;
  lu_byte upval;
  lu_byte isloop;
  lu_byte insidetbc;
} BlockCnt;

static void enterblock (FuncState *fs, BlockCnt *bl, lu_byte isloop) {
  bl->isloop = isloop;
  bl->nactvar = fs->nactvar;
  bl->firstlabel = fs->ls->dyd->label.n;
  bl->firstgoto = fs->ls->dyd->gt.n;
  bl->upval = 0;
  bl->insidetbc = (fs->bl != NULL && fs->bl->insidetbc);
  bl->previous = fs->bl;
  fs->bl = bl;
}

static void leaveblock (FuncState *fs) {
  BlockCnt *bl = fs->bl;
  LexState *ls = fs->ls;
  int hasclose = 0;
  int stklevel = reglevel(fs, bl->nactvar);
  if (bl->isloop)
    hasclose = creategoto(ls, luaS_newliteral(ls->L, "break"), ls->lastline);
  hasclose = hasclose || bl->upval;
  if (hasclose) {
    luaK_codeABCk(fs, OP_CLOSE, stklevel, 0, 0, 0);
  }
  fs->bl = bl->previous;
  removevars(fs, bl->nactvar);
  lua_assert(bl->nactvar == fs->nactvar);
  fs->freereg = cast_byte(stklevel);
  ls->dyd->label.n = bl->firstlabel;
  if (bl->previous)
    movegotos(fs, bl);
  else {
    if (bl->firstgoto < ls->dyd->gt.n)
      closegoto(ls, bl->firstgoto, luaS_newliteral(ls->L, "break"));
  }
}

static void removevars (FuncState *fs, int tolevel) {
  fs->ls->dyd->actvar.n -= (fs->nactvar - tolevel);
  while (fs->nactvar > tolevel) {
    LocVar *lv = getlocalvar(fs, --fs->nactvar);
    if (lv) lv->endpc = fs->pc;
  }
}

static LocVar *getlocalvar (FuncState *fs, int i) {
  Vardesc *vd = getlocalvardesc(fs, i);
  if (vd->vd.kind == RDKCTC || vd->vd.pidx < 0) return NULL;
  return &fs->f->locvars[vd->vd.pidx];
}

static void movegotos (FuncState *fs, BlockCnt *bl) {
  LexState *ls = fs->ls;
  Labellist *gl = &ls->dyd->gt;
  int i = bl->firstgoto;
  while (i < gl->n) {
    Labeldesc *gt = &gl->arr[i];
    lua_assert(gt->nactvar <= bl->nactvar);
    gt->nactvar = bl->nactvar;
    i++;
  }
}

static int creategoto (LexState *ls, TString *name, int line) {
  /* simplified - just create a goto */
  return 0;
}

static void closegoto (LexState *ls, int g, TString *name) {
  /* simplified goto handling */
}

static void newlocalvar (LexState *ls, TString *name) {
  FuncState *fs = ls->fs;
  Dyndata *dyd = ls->dyd;
  int reg = luaY_nvarstack(fs);
  Vardesc *var;
  checklimit(fs, dyd->actvar.n + 1 - fs->firstlocal, MAXVARS, "local variables");
  luaM_growvector(ls->L, dyd->actvar.arr, dyd->actvar.n + 1,
                  dyd->actvar.size, Vardesc, MAX_INT, "local variables");
  var = &dyd->actvar.arr[dyd->actvar.n++];
  var->vd.kind = VDKREG;
  var->vd.name = name;
  var->vd.ridx = cast_byte(reg);
  var->vd.pidx = registerlocalvar(ls, fs, name);
}

static void newlocalvarliteral_ (LexState *ls, const char *name, size_t sz) {
  newlocalvar(ls, luaX_newstring(ls, name, sz));
}

#define newlocalvarliteral(ls,v) \
    newlocalvarliteral_(ls, "" v, (sizeof(v)/sizeof(char))-1)

static void adjustlocalvars (LexState *ls, int nvars) {
  FuncState *fs = ls->fs;
  int regs = luaY_nvarstack(fs);
  while (nvars--) {
    int vidx = fs->nactvar++;
    Vardesc *var = getlocalvardesc(fs, vidx);
    var->vd.ridx = cast_byte(regs++);
    var->vd.pidx = registerlocalvar(ls, fs, var->vd.name);
  }
}

/* expression parsing */
static void primaryexp (LexState *ls, expdesc *v) {
  FuncState *fs = ls->fs;
  switch (ls->t.token) {
    case '(': {
      int line = ls->linenumber;
      luaX_next(ls);
      expr(ls, v);
      check_condition(ls, ls->t.token == ')', "')' expected");
      luaX_next(ls);
      luaK_dischargevars(fs, v);
      return;
    }
    case TK_NAME: {
      singlevar(ls, v);
      return;
    }
    default: {
      luaX_syntaxerror(ls, "unexpected symbol near expression");
    }
  }
}

static void suffixedexp (LexState *ls, expdesc *v) {
  FuncState *fs = ls->fs;
  primaryexp(ls, v);
  for (;;) {
    switch (ls->t.token) {
      case '.': {
        luaX_next(ls);
        expdesc key;
        codename(ls, &key);
        luaK_indexed(fs, v, &key);
        break;
      }
      case '[': {
        expdesc key;
        luaK_exp2anyregup(fs, v);
        luaX_next(ls);
        expr(ls, &key);
        checknext(ls, ']');
        luaK_indexed(fs, v, &key);
        break;
      }
      case ':': {
        expdesc key;
        luaX_next(ls);
        codename(ls, &key);
        luaK_self(fs, v, &key);
        callargs(ls, v);
        break;
      }
      case '(': case TK_STRING: case '{': {
        luaK_exp2nextreg(fs, v);
        callargs(ls, v);
        break;
      }
      default: return;
    }
  }
}

static void callargs (LexState *ls, expdesc *f) {
  FuncState *fs = ls->fs;
  expdesc args;
  int base, nparams;
  int line = ls->linenumber;
  switch (ls->t.token) {
    case '(': {
      luaX_next(ls);
      if (ls->t.token == ')')
        args.k = VVOID;
      else
        explist(ls, &args);
      check_condition(ls, ls->t.token == ')', "')' expected");
      luaX_next(ls);
      break;
    }
    case '{': {
      constructor(ls, &args);
      break;
    }
    case TK_STRING: {
      codestring(ls, &args, ls->t.seminfo.ts);
      luaX_next(ls);
      break;
    }
    default: {
      luaX_syntaxerror(ls, "function arguments expected");
    }
  }
  lua_assert(f->k == VNONRELOC);
  base = f->u.info;
  if (hasmultret(args.k))
    nparams = LUA_MULTRET;
  else {
    if (args.k != VVOID)
      luaK_exp2nextreg(fs, &args);
    nparams = fs->freereg - (base + 1);
  }
  init_exp(f, VCALL, luaK_codeABCk(fs, OP_CALL, base, nparams + 1, 2, 0));
  luaK_fixline(fs, line);
  fs->freereg = base + 1;
}

static int explist (LexState *ls, expdesc *v) {
  int n = 1;
  expr(ls, v);
  while (testnext(ls, ',')) {
    luaK_exp2nextreg(ls->fs, v);
    expr(ls, v);
    n++;
  }
  return n;
}

/* constructor */
static void constructor (LexState *ls, expdesc *t) {
  FuncState *fs = ls->fs;
  int line = ls->linenumber;
  int pc = luaK_codeABCk(fs, OP_NEWTABLE, 0, 0, 0, 0);
  luaK_codeABCk(fs, OP_EXTRAARG, 0, 0, 0, 0);
  struct ConsControl {
    expdesc v;
    expdesc *t;
    int nh;
    int na;
    int tostore;
  } cc;
  cc.na = cc.nh = cc.tostore = 0;
  cc.t = t;
  init_exp(t, VRELOC, pc);
  init_exp(&cc.v, VVOID, 0);
  luaK_reserveregs(fs, 1);
  checknext(ls, '{');
  do {
    lua_assert(cc.v.k == VVOID || cc.tostore > 0);
    if (ls->t.token == '}') break;
    closelistfield(fs, &cc);
    switch (ls->t.token) {
      case TK_NAME: {
        if (luaX_lookahead(ls) != '=') {
          listfield(ls, &cc);
        }
        else {
          recfield(ls, &cc);
        }
        break;
      }
      case '[': {
        recfield(ls, &cc);
        break;
      }
      default: {
        listfield(ls, &cc);
        break;
      }
    }
  } while (testnext(ls, ',') || testnext(ls, ';'));
  check_condition(ls, ls->t.token == '}', "'}' expected");
  luaX_next(ls);
  lastlistfield(fs, &cc);
  luaK_settablesize(fs, pc, t->u.info, cc.na, cc.nh);
}

static void closelistfield (FuncState *fs, void *cc_v) {
  struct ConsControl *cc = (struct ConsControl *)cc_v;
  if (cc->v.k == VVOID) return;
  luaK_exp2nextreg(fs, &cc->v);
  cc->v.k = VVOID;
  if (cc->tostore == LFIELDS_PER_FLUSH) {
    luaK_setlist(fs, cc->t->u.info, cc->na, cc->tostore);
    cc->na += cc->tostore;
    cc->tostore = 0;
  }
}

static void lastlistfield (FuncState *fs, void *cc_v) {
  struct ConsControl *cc = (struct ConsControl *)cc_v;
  if (cc->tostore == 0) return;
  if (hasmultret(cc->v.k)) {
    luaK_setmultret(fs, &cc->v);
    luaK_setlist(fs, cc->t->u.info, cc->na, LUA_MULTRET);
    cc->na--;
  }
  else {
    if (cc->v.k != VVOID)
      luaK_exp2nextreg(fs, &cc->v);
    luaK_setlist(fs, cc->t->u.info, cc->na, cc->tostore);
  }
  cc->na += cc->tostore;
}

static void listfield (LexState *ls, void *cc_v) {
  struct ConsControl *cc = (struct ConsControl *)cc_v;
  expr(ls, &cc->v);
  cc->tostore++;
}

static void recfield (LexState *ls, void *cc_v) {
  struct ConsControl *cc = (struct ConsControl *)cc_v;
  FuncState *fs = ls->fs;
  int reg = ls->fs->freereg;
  expdesc tab, key, val;
  tab = *cc->t;
  if (ls->t.token == TK_NAME) {
    codename(ls, &key);
  }
  else {
    luaX_next(ls);
    expr(ls, &key);
    checknext(ls, ']');
  }
  cc->nh++;
  checknext(ls, '=');
  luaK_exp2val(fs, &key);
  expr(ls, &val);
  luaK_storevar(fs, &key, &val);  /* simplified */
}

/* expressions */
static void simpleexp (LexState *ls, expdesc *v) {
  switch (ls->t.token) {
    case TK_FLT: {
      init_exp(v, VKFLT, 0);
      v->u.nval = ls->t.seminfo.r;
      luaX_next(ls);
      break;
    }
    case TK_INT: {
      init_exp(v, VKINT, 0);
      v->u.ival = ls->t.seminfo.i;
      luaX_next(ls);
      break;
    }
    case TK_STRING: {
      codestring(ls, v, ls->t.seminfo.ts);
      luaX_next(ls);
      break;
    }
    case TK_NIL: {
      init_exp(v, VNIL, 0);
      luaX_next(ls);
      break;
    }
    case TK_TRUE: {
      init_exp(v, VTRUE, 0);
      luaX_next(ls);
      break;
    }
    case TK_FALSE: {
      init_exp(v, VFALSE, 0);
      luaX_next(ls);
      break;
    }
    case TK_DOTS: {
      FuncState *fs = ls->fs;
      check_condition(ls, fs->f->is_vararg, "cannot use '...' outside a vararg function");
      init_exp(v, VVARARG, luaK_codeABCk(fs, OP_VARARG, 0, 0, 1, 0));
      luaX_next(ls);
      break;
    }
    case '{': {
      constructor(ls, v);
      return;
    }
    case TK_FUNCTION: {
      luaX_next(ls);
      body(ls, v, 0, ls->linenumber);
      return;
    }
    default: {
      suffixedexp(ls, v);
      return;
    }
  }
}

static UnOpr getunopr (int op) {
  switch (op) {
    case TK_NOT: return OPR_NOT;
    case '-': return OPR_MINUS;
    case '~': return OPR_BNOT;
    case '#': return OPR_LEN;
    default: return OPR_NOUNOPR;
  }
}

static BinOpr getbinopr (int op) {
  switch (op) {
    case '+': return OPR_ADD;
    case '-': return OPR_SUB;
    case '*': return OPR_MUL;
    case '%': return OPR_MOD;
    case '^': return OPR_POW;
    case '/': return OPR_DIV;
    case TK_IDIV: return OPR_IDIV;
    case '&': return OPR_BAND;
    case '|': return OPR_BOR;
    case '~': return OPR_BXOR;
    case TK_SHL: return OPR_SHL;
    case TK_SHR: return OPR_SHR;
    case TK_CONCAT: return OPR_CONCAT;
    case TK_NE: return OPR_NE;
    case TK_EQ: return OPR_EQ;
    case '<': return OPR_LT;
    case TK_LE: return OPR_LE;
    case '>': return OPR_GT;
    case TK_GE: return OPR_GE;
    case TK_AND: return OPR_AND;
    case TK_OR: return OPR_OR;
    default: return OPR_NOBINOPR;
  }
}

static const struct {
  lu_byte left;
  lu_byte right;
} priority[] = {
  {12, 12}, {12, 12}, {13, 13}, {13, 13}, {13, 13},
  {13, 13}, {13, 13},
  {6, 6}, {4, 4}, {5, 5},
  {7, 7}, {7, 7},
  {9, 8},
  {3, 3}, {3, 3},
  {3, 3}, {3, 3}, {3, 3}, {3, 3},
  {2, 2}, {1, 1},
};

#define UNARY_PRIORITY  14

static BinOpr subexpr (LexState *ls, expdesc *v, unsigned limit) {
  BinOpr op;
  UnOpr uop;
  uop = getunopr(ls->t.token);
  if (uop != OPR_NOUNOPR) {
    int line = ls->linenumber;
    luaX_next(ls);
    subexpr(ls, v, UNARY_PRIORITY);
    luaK_prefix(ls->fs, uop, v, line);
  }
  else simpleexp(ls, v);
  op = getbinopr(ls->t.token);
  while (op != OPR_NOBINOPR && priority[op].left > limit) {
    expdesc v2;
    BinOpr nextop;
    int line = ls->linenumber;
    luaK_infix(ls->fs, op, v);
    luaX_next(ls);
    nextop = subexpr(ls, &v2, priority[op].right);
    luaK_posfix(ls->fs, op, v, &v2, line);
    op = nextop;
  }
  return op;
}

static void expr (LexState *ls, expdesc *v) {
  subexpr(ls, v, 0);
}

/* statements */
static void block (LexState *ls) {
  FuncState *fs = ls->fs;
  BlockCnt bl;
  enterblock(fs, &bl, 0);
  statlist(ls);
  leaveblock(fs);
}

static void statlist (LexState *ls) {
  while (!block_follow(ls, 1)) {
    if (ls->t.token == TK_RETURN) {
      retstat(ls);
      return;
    }
    statement(ls);
  }
}

static int block_follow (LexState *ls, int withuntil) {
  switch (ls->t.token) {
    case TK_ELSE: case TK_ELSEIF:
    case TK_END: case TK_EOS:
      return 1;
    case TK_UNTIL: return withuntil;
    default: return 0;
  }
}

/* assignment statement */
static void check_conflict (LexState *ls, struct LHS_assign *lh,
                            expdesc *v) {
  FuncState *fs = ls->fs;
  int extra = fs->freereg;
  int conflict = 0;
  for (; lh; lh = lh->prev) {
    expdesc *var = &lh->v;
    if (vkisindexed(var->k)) {
      if (var->k == VINDEXED) {
        if (var->u.ind.t == v->u.info) {
          conflict = 1;
          var->u.ind.t = extra;
        }
        if (var->u.ind.idx == v->u.info) {
          conflict = 1;
          var->u.ind.idx = extra;
        }
      }
      else {
        if (var->u.ind.t == v->u.info) {
          conflict = 1;
          var->u.ind.t = extra;
        }
      }
    }
  }
  if (conflict) {
    luaK_codeABCk(fs, OP_MOVE, extra, v->u.info, 0, 0);
    luaK_reserveregs(fs, 1);
  }
}

struct LHS_assign {
  struct LHS_assign *prev;
  expdesc v;
};

static void assignment (LexState *ls, struct LHS_assign *lh, int nvars) {
  expdesc e;
  check_condition(ls, vkisvar(lh->v.k), "syntax error in assignment");
  if (testnext(ls, ',')) {
    struct LHS_assign nv;
    nv.prev = lh;
    suffixedexp(ls, &nv.v);
    if (!vkisindexed(nv.v.k))
      check_conflict(ls, lh, &nv.v);
    checklimit(ls->fs, nvars + ls->dyd->actvar.n, MAXVARS + SHRT_MAX, 
               "variables in assignment");
    assignment(ls, &nv, nvars + 1);
  }
  else {
    int nexps;
    checknext(ls, '=');
    nexps = explist(ls, &e);
    if (nexps != nvars)
      adjust_assign(ls, nvars, nexps, &e);
    else {
      luaK_setoneret(ls->fs, &e);
      luaK_storevar(ls->fs, &lh->v, &e);
      return;
    }
  }
  init_exp(&e, VNONRELOC, ls->fs->freereg - 1);
  luaK_storevar(ls->fs, &lh->v, &e);
}

static int cond (LexState *ls) {
  expdesc v;
  expr(ls, &v);
  if (v.k == VNIL) v.k = VFALSE;
  luaK_goiftrue(ls->fs, &v);
  return v.f;
}

static void gotostat (LexState *ls) {
  /* simplified goto - just skip */
  int line = ls->linenumber;
  TString *name = str_checkname(ls);
  /* add to goto list */
}

static void labelstat (LexState *ls, TString *label, int line) {
  /* simplified label - just record it */
  checknext(ls, TK_DBCOLON);
}

static void whilestat (LexState *ls, int line) {
  FuncState *fs = ls->fs;
  int whileinit;
  int condexit;
  BlockCnt bl;
  luaX_next(ls);
  whileinit = luaK_getlabel(fs);
  condexit = cond(ls);
  enterblock(fs, &bl, 1);
  checknext(ls, TK_DO);
  block(ls);
  luaK_jumpto(fs, whileinit);
  check_condition(ls, ls->t.token == TK_END, "'end' expected");
  luaX_next(ls);
  leaveblock(fs);
  luaK_patchtohere(fs, condexit);
}

static void repeatstat (LexState *ls, int line) {
  int condexit;
  FuncState *fs = ls->fs;
  int repeat_init = luaK_getlabel(fs);
  BlockCnt bl1, bl2;
  enterblock(fs, &bl1, 1);
  enterblock(fs, &bl2, 0);
  luaX_next(ls);
  statlist(ls);
  check_condition(ls, ls->t.token == TK_UNTIL, "'until' expected");
  luaX_next(ls);
  condexit = cond(ls);
  leaveblock(fs);
  if (bl2.upval) {
    int exit = luaK_jump(fs);
    luaK_patchtohere(fs, condexit);
    luaK_codeABCk(fs, OP_CLOSE, reglevel(fs, bl2.nactvar), 0, 0, 0);
    condexit = luaK_jump(fs);
    luaK_patchtohere(fs, exit);
  }
  luaK_patchlist(fs, condexit, repeat_init);
  leaveblock(fs);
}

static void ifstat (LexState *ls, int line) {
  FuncState *fs = ls->fs;
  int flist;
  int escapelist = NO_JUMP;
  flist = test_then_block(ls, &escapelist);
  while (ls->t.token == TK_ELSEIF)
    flist = test_then_block(ls, &escapelist);
  if (testnext(ls, TK_ELSE))
    block(ls);
  check_condition(ls, ls->t.token == TK_END, "'end' expected");
  luaX_next(ls);
  luaK_patchtohere(fs, flist);
  luaK_patchtohere(fs, escapelist);
}

static int test_then_block (LexState *ls, int *escapelist) {
  BlockCnt bl;
  FuncState *fs = ls->fs;
  expdesc v;
  int jf;
  luaX_next(ls);
  expr(ls, &v);
  checknext(ls, TK_THEN);
  if (ls->t.token == TK_GOTO || ls->t.token == TK_BREAK) {
    luaK_goiftrue(ls->fs, &v);
    enterblock(fs, &bl, 0);
    if (ls->t.token == TK_BREAK) {
      luaX_next(ls);
    }
    else {
      gotostat(ls);
    }
    while (!block_follow(ls, 0))
      statement(ls);
    leaveblock(fs);
    return v.f;
  }
  else {
    luaK_goiffalse(ls->fs, &v);
    enterblock(fs, &bl, 0);
    jf = v.t;
  }
  statlist(ls);
  leaveblock(fs);
  if (ls->t.token == TK_ELSE || ls->t.token == TK_ELSEIF) {
    luaK_concat(fs, escapelist, luaK_jump(fs));
  }
  luaK_patchtohere(fs, jf);
  return jf;
}

static void forstat (LexState *ls, int line) {
  FuncState *fs = ls->fs;
  TString *varname;
  BlockCnt bl;
  enterblock(fs, &bl, 1);
  luaX_next(ls);
  varname = str_checkname(ls);
  switch (ls->t.token) {
    case '=': fornum(ls, varname, line); break;
    case ',': case TK_IN: forlist(ls, varname); break;
    default: luaX_syntaxerror(ls, "'=' or 'in' expected");
  }
  check_condition(ls, ls->t.token == TK_END, "'end' expected");
  luaX_next(ls);
  leaveblock(fs);
}

static void fornum (LexState *ls, TString *varname, int line) {
  FuncState *fs = ls->fs;
  int base = fs->freereg;
  newlocalvarliteral(ls, "(for state)");
  newlocalvarliteral(ls, "(for state)");
  newlocalvarliteral(ls, "(for state)");
  newlocalvar(ls, varname);
  checknext(ls, '=');
  exp1(ls);
  checknext(ls, ',');
  exp1(ls);
  if (testnext(ls, ','))
    exp1(ls);
  else {
    luaK_intK(fs, 1);
    luaK_exp2nextreg(fs, &(expdesc){.k=VKINT,.u.ival=1,.t=NO_JUMP,.f=NO_JUMP});
  }
  adjustlocalvars(ls, 3);
  luaK_checkstack(fs, 3);
  forbody(ls, base, line, 1, 1);
}

static int exp1 (LexState *ls) {
  expdesc e;
  expr(ls, &e);
  luaK_exp2nextreg(ls->fs, &e);
  lua_assert(e.k == VNONRELOC);
  return e.u.info;
}

static void forlist (LexState *ls, TString *indexname) {
  FuncState *fs = ls->fs;
  expdesc e;
  int nvars = 4;
  int line;
  int base = fs->freereg;
  newlocalvarliteral(ls, "(for state)");
  newlocalvarliteral(ls, "(for state)");
  newlocalvarliteral(ls, "(for state)");
  newlocalvarliteral(ls, "(for state)");  
  newlocalvar(ls, indexname);
  while (testnext(ls, ',')) {
    newlocalvar(ls, str_checkname(ls));
    nvars++;
  }
  checknext(ls, TK_IN);
  line = ls->linenumber;
  adjust_assign(ls, 3, explist(ls, &e), &e);
  adjustlocalvars(ls, 3);
  luaK_checkstack(fs, 3);
  forbody(ls, base, line, nvars - 3, 0);
}

static void forbody (LexState *ls, int base, int line, int nvars, int isnum) {
  BlockCnt bl;
  FuncState *fs = ls->fs;
  int prep, endfor;
  checknext(ls, TK_DO);
  prep = isnum ? luaK_codeABx(fs, OP_FORPREP, base, 0) : luaK_codeABx(fs, OP_TFORPREP, base, 0);
  enterblock(fs, &bl, 0);
  adjustlocalvars(ls, nvars);
  luaK_reserveregs(fs, nvars);
  block(ls);
  leaveblock(fs);
  luaK_fixline(fs, line);
  endfor = (isnum) ? luaK_codeABx(fs, OP_FORLOOP, base, 0) :
    luaK_codeABCk(fs, OP_TFORCALL, base, 0, nvars, 0);
  if (!isnum)
    luaK_codeABx(fs, OP_TFORLOOP, base, 0);
  luaK_patchlist(fs, endfor, prep + 1);
  luaK_patchtohere(fs, prep);
  if (isnum) {
    int back = luaK_getlabel(fs) - 1;
    SETARG_Bx(fs->f->code[prep], back - prep);
  }
}

static void funcstat (LexState *ls, int line) {
  expdesc v, b;
  luaX_next(ls);
  funcname(ls, &v);
  body(ls, &b, 0, line);
  check_condition(ls, vkisvar(v.k), "invalid function name");
  luaK_storevar(ls->fs, &v, &b);
  luaK_fixline(ls->fs, line);
}

static void funcname (LexState *ls, expdesc *v) {
  int ismethod = 0;
  singlevar(ls, v);
  while (ls->t.token == '.') {
    luaX_next(ls);
    expdesc key;
    codename(ls, &key);
    luaK_indexed(ls->fs, v, &key);
  }
  if (ls->t.token == ':') {
    ismethod = 1;
    luaX_next(ls);
    expdesc key;
    codename(ls, &key);
    luaK_self(ls->fs, v, &key);
  }
  if (ismethod) {
    /* add implicit 'self' parameter */
  }
}

static void localfunc (LexState *ls) {
  expdesc b;
  FuncState *fs = ls->fs;
  int fvar = fs->nactvar;
  newlocalvar(ls, str_checkname(ls));
  init_exp(&b, VLOCAL, fs->freereg);
  b.u.var.ridx = cast_byte(fs->freereg);
  luaK_reserveregs(fs, 1);
  adjustlocalvars(ls, 1);
  body(ls, &b, 0, ls->linenumber);
  adjustlocalvars(ls, 0);
  luaK_fixline(fs, ls->linenumber);
}

static int getlocalattribute (LexState *ls) {
  if (testnext(ls, '<')) {
    const char *attr = getstr(str_checkname(ls));
    checknext(ls, '>');
    if (strcmp(attr, "close") == 0)
      return RDKTOCLOSE;
    else if (strcmp(attr, "const") == 0)
      return RDKCONST;
    else
      luaK_semerror(ls, luaO_pushfstring(ls->L,
        "unknown attribute '%s'", attr));
  }
  return VDKREG;
}

static void localstat (LexState *ls) {
  FuncState *fs = ls->fs;
  int toclose = -1;
  Vardesc *var;
  int vidx;
  int nvars = 0;
  int nexps;
  expdesc e;
  do {
    int attr;
    TString *name = str_checkname(ls);
    attr = getlocalattribute(ls);
    newlocalvar(ls, name);
    vidx = fs->nactvar + nvars - 1;
    if (attr == RDKTOCLOSE) {
      if (toclose != -1)
        luaK_semerror(ls, "multiple to-be-closed variables in local list");
      toclose = nvars - 1;
    }
    nvars++;
  } while (testnext(ls, ','));
  if (testnext(ls, '='))
    nexps = explist(ls, &e);
  else {
    e.k = VVOID;
    nexps = 0;
  }
  adjust_assign(ls, nvars, nexps, &e);
  adjustlocalvars(ls, nvars);
  if (toclose != -1) {
    fs->bl->insidetbc = 1;
    luaK_codeABCk(fs, OP_TBC, reglevel(fs, fs->nactvar - nvars + toclose), 0, 0, 0);
  }
}

static void exprstat (LexState *ls) {
  FuncState *fs = ls->fs;
  struct LHS_assign v;
  suffixedexp(ls, &v.v);
  if (ls->t.token == '=' || ls->t.token == ',') {
    v.prev = NULL;
    assignment(ls, &v, 1);
  }
  else {
    check_condition(ls, v.v.k == VCALL, "syntax error");
    SETARG_C(*(&fs->f->code[v.v.u.info]), 1);
  }
}

static void retstat (LexState *ls) {
  FuncState *fs = ls->fs;
  expdesc e;
  int nret;
  int first = luaY_nvarstack(fs);
  if (block_follow(ls, 1) || ls->t.token == ';')
    nret = 0;
  else {
    nret = explist(ls, &e);
    if (hasmultret(e.k)) {
      luaK_setmultret(fs, &e);
      if (e.k == VCALL && nret == 1 && !ls->fs->bl->insidetbc) {
        SETARG_A(fs->f->code[e.u.info], first);
        SET_OPCODE(fs->f->code[e.u.info], OP_TAILCALL);
        lua_assert(GETARG_A(fs->f->code[e.u.info]) == luaY_nvarstack(fs));
      }
      nret = LUA_MULTRET;
    }
    else {
      if (nret == 1)
        first = luaK_exp2anyreg(fs, &e);
      else {
        luaK_exp2nextreg(fs, &e);
        first = fs->freereg - nret;
        lua_assert(nret == fs->freereg - first);
      }
    }
  }
  luaK_ret(fs, first, nret);
  testnext(ls, ';');
}

static void statement (LexState *ls) {
  int line = ls->linenumber;
  luaC_checkGC(ls->L);
  switch (ls->t.token) {
    case TK_IF: {
      ifstat(ls, line);
      break;
    }
    case TK_WHILE: {
      whilestat(ls, line);
      break;
    }
    case TK_DO: {
      luaX_next(ls);
      block(ls);
      check_condition(ls, ls->t.token == TK_END, "'end' expected");
      luaX_next(ls);
      break;
    }
    case TK_FOR: {
      forstat(ls, line);
      break;
    }
    case TK_REPEAT: {
      repeatstat(ls, line);
      break;
    }
    case TK_FUNCTION: {
      funcstat(ls, line);
      break;
    }
    case TK_LOCAL: {
      luaX_next(ls);
      if (testnext(ls, TK_FUNCTION))
        localfunc(ls);
      else
        localstat(ls);
      break;
    }
    case TK_RETURN: {
      luaX_next(ls);
      retstat(ls);
      break;
    }
    case TK_BREAK: {
      luaX_next(ls);
      /* simplified break handling */
      {
        FuncState *fs = ls->fs;
        luaK_jump(fs);
      }
      break;
    }
    case TK_GOTO: {
      luaX_next(ls);
      gotostat(ls);
      break;
    }
    case TK_DBCOLON: {
      luaX_next(ls);
      TString *label = str_checkname(ls);
      labelstat(ls, label, line);
      break;
    }
    case ';': {
      luaX_next(ls);
      break;
    }
    default: {
      exprstat(ls);
      break;
    }
  }
}

/* function bodies */
static void parlist (LexState *ls) {
  FuncState *fs = ls->fs;
  Proto *f = fs->f;
  int nparams = 0;
  f->is_vararg = 0;
  if (ls->t.token != ')') {
    do {
      switch (ls->t.token) {
        case TK_NAME: {
          newlocalvar(ls, str_checkname(ls));
          nparams++;
          break;
        }
        case TK_DOTS: {
          luaX_next(ls);
          f->is_vararg = 1;
          break;
        }
        default: luaX_syntaxerror(ls, "'...' or <name> expected");
      }
    } while (!f->is_vararg && testnext(ls, ','));
  }
  adjustlocalvars(ls, nparams);
  f->numparams = cast_byte(fs->nactvar);
  luaK_reserveregs(fs, fs->nactvar);
}

static void body (LexState *ls, expdesc *e, int ismethod, int line) {
  FuncState new_fs;
  BlockCnt bl;
  new_fs.f = addprototype(ls);
  new_fs.f->linedefined = line;
  open_func(ls, &new_fs, &bl);
  checknext(ls, '(');
  if (ismethod) {
    newlocalvarliteral(ls, "self");
    adjustlocalvars(ls, 1);
  }
  parlist(ls);
  checknext(ls, ')');
  statlist(ls);
  new_fs.f->lastlinedefined = ls->linenumber;
  check_condition(ls, ls->t.token == TK_END, "'end' expected");
  luaX_next(ls);
  codeclosure(ls, e);
  close_func(ls);
}

static Proto *addprototype (LexState *ls) {
  Proto *clp;
  lua_State *L = ls->L;
  FuncState *fs = ls->fs;
  Proto *f = fs->f;
  if (fs->np >= f->sizep) {
    int oldsize = f->sizep;
    luaM_growvector(L, f->p, fs->np, f->sizep, Proto *, MAXARG_Bx, "functions");
    while (oldsize < f->sizep)
      f->p[oldsize++] = NULL;
  }
  f->p[fs->np++] = clp = luaF_newproto(L);
  luaC_objbarrier(L, f, clp);
  return clp;
}

static void codeclosure (LexState *ls, expdesc *v) {
  FuncState *fs = ls->fs->prev;
  init_exp(v, VRELOC, luaK_codeABx(fs, OP_CLOSURE, 0, fs->np - 1));
  luaK_exp2nextreg(fs, v);
}

static void open_func (LexState *ls, FuncState *fs, BlockCnt *bl) {
  Proto *f = fs->f;
  fs->prev = ls->fs;
  fs->ls = ls;
  ls->fs = fs;
  fs->pc = 0;
  fs->previousline = 0;
  fs->iwthabs = 0;
  fs->lasttarget = 0;
  fs->freereg = 0;
  fs->nk = 0;
  fs->nabslineinfo = 0;
  fs->np = 0;
  fs->nups = 0;
  fs->ndebugvars = 0;
  fs->nactvar = 0;
  fs->needclose = 0;
  fs->firstlocal = ls->dyd->actvar.n;
  fs->firstlabel = ls->dyd->label.n;
  fs->bl = NULL;
  f->source = ls->source;
  luaC_objbarrier(ls->L, f, f->source);
  f->maxstacksize = 2;
  enterblock(fs, bl, 0);
}

static void close_func (LexState *ls) {
  lua_State *L = ls->L;
  FuncState *fs = ls->fs;
  Proto *f = fs->f;
  luaK_ret(fs, luaY_nvarstack(fs), 0);
  leaveblock(fs);
  lua_assert(fs->bl == NULL);
  luaK_finish(fs);
  /* final adjustments to Proto */
  luaM_shrinkvector_(L, f->code, &f->sizecode, fs->pc, sizeof(Instruction));
  luaM_shrinkvector_(L, f->lineinfo, &f->sizelineinfo, fs->pc, sizeof(ls_byte));
  luaM_shrinkvector_(L, f->abslineinfo, &f->sizeabslineinfo, fs->nabslineinfo, sizeof(AbsLineInfo));
  luaM_shrinkvector_(L, f->k, &f->sizek, fs->nk, sizeof(TValue));
  luaM_shrinkvector_(L, f->p, &f->sizep, fs->np, sizeof(Proto *));
  luaM_shrinkvector_(L, f->locvars, &f->sizelocvars, fs->ndebugvars, sizeof(LocVar));
  luaM_shrinkvector_(L, f->upvalues, &f->sizeupvalues, fs->nups, sizeof(Upvaldesc));
  ls->fs = fs->prev;
}

/* main parser entry point */
LClosure *luaY_parser (lua_State *L, ZIO *z, Mbuffer *buff, Dyndata *dyd,
                       const char *name, int firstchar) {
  LexState lexstate;
  FuncState funcstate;
  LClosure *cl = luaF_newLclosure(L, 1);
  setclLvalue2s(L, L->top, cl);
  api_incr_top(L);
  funcstate.f = cl->p = luaF_newproto(L);
  luaC_objbarrier(L, cl, cl->p);
  funcstate.f->source = luaS_new(L, name);
  luaC_objbarrier(L, funcstate.f, funcstate.f->source);
  lexstate.buff = buff;
  lexstate.dyd = dyd;
  dyd->actvar.n = dyd->gt.n = dyd->label.n = 0;
  luaX_setinput(L, &lexstate, z, funcstate.f->source, firstchar);
  {
    BlockCnt bl;
    open_func(&lexstate, &funcstate, &bl);
    funcstate.f->is_vararg = 1;
    luaX_next(&lexstate);
    statlist(&lexstate);
    check(&lexstate, TK_EOS);
    close_func(&lexstate);
  }
  lua_assert(!funcstate.prev && funcstate.nups == 1 && !lexstate.fs);
  lua_assert(dyd->actvar.n == 0 && dyd->gt.n == 0 && dyd->label.n == 0);
  L->top--;
  return cl;
}

