# precall for Lua functions returns 1
# luaD_call: if (!precall(L, func, nResults)) -> if (!1) -> if (0) -> DON'T execute!
# 
# THAT'S THE BUG! precall returns 1 for Lua functions, meaning "needs execution"
# But luaD_call does: if (!precall(...)) { luaV_execute }
# 
# !precall = !1 = 0 = false -> luaV_execute is NEVER called!
# 
# The fix: luaD_call should call luaV_execute when precall returns 1

python3 << 'EOF'
with open('/workspace/src/ldo.c', 'r') as f:
    content = f.read()

old = '''void luaD_call (lua_State *L, StkId func, int nResults) {
  luaE_incCstack(L);
  if (!precall(L, func, nResults)) {
    luaV_execute(L, L->ci);
  }
  decCcalls(L);
}'''

new = '''void luaD_call (lua_State *L, StkId func, int nResults) {
  luaE_incCstack(L);
  if (precall(L, func, nResults))  /* is it a Lua function? */
    luaV_execute(L, L->ci);  /* call it */
  decCcalls(L);
}'''

content = content.replace(old, new)

with open('/workspace/src/ldo.c', 'w') as f:
    f.write(content)
print("Fixed luaD_call")
EOF

