# Still hanging! Even with the fix. Let me check the OP_RETURN behavior.
# 
# When OP_RETURN is executed:
# luaD_poscall(L, ci, n) is called
# Then: if (ci->callstatus & CIST_FRESH) return;
# else { ci = L->ci; if (isLua(ci)) goto startfunc; return; }
# 
# CIST_FRESH is never set in our code!
# So we go to else:
# ci = L->ci  (after poscall, L->ci = ci->previous)
# if (isLua(ci)) goto startfunc;
# This means we jump back to start and execute the PREVIOUS function's bytecode!
# 
# When called from the C API:
# base_ci (the bottom ci) has callstatus = CIST_C (not Lua)
# So isLua(base_ci) = false
# We return from luaV_execute
# 
# But then luaD_call returns, and... nothing.
# The pcall should have captured the result.
# 
# Actually the infinite loop is probably because:
# After OP_RETURN, we get the previous ci
# ci = L->ci = base_ci with CIST_C
# isLua(ci) = false -> return
# 
# But we returned! So why is it looping?
# 
# Let me add printf to trace the return path

