# The result should be at stack[1] but it's nil!
# func was at offset 16 = stack[1] (each StackValue is 16 bytes)
# 
# Before call: L->top=2 (stack[0] = nil (base), stack[1] = function)
# After call: L->top=2 but the value at stack[1] is nil
# 
# In luaD_poscall:
# ci->func = &stack[1] (the function slot)
# firstres = L->top - nres = &stack[2-1] = &stack[1]
# 
# Wait! If L->top=2 and nres=1, firstres = &stack[1]
# The result is at firstres[0] = stack[1]
# We copy firstres[0] to ci->func = stack[1]
# That's the same position!
# 
