static int my_pkg_open(lua_State *L) {
  printf("start\n"); fflush(stdout);

  luaL_newmetatable(L, "LOADLIB");
  lua_pop(L, 1);
  printf("metatable done\n"); fflush(stdout);

  lua_createtable(L, 0, 2);
  printf("created lib table\n"); fflush(stdout);

  /* createclibstable */
  luaL_getsubtable(L, LUA_REGISTRYINDEX, LUA_LOADED_TABLE);
  lua_setfield(L, -2, "loaded");
  luaL_getsubtable(L, LUA_REGISTRYINDEX, LUA_PRELOAD_TABLE);
  lua_setfield(L, -2, "preload");
  printf("created lib tables\n"); fflush(stdout);

  /* set path/cpath */
  lua_pushstring(L, LUA_PATH_DEFAULT);
  lua_setfield(L, -2, "path");
  lua_pushstring(L, LUA_CPATH_DEFAULT);
  lua_setfield(L, -2, "cpath");
