# lua_setfield(L, -2, fname) sets slot -2.field = slot -1.
# Slot -1 = io_table copy.
# Slot -2 = io_table itself!
# So io_table.stdin = io_table! (circular reference)
# 
# THEN the io_table copy is left on the stack!
# Stack: [..., io_table, io_table_copy_from_setfield]
# 
# Wait, lua_setfield POPS the value at -1, not the field.
# lua_setfield(L, -2, fname):
# - Gets table at index -2 (NOT -1!)
# - Pops value at -1 (the io_table copy)
# - Sets table[-2].fname = io_table_copy
# 
# But the table at -2 is ALSO the io_table! (io_table = stack at -1 before setfield)
# No wait: after lua_setfield(registry, iokey) pops the userdata,
# the stack is [..., io_table]. io_table is now at top (-1).
# 
# lua_pushvalue(L, -1) -> stack: [..., io_table, io_table_copy]
# lua_setfield(L, -2, fname) -> index -2 is io_table, set io_table.fname = io_table_copy
# Stack after: [..., io_table] (io_table_copy was popped)
