# freereg(fs, reg): if reg >= nvarstack, freereg--
# 
# For VINDEXSTR: e->u.ind.t = table register
# If e->u.ind.t >= nvarstack (0), then freereg--!
# freereg was 0 -> freereg-- = lu_byte(0) - 1 = 255!
# 
# THAT'S THE BUG!
# 
# For "print" resolved as _ENV["print"] = VINDEXSTR:
# e->u.ind.t is the REGISTER containing _ENV
# 
# But wait: for a global lookup, print is found via:
# 1. Not in local vars
# 2. singlevaraux: not found in local, found in upvalues? Or _ENV?
# 3. Gets resolved to VUPVAL (the _ENV upvalue is index 0 in the function)
# 4. luaK_indexed makes it VINDEXSTR (since key is a string)
# 
# For VINDEXSTR: ind.t = table register (where _ENV was copied to)
# But wait: if the table is an UPVALUE (VUPVAL), after luaK_indexed it becomes VINDEXUP!
# 
# Let me trace: singlevar:
# 1. searchvar: not found
# 2. singlevaraux(nil): VVOID
# 3. So we look for _ENV:
# singlevaraux(fs, ls->envn, var, 1) -> finds _ENV as VUPVAL[0]
# 
# Then: codestring(ls, &key, varname) -> key = VKSTR
# luaK_indexed(fs, var, &key) where var is VUPVAL[0]
# 
# In luaK_indexed:
# if k->k == VKSTR && luaK_isKstr:
#   t->u.ind.idx = str (K index)
#   if t->k == VUPVAL -> t->k = VINDEXUP (not VINDEXSTR!)
# 
# So it should be VINDEXUP (13), not VINDEXSTR (15)!
# But the trace shows v->k = 15 = VINDEXSTR!
# 
# This means singlevar is NOT resolving "print" to VINDEXUP.
# Maybe the upvalue index is wrong, or the lookup path is different.
# 
# Let me add trace to singlevaraux:

python3 << 'EOF'
with open('/workspace/src/lparser.c', 'r') as f:
    content = f.read()

old = '''static void singlevar (LexState *ls, expdesc *var) {
  TString *varname = str_checkname(ls);
  FuncState *fs = ls->fs;
  if (singlevaraux(fs, varname, var, 1) == VVOID) {
    expdesc key;
    singlevaraux(fs, ls->envn, var, 1);
    lua_assert(var->k == VLOCAL || var->k == VUPVAL);
    codestring(ls, &key, varname);
    luaK_indexed(fs, var, &key);
  }
}'''

new = '''static void singlevar (LexState *ls, expdesc *var) {
  TString *varname = str_checkname(ls);
  FuncState *fs = ls->fs;
  fprintf(stderr, "singlevar: looking up '%s'\\n", getstr(varname)); fflush(stderr);
  if (singlevaraux(fs, varname, var, 1) == VVOID) {
    expdesc key;
    fprintf(stderr, "  not found, using _ENV\\n"); fflush(stderr);
    singlevaraux(fs, ls->envn, var, 1);
    fprintf(stderr, "  _ENV: var->k=%d\\n", var->k); fflush(stderr);
    lua_assert(var->k == VLOCAL || var->k == VUPVAL);
    codestring(ls, &key, varname);
    luaK_indexed(fs, var, &key);
    fprintf(stderr, "  after indexed: var->k=%d\\n", var->k); fflush(stderr);
  }
}'''

content = content.replace(old, new)

with open('/workspace/src/lparser.c', 'w') as f:
    f.write(content)
print("Added singlevar trace")
EOF

