# Still "_ENV: var->k=0" = VVOID!
# The fix didn't work. Let me check why.
# 
# After adding _ENV upvalue, searchupvalue should find it.
# But singlevaraux goes:
# searchvar(fs, "_ENV", var) -> not found (it's an upvalue, not a local)
# singlevaraux(fs->prev=NULL, "_ENV", var, 0) -> VVOID (no parent)
# Returns VVOID
# 
# This is WRONG because the code should find "_ENV" as an upvalue.
# In the original Lua:
# singlevaraux checks if the name is ALREADY an upvalue of the current function:
# Actually looking at the code: searchvar checks LOCAL variables only.
# The upvalue lookup is done via singlevaraux on the PARENT.
# 
# For the MAIN FUNCTION: fs->prev = NULL.
# So when we look for "_ENV" in the main function:
# 1. searchvar: not found (it's not a local)
# 2. singlevaraux(NULL, "_ENV"): returns VVOID
# 3. So we return VVOID!
# 
# But _ENV IS an upvalue of the main function!
# The original Lua handles this by adding searchupvalue to singlevaraux.
# 
# Actually I think the issue is that singlevaraux should also check
# the CURRENT function's upvalues! Not just parent's locals.
# 
# Looking at the Lua 5.4 source for singlevaraux:
# static int singlevaraux (FuncState *fs, TString *n, expdesc *var, int base) {
#   if (fs == NULL) {
#     init_exp(var, VVOID, 0);
#     return VVOID;
#   }
#   else {
#     int v = searchvar(fs, n, var);
#     if (v >= 0) {
#       ...
#     }
#     else {
#       if (singlevaraux(fs->prev, n, var, 0) == VVOID)
#         return VVOID;
#       ...
#     }
#   }
# }
# 
# For the MAIN function:
# singlevaraux(main_fs, "_ENV", var, 1)
# -> searchvar: not found
# -> singlevaraux(main_fs->prev=NULL, "_ENV", var, 0)
#    -> returns VVOID
# -> returns VVOID!
# 
# This means the original Lua ALSO would return VVOID for _ENV!
# Unless... the original Lua has _ENV as a LOCAL variable (register 0)?
# 
# Actually in the original Lua:
# When the main chunk is compiled, _ENV is added as a pseudo-local variable
# before compilation starts. So searchvar DOES find it as a local!
# 
# The fix: add "_ENV" as an upvalue that is IN STACK (a pseudo-local).
# 
# Actually in Lua 5.4, _ENV is set up as a "local" variable in a special way.
# Let me check the original f_parser:
# After setting up the funcstate, it calls:
# adjustlocalvars(ls, 1);  <- marks var 0 as active
# luaK_reserveregs(fs, 1); <- reserves register 0 for _ENV
# 
# So _ENV is at register 0 and is an active local!
# 
# Then when we search for _ENV: searchvar finds it at register 0!
# And returns VLOCAL with info = 0.
# 
# Then singlevar's call to singlevaraux(fs, ls->envn, var, 1):
# searchvar finds "_ENV" -> VLOCAL at register 0
# Since base=1 (outer call), we return VLOCAL directly!
# 
# Then luaK_indexed with VLOCAL table -> VINDEXSTR (correct!)
# And VINDEXSTR.t = 0 (register 0 = _ENV)
# 
# freereg(fs, 0) in VINDEXSTR discharge:
# if (0 >= luaY_nvarstack(fs)): 0 >= 1 (since _ENV is var 0, nvarstack=1)?
# 
# Wait: luaY_nvarstack counts active variables by register.
# If _ENV is at register 0 and is active (nactvar >= 1):
# reglevel(fs, nactvar) = reglevel(fs, 1) -> returns ridx of var 0 + 1 = 1
# 
# So nvarstack = 1.
# freereg(fs, 0): 0 >= 1? FALSE -> freereg-- does NOT happen!
# 
# THE FIX: We need to add _ENV as an ACTIVE LOCAL VARIABLE (not just upvalue).

python3 << 'EOF'
with open('/workspace/src/lparser.c', 'r') as f:
    content = f.read()

# Fix: after open_func, add _ENV as a local variable at register 0
old = '''    open_func(&lexstate, &funcstate, &bl);
    funcstate.f->is_vararg = 1;
    /* set up _ENV as upvalue[0] of the main function */
    {
      TString *envn = lexstate.envn;
      Upvaldesc *up;
      luaM_growvector(L, funcstate.f->upvalues, funcstate.nups, 
                      funcstate.f->sizeupvalues, Upvaldesc, MAXUPVAL, "upvalues");
      up = &funcstate.f->upvalues[funcstate.nups];
      up->instack = 1;  /* _ENV is on the stack (register 0 of the enclosing chunk) */
      up->idx = 0;      /* stack index 0 */
      up->kind = VDKREG;
      up->name = envn;
      luaC_objbarrier(L, funcstate.f, envn);
      funcstate.nups = 1;
    }
    luaX_next(&lexstate);'''

new = '''    open_func(&lexstate, &funcstate, &bl);
    funcstate.f->is_vararg = 1;
    /* set up _ENV as upvalue[0] of the main function */
    /* In Lua, _ENV is a local variable (on the stack) that becomes upvalue[0] */
    {
      expdesc env_var;
      /* Create _ENV as a local variable (for searching purposes) */
      newlocalvar(&lexstate, lexstate.envn);
      adjustlocalvars(&lexstate, 1);
      luaK_reserveregs(&funcstate, 1);  /* register 0 for _ENV */
      /* Set up the upvalue record */
      luaM_growvector(L, funcstate.f->upvalues, funcstate.nups, 
                      funcstate.f->sizeupvalues, Upvaldesc, MAXUPVAL, "upvalues");
      funcstate.f->upvalues[0].instack = 1;
      funcstate.f->upvalues[0].idx = 0;
      funcstate.f->upvalues[0].kind = VDKREG;
      funcstate.f->upvalues[0].name = lexstate.envn;
      luaC_objbarrier(L, funcstate.f, lexstate.envn);
      funcstate.nups = 1;
    }
    luaX_next(&lexstate);'''

content = content.replace(old, new)

with open('/workspace/src/lparser.c', 'w') as f:
    f.write(content)
print("Fixed _ENV setup: add as local var")
EOF

