# The fix: exp2nextreg for VRELOC should use the already-allocated slot
# without calling reserveRegs again.

# Current exp2nextreg:
# luaK_dischargevars
# freeexp
# luaK_reserveregs(1)  <- always reserves a new slot
# exp2reg(e, freereg - 1)

# The CORRECT behavior:
# For VRELOC: the instruction was already emitted, with a slot reserved by the emitter.
# The slot is freereg - 1 (the last allocated slot).
# So: don't call reserveRegs for VRELOC.

# But this would break non-VRELOC cases. Let me see:
# For VKINT, VKFLT etc.: no slot is reserved. We need reserveRegs.
# For VLOCAL, VNONRELOC: already has a register. freeexp frees it, we need a new one.
# For VRELOC: instruction emitted, slot reserved by emitter. Don't need new one.

# The fix: check if e->k == VRELOC, and if so, skip reserveRegs:

python3 << 'EOF'
with open('/workspace/src/lcode.c', 'r') as f:
    content = f.read()

old = '''void luaK_exp2nextreg (FuncState *fs, expdesc *e) {
  luaK_dischargevars(fs, e);
  freeexp(fs, e);
  luaK_reserveregs(fs, 1);
  exp2reg(fs, e, fs->freereg - 1);
}'''

new = '''void luaK_exp2nextreg (FuncState *fs, expdesc *e) {
  luaK_dischargevars(fs, e);
  freeexp(fs, e);
  if (e->k != VRELOC) {
    /* For non-VRELOC: we need to allocate a new register */
    luaK_reserveregs(fs, 1);
  }
  /* For VRELOC: the register was already allocated (e.g., by constructor's reserveRegs) */
  exp2reg(fs, e, fs->freereg - 1);
}'''

content = content.replace(old, new)

with open('/workspace/src/lcode.c', 'w') as f:
    f.write(content)
print("Fixed exp2nextreg for VRELOC")
EOF

