# what the correct bytecode should be.
# 
# In our VM (lvm.c), OP_EQI:
# case OP_EQI: {
#   int imm = GETARG_sB(i);
#   int cond;
#   if (ttisinteger(s2v(ra))) cond = (ivalue(s2v(ra)) == imm);
#   else if (ttisfloat(s2v(ra))) cond = luai_numeq(fltvalue(s2v(ra)), cast_num(imm));
#   else cond = 0;
#   if (cond != GETARG_k(i)) pc++;
#   else pc += GETARG_sJ(*pc) + 1;
#   break;
# }
# 
# For EQI A=1 sB=1 k=0:
# cond = (1 == 1) = 1
# k = 0
# cond != k: 1 != 0 = TRUE -> pc++ (skip next)
# 
# So TRUE skips the next instruction (JMP at pc=3).
# FALSE executes JMP (jumps to some target).
# 
# After skipping JMP (TRUE case): we execute [4] LOADFALSE?
# But wait: the bytecode shows:
# [4] LOADFALSE A=1
# [5] LFALSESKIP A=1
# 
# After LOADFALSE: R[1] = false. 
# Then LFALSESKIP? LFALSESKIP loads false AND skips next. But why would we need that?
# 
# The correct Lua 5.4 pattern for boolean is:
# LFALSESKIP A = load false into R[A], then skip next instruction
# LOADTRUE A = load true into R[A]
# 
# Used AFTER a test instruction:
# TEST (if TRUE: skip LFALSESKIP -> execute LOADTRUE)
# TEST (if FALSE: execute LFALSESKIP, skip LOADTRUE -> result = false)
# 
# For EQI with k=0 (skip if equal=TRUE):
# EQI TRUE -> skip -> execute LOADTRUE
# EQI FALSE -> don't skip -> execute LFALSESKIP (load false, skip LOADTRUE)
# 
# Wait NO: our VM shows "if cond != k: pc++" where pc++ means SKIP.
# For k=0, cond=1 (TRUE): 1!=0 -> pc++ -> SKIP JMP
# So TRUE SKIPS next, FALSE DOESN'T SKIP.
# 
# The correct pattern:
# [2] EQI k=0 (skip if TRUE)
# [3] JMP to FALSE_CODE
# [4] TRUE_CODE: LOADTRUE A=1
# [5] JMP past FALSE_CODE (optional)
# [6] FALSE_CODE: LOADFALSE A=1
# 
# OR simpler:
# [2] EQI k=0 (skip if TRUE)
# [3] LFALSESKIP A=1 (only executed if FALSE -> load false, skip LOADTRUE)
# [4] LOADTRUE A=1 (executed if TRUE, since JMP was skipped)
# 
