actions.command:
# EQI now has: if (cond != k) pc++; (no else)
# This is correct for LFALSESKIP/LOADTRUE pattern.
# 
# But for "if 1==1 then ... end":
# EQI TRUE -> pc++ (skip JMP... wait, there IS no JMP now!)
# We only emit LFALSESKIP/LOADTRUE when the EQI is used as a VALUE.
# But for the "if" statement, we use jumponcond which emits TEST + JMP.
# EQI is only used when "1==1" is used as a value (in boolean context).
# 
# For "if 1==1 then ... end":
# The condition is evaluated via subexpr -> codeeq -> e1->k=VJMP
# goiffalse(v) -> switch(VJMP) -> pc = e->u.info (EQI PC)
# luaK_concat(&v.t, pc=EQI_PC)
# patchtohere(v.f = NO_JUMP) -> nothing
# jf = v.t = EQI_PC
# 
# Then ifstat calls patchtohere(jf=EQI_PC)!
# getjump(fs, EQI_PC) reads code[EQI_PC] = EQI instruction.
# GETARG_sJ(EQI) = GARBAGE (EQI is not isJ format)!
# 
# THE BUG: when the comparison result (VJMP) is used in an "if" statement,
# goiffalse stores the EQI PC in v.t.
# Then patchtohere tries to follow the "jump chain" starting from the EQI PC.
# But EQI is not a jump, so getjump reads garbage.
# 
# THE FIX: For "if" statements that use comparison results,
# goiffalse should emit a JMP after the EQI.
# 
# In goiffalse with VJMP:
# case VJMP: {
#   pc = e->u.info;  <- pc = EQI instruction PC
#   break;
# }
# luaK_concat(&e->t, pc)  <- adds EQI to the "true" jump list
# 
# Then patchtohere(e->t = EQI_PC) tries to patch the EQI as a jump!
# 
# For the "if" statement to work correctly, we need a PROPER JMP instruction
# in the jump list.
# 
# THE SOLUTION: In goiffalse for VJMP, instead of using the VJMP instruction PC,
# emit a NEW JMP instruction after the test:
# EQI ...
# JMP (placeholder) <- this is what we add to the jump list
# 
# OR: Change patchtohere to handle test instructions differently.
# 
# Actually: the CLEANEST solution is to add a JMP after the comparison
# in the VJMP case of goiffalse.

python3 << 'EOF'
with open('/workspace/src/lcode.c', 'r') as f:
    content = f.read()

# Fix goiffalse for VJMP: emit a JMP after the test instruction
old = '''void luaK_goiffalse (FuncState *fs, expdesc *e) {
  int pc;
  luaK_dischargevars(fs, e);
  switch (e->k) {
    case VJMP: {
      pc = e->u.info;
      break;
    }
    case VNIL: case VFALSE: {
      pc = NO_JUMP;
      break;
    }
    default: {
      pc = jumponcond(fs, e, 1);
      break;
    }
  }
  luaK_concat(fs, &e->t, pc);
  luaK_patchtohere(fs, e->f);
  e->f = NO_JUMP;
}'''

new = '''void luaK_goiffalse (FuncState *fs, expdesc *e) {
  int pc;
  luaK_dischargevars(fs, e);
  switch (e->k) {
    case VJMP: {
      /* Test instruction (EQI, LTI, etc.): emit a JMP after it for the jump chain */
      /* EQI condition TRUE -> skip JMP; condition FALSE -> take JMP (to skip body) */
      pc = luaK_jump(fs);  /* emit JMP and return JMP pc for jump list */
      /* Note: e->u.info holds the test instruction PC, pc holds the JMP PC */
      /* The test instruction's k already handles the "skip" behavior */
      break;
    }
    case VNIL: case VFALSE: {
      pc = NO_JUMP;
      break;
    }
    default: {
      pc = jumponcond(fs, e, 1);
      break;
    }
  }
  luaK_concat(fs, &e->t, pc);
  luaK_patchtohere(fs, e->f);
  e->f = NO_JUMP;
}'''

content = content.replace(old, new)

# Also fix luaK_goiftrue for VJMP:
old2 = '''void luaK_goiftrue (FuncState *fs, expdesc *e) {
  int pc;
  luaK_dischargevars(fs, e);
  switch (e->k) {
    case VJMP: {
      invertjump(fs, e);
      pc = e->u.info;
      break;
    }'''

new2 = '''void luaK_goiftrue (FuncState *fs, expdesc *e) {
  int pc;
  luaK_dischargevars(fs, e);
  switch (e->k) {
    case VJMP: {
      invertjump(fs, e);
      /* Test instruction: emit a JMP for the jump chain */
      pc = luaK_jump(fs);
      break;
    }'''

content = content.replace(old2, new2)

with open('/workspace/src/lcode.c', 'w') as f:
    f.write(content)
print("Fixed goiffalse/goiftrue for VJMP")
EOF

cd /workspace/src && gcc -I. -DLUA_USE_LINUX -g -o /tmp/lua_test \
  lapi.c lauxlib.c lbaselib.c lcorolib.c lctype.c ldblib.c ldebug.c \
  ldo.c ldump.c lfunc.c lgc.c linit.c liolib.c llex.c lmathlib.c \
  lmem.c loadlib.c lobject.c lopcodes.c loslib.c lparser.c lstate.c \
  lstring.c lstrlib.c ltable.c ltablib.c ltm.c lua.c lundump.c lutf8lib.c \
  lvm.c lzio.c lcode.c \
  -lm -ldl 2>&1 | grep "error:" | head -3

